INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e5eaebc6-dd82-5758-a3e7-198f5b8e8601', '32eba658-8aac-5cd5-ac4e-0ccce652774d', NULL, 22, 22, 'David swore to Saul. Saul went home; but David and his men went up to the stronghold.'),
  ('6cf3ade3-baeb-5a16-a478-031c970bfff7', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 1, 1, 'Samuel died; and all Israel gathered themselves together, and lamented him, and buried him in his house at Ramah. David arose, and went down to the wilderness of Paran.'),
  ('ad9951e9-f3a6-51d3-a631-1a4df7a09e3d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 2, 2, 'There was a man in Maon, whose possessions were in Carmel; and the man was very great, and he had three thousand sheep, and a thousand goats: and he was shearing his sheep in Carmel.'),
  ('3f6a8584-d863-5744-a325-23be9c528d2c', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 3, 3, 'Now the name of the man was Nabal; and the name of his wife Abigail; and the woman was of good understanding, and of a beautiful face: but the man was churlish and evil in his doings; and he was of the house of Caleb.'),
  ('c7e78f19-aa18-5fb5-abd3-78fda529c7e5', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 4, 4, 'David heard in the wilderness that Nabal was shearing his sheep.'),
  ('87ddb89a-2624-5c92-a540-62526da1d644', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 5, 5, 'David sent ten young men, and David said to the young men, "Go up to Carmel, and go to Nabal, and greet him in my name.'),
  ('b0ef1720-70a3-5de8-a735-b26c7aed712b', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 6, 6, 'You shall tell him, ''Long life to you! Peace be to you, and peace be to your house, and peace be to all that you have.'),
  ('569b479e-fec2-5c53-af6e-7d98fe2c38d5', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 7, 7, 'Now I have heard that you have shearers. Your shepherds have now been with us, and we did them no hurt, neither was there anything missing to them, all the while they were in Carmel.'),
  ('a8c3e58a-c64e-5b03-a153-5840a24a4ef9', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 8, 8, 'Ask your young men, and they will tell you. Therefore, let the young men find favor in your eyes; for we come in a good day. Please give whatever comes to your hand, to your servants, and to your son David.''"'),
  ('ba6bd1a1-4fa0-5d9f-a489-a2416cc51794', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 9, 9, 'When David''s young men came, they spoke to Nabal according to all those words in the name of David, and ceased.'),
  ('41389f7a-1aa9-52d8-a086-ac67aaf48d7e', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 10, 10, 'Nabal answered David''s servants, and said, "Who is David? Who is the son of Jesse? There are many servants who break away from their masters these days.'),
  ('50afea16-9a37-54ae-a868-8294141a90e4', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 11, 11, 'Shall I then take my bread, and my water, and my meat that I have killed for my shearers, and give it to men who I don''t know where they come from?"'),
  ('186b477e-63b0-52b5-af40-b6108c9eaff8', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 12, 12, 'So David''s young men turned on their way, and went back, and came and told him according to all these words.'),
  ('98a01638-69d9-5881-a257-b00501b8421b', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 13, 13, 'David said to his men, "Every man put on his sword!" Every man put on his sword. David also put on his sword. About four hundred men followed David; and two hundred stayed by the baggage.'),
  ('933fc59e-021f-562c-aaab-dcfafc1d2216', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 14, 14, 'But one of the young men told Abigail, Nabal''s wife, saying, "Behold, David sent messengers out of the wilderness to Greet our master; and he railed at them.'),
  ('ea8ac585-04ab-5663-a324-47d12ff58451', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 15, 15, 'But the men were very good to us, and we were not hurt, neither missed we anything, as long as we went with them, when we were in the fields.'),
  ('4e50e48a-7bfa-5189-ace4-942cdb7b7ef1', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 16, 16, 'They were a wall to us both by night and by day, all the while we were with them keeping the sheep.'),
  ('51714aa2-35cb-5320-a71d-ff47b86080a1', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 17, 17, 'Now therefore know and consider what you will do; for evil is determined against our master, and against all his house; for he is such a worthless fellow that one can''t speak to him."'),
  ('9ddd4361-05a0-5156-aee8-ba95e182787d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 18, 18, 'Then Abigail hurried and took two hundred loaves of bread, two bottles of wine, five sheep ready dressed, five measures of parched grain, one hundred clusters of raisins, and two hundred cakes of figs, and laid them on donkeys.'),
  ('56457b9d-8073-5890-a1cf-2d3eee40ad27', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 19, 19, 'She said to her young men, "Go on before me. Behold, I come after you." But she didn''t tell her husband, Nabal.'),
  ('b7423214-56dc-5529-a45b-cafcf26b80d3', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 20, 20, 'It was so, as she rode on her donkey, and came down by the covert of the mountain, that behold, David and his men came down toward her; and she met them.'),
  ('b7b73faa-5061-5017-a5eb-4cd08507a4af', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 21, 21, 'Now David had said, "Surely in vain have I kept all that this fellow has in the wilderness, so that nothing was missed of all that pertained to him. He has returned me evil for good.'),
  ('5b770a77-672f-5b12-a039-3584f0b2ced3', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 22, 22, 'God do so to the enemies of David, and more also, if I leave of all that belongs to him by the morning light so much as one who urinates on a wall."'),
  ('bcec827c-0e6f-5156-ab67-9d5f27a25737', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 23, 23, 'When Abigail saw David, she hurried, and alighted from her donkey, and fell before David on her face, and bowed herself to the ground.'),
  ('16df5e84-d842-5513-a624-542299d1e1e5', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 24, 24, 'She fell at his feet, and said, "On me, my lord, on me be the iniquity; and please let your handmaid speak in your ears. Hear the words of your handmaid.'),
  ('ed7bd6dd-8dfc-5db9-a334-2ef05b1de0be', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 25, 25, 'Please don''t let my lord regard this worthless fellow, even Nabal; for as his name is, so is he. Nabal is his name, and folly is with him; but I, your handmaid, didn''t see the young men of my lord, whom you sent.'),
  ('79a2fa5a-9e47-5548-a313-1d3a0af1bb9d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 26, 26, 'Now therefore, my lord, as Yahweh lives, and as your soul lives, since Yahweh has withheld you from blood guiltiness, and from avenging yourself with your own hand, now therefore let your enemies, and those who seek evil to my lord, be as Nabal.'),
  ('84b53559-a53d-5ad6-a2c7-ee784ff0b67e', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 27, 27, 'Now this present which your servant has brought to my lord, let it be given to the young men who follow my lord.'),
  ('89047a1d-bf8b-55d5-a09b-115fb3b3279e', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 28, 28, 'Please forgive the trespass of your handmaid. For Yahweh will certainly make my lord a sure house, because my lord fights the battles of Yahweh; and evil shall not be found in you all your days.'),
  ('6e7b208f-0cbf-56bb-a959-df133eba8356', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 29, 29, 'Though men may rise up to pursue you, and to seek your soul, yet the soul of my lord shall be bound in the bundle of life with Yahweh your God. He will sling out the souls of your enemies, as from the hollow of a sling.'),
  ('346b4650-96ae-5299-af2a-a2aa187c192d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 30, 30, 'It shall come to pass, when Yahweh has done to my lord according to all the good that he has spoken concerning you, and shall have appointed you prince over Israel,'),
  ('1f301491-3979-5ad9-a737-22a661cc1db8', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 31, 31, 'that this shall be no grief to you, nor offense of heart to my lord, either that you have shed blood without cause, or that my lord has avenged himself. When Yahweh has dealt well with my lord, then remember your handmaid."'),
  ('d5251d3b-b08c-5bd7-a980-99b63e80ee9d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 32, 32, 'David said to Abigail, "Blessed is Yahweh, the God of Israel, who sent you this day to meet me!'),
  ('bc3fdf5a-3b67-57bf-a55b-fdd5b8a8a0b5', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 33, 33, 'Blessed is your discretion, and blessed are you, that have kept me this day from blood guiltiness, and from avenging myself with my own hand.'),
  ('c5b81daa-44aa-553f-a9fe-e58e1a030a12', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 34, 34, 'For indeed, as Yahweh, the God of Israel, lives, who has withheld me from hurting you, unless you had hurried and come to meet me, surely there wouldn''t have been left to Nabal by the morning light so much as one who urinates on a wall."'),
  ('37286cd1-5e21-5857-ae28-b767d5a74e74', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 35, 35, 'So David received of her hand that which she had brought him: and he said to her, "Go up in peace to your house. Behold, I have listened to your voice, and have granted your request."'),
  ('8f9494e6-3390-5af5-a6f2-5fbbf7e9029d', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 36, 36, 'Abigail came to Nabal; and behold, he held a feast in his house, like the feast of a king. Nabal''s heart was merry within him, for he was very drunken. Therefore she told him nothing, less or more, until the morning light.'),
  ('197ae62a-8f90-5f51-ac7a-2c67932899b3', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 37, 37, 'It happened in the morning, when the wine was gone out of Nabal, that his wife told him these things, and his heart died within him, and he became as a stone.'),
  ('bf66d1b8-f9e5-518c-af75-91ab385464ee', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 38, 38, 'It happened about ten days after, that Yahweh struck Nabal, so that he died.'),
  ('bc064916-5268-5bd3-aae4-c3d73c736d60', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 39, 39, 'When David heard that Nabal was dead, he said, "Blessed is Yahweh, who has pleaded the cause of my reproach from the hand of Nabal, and has kept back his servant from evil. Yahweh has returned the evildoing of Nabal on his own head." David sent and spoke concerning Abigail, to take her to him as wife.'),
  ('7ce8bc7a-eab6-51af-aaa7-104751cc597a', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 40, 40, 'When the servants of David had come to Abigail to Carmel, they spoke to her, saying, "David has sent us to you, to take you to him as wife."'),
  ('d7649ba3-d198-5ada-ad78-c7e7bbb3e706', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 41, 41, 'She arose, and bowed herself with her face to the earth, and said, "Behold, your handmaid is a servant to wash the feet of the servants of my lord."'),
  ('a07e416c-acb4-5ba3-aa52-0786bdb0cba1', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 42, 42, 'Abigail hurried, and arose, and rode on a donkey, with five ladies of hers who followed her; and she went after the messengers of David, and became his wife.'),
  ('82c2a66d-350f-5a1f-a80f-6d6447d0cf43', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 43, 43, 'David also took Ahinoam of Jezreel; and they both became his wives.'),
  ('cf7ef686-56ea-504a-ab3b-e99ba6a02d8e', 'abaf2614-de0d-55b0-aa28-c4f2fe3f525f', NULL, 44, 44, 'Now Saul had given Michal his daughter, David''s wife, to Palti the son of Laish, who was of Gallim.'),
  ('ca44aaa5-fb86-5040-ad2d-ec92e0e94e3b', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 1, 1, 'The Ziphites came to Saul to Gibeah, saying, "Doesn''t David hide himself in the hill of Hachilah, which is before the desert?"'),
  ('f91236bd-ac0e-56bb-a711-260b3a1b35c0', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 2, 2, 'Then Saul arose, and went down to the wilderness of Ziph, having three thousand chosen men of Israel with him, to seek David in the wilderness of Ziph.'),
  ('a4e2d6c2-0bc4-5617-a9fd-05ddaf06907a', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 3, 3, 'Saul encamped in the hill of Hachilah, which is before the desert, by the way. But David stayed in the wilderness, and he saw that Saul came after him into the wilderness.'),
  ('666d1c7f-fb94-56f0-ac96-58a866480d91', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 4, 4, 'David therefore sent out spies, and understood that Saul had certainly come.'),
  ('b0c1c29b-fb70-5953-a5ce-c352998678b1', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 5, 5, 'David arose, and came to the place where Saul had encamped; and David saw the place where Saul lay, and Abner the son of Ner, the captain of his army: and Saul lay within the place of the wagons, and the people were encamped around him.'),
  ('f832980e-48b1-59a1-ae9f-858a8f4e74ea', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 6, 6, 'Then answered David and said to Ahimelech the Hittite, and to Abishai the son of Zeruiah, brother to Joab, saying, "Who will go down with me to Saul to the camp?" Abishai said, "I will go down with you."'),
  ('b26d388b-8a4c-55a6-ad32-e77558ff0930', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 7, 7, 'So David and Abishai came to the people by night: and, behold, Saul lay sleeping within the place of the wagons, with his spear stuck in the ground at his head; and Abner and the people lay around him.'),
  ('cdcbcbb2-a58a-5747-aaa9-7bfe9ba7b476', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 8, 8, 'Then Abishai said to David, "God has delivered up your enemy into your hand this day. Now therefore please let me strike him with the spear to the earth at one stroke, and I will not strike him the second time."'),
  ('86bf05af-13f3-5e20-a00a-f4113f12f736', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 9, 9, 'David said to Abishai, "Don''t destroy him; for who can put forth his hand against Yahweh''s anointed, and be guiltless?"'),
  ('f7aa53f6-8302-5974-ab83-13f29c1c9be7', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 10, 10, 'David said, "As Yahweh lives, Yahweh will strike him; or his day shall come to die; or he shall go down into battle and perish.'),
  ('731ea50e-7238-58b9-ace3-5419b0c052d6', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 11, 11, 'Yahweh forbid that I should put forth my hand against Yahweh''s anointed; but now please take the spear that is at his head, and the jar of water, and let us go."'),
  ('afc0de6b-44e4-57e4-a62f-c1aaf936f0a2', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 12, 12, 'So David took the spear and the jar of water from Saul''s head; and they went away: and no man saw it, nor knew it, neither did any awake; for they were all asleep, because a deep sleep from Yahweh was fallen on them.'),
  ('16601e44-7e2d-5f24-ab0b-a23c6b780f9c', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 13, 13, 'Then David went over to the other side, and stood on the top of the mountain afar off; a great space being between them;'),
  ('8489847d-468e-5eed-a0c6-6380bd1be4cd', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 14, 14, 'and David cried to the people, and to Abner the son of Ner, saying, "Don''t you answer, Abner?" Then Abner answered, "Who are you who cries to the king?"'),
  ('ab6df663-a26c-5e14-a9a4-5b3fdac68eea', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 15, 15, 'David said to Abner, "Aren''t you a man? Who is like you in Israel? Why then have you not kept watch over your lord, the king? For one of the people came in to destroy the king your lord.'),
  ('27e7754b-dd1d-5e0d-acff-422493f312ca', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 16, 16, 'This thing isn''t good that you have done. As Yahweh lives, you are worthy to die, because you have not kept watch over your lord, Yahweh''s anointed. Now see where the king''s spear is, and the jar of water that was at his head."'),
  ('e6510bad-f6df-5fa7-ae76-dd7ebdff9d2e', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 17, 17, 'Saul knew David''s voice, and said, "Is this your voice, my son David?" David said, "It is my voice, my lord, O king."'),
  ('2ac57ec7-af15-5ab0-a4b1-ec116aaabd23', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 18, 18, 'He said, "Why does my lord pursue after his servant? For what have I done? Or what evil is in my hand?'),
  ('6e169732-c9e5-5ad1-a09b-7049ef2127ef', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 19, 19, 'Now therefore, please let my lord the king hear the words of his servant. If it is so that Yahweh has stirred you up against me, let him accept an offering. But if it is the children of men, they are cursed before Yahweh; for they have driven me out this day that I shouldn''t cling to Yahweh''s inheritance, saying, ''Go, serve other gods!'''),
  ('d267143a-d293-5f9b-aad4-50b57a48b14f', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 20, 20, 'Now therefore, don''t let my blood fall to the earth away from the presence of Yahweh; for the king of Israel has come out to seek a flea, as when one hunts a partridge in the mountains."'),
  ('121d3d48-76cb-5278-a503-4861c56b5f2c', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 21, 21, 'Then Saul said, "I have sinned. Return, my son David; for I will no more do you harm, because my life was precious in your eyes this day. Behold, I have played the fool, and have erred exceedingly."'),
  ('4ab46cab-ecb3-574b-add4-4890222d4a1b', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 22, 22, 'David answered, "Behold the spear, O king! Then let one of the young men come over and get it.'),
  ('026877da-a58f-53f5-a209-953a64ceaaaf', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 23, 23, 'Yahweh will render to every man his righteousness and his faithfulness; because Yahweh delivered you into my hand today, and I wouldn''t put forth my hand against Yahweh''s anointed.'),
  ('954141e8-6b71-54a5-a345-f2f1598e5f6c', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 24, 24, 'Behold, as your life was respected this day in my eyes, so let my life be respected in the eyes of Yahweh, and let him deliver me out of all oppression."'),
  ('fb33ad12-b17f-57d1-a3ee-6e46949330f4', 'c24de15d-1df2-5e98-acd5-350ef0de80f7', NULL, 25, 25, 'Then Saul said to David, "You are blessed, my son David. You shall both do mightily, and shall surely prevail." So David went his way, and Saul returned to his place.'),
  ('6038c85f-395c-57e5-afa7-9253ff10ddf5', 'a0df22de-dded-5689-a737-832733735523', NULL, 1, 1, 'David said in his heart, "I shall now perish one day by the hand of Saul. There is nothing better for me than that I should escape into the land of the Philistines; and Saul will despair of me, to seek me any more in all the borders of Israel. So shall I escape out of his hand."'),
  ('a2f4203d-3e92-54d2-abb5-87f4ab8662f1', 'a0df22de-dded-5689-a737-832733735523', NULL, 2, 2, 'David arose, and passed over, he and the six hundred men who were with him, to Achish the son of Maoch, king of Gath.'),
  ('6ac4b788-ebbd-5002-ae0a-39e7e114d028', 'a0df22de-dded-5689-a737-832733735523', NULL, 3, 3, 'David lived with Achish at Gath, he and his men, every man with his household, even David with his two wives, Ahinoam the Jezreelitess, and Abigail the Carmelitess, Nabal''s wife.'),
  ('f8cdab5b-a99e-5d53-a74d-0392d5ed34cb', 'a0df22de-dded-5689-a737-832733735523', NULL, 4, 4, 'It was told Saul that David was fled to Gath: and he sought no more again for him.'),
  ('50369c0f-e4f0-53fb-a128-019f7a5e1ab2', 'a0df22de-dded-5689-a737-832733735523', NULL, 5, 5, 'David said to Achish, "If now I have found favor in your eyes, let them give me a place in one of the cities in the country, that I may dwell there. For why should your servant dwell in the royal city with you?"'),
  ('b92d9866-cca0-5cdf-a9e1-2d192b076d82', 'a0df22de-dded-5689-a737-832733735523', NULL, 6, 6, 'Then Achish gave him Ziklag that day: why Ziklag pertains to the kings of Judah to this day.'),
  ('51541cfa-9de7-5f73-af57-fd76b0faf200', 'a0df22de-dded-5689-a737-832733735523', NULL, 7, 7, 'The number of the days that David lived in the country of the Philistines was a full year and four months.'),
  ('f335a6c2-e239-5b08-ac35-688bd5468331', 'a0df22de-dded-5689-a737-832733735523', NULL, 8, 8, 'David and his men went up, and made a raid on the Geshurites, and the Girzites, and the Amalekites; for those [nations] were the inhabitants of the land, who were of old, as you go to Shur, even to the land of Egypt.'),
  ('ce2414e3-9dab-556b-ab48-3db4e57cf96d', 'a0df22de-dded-5689-a737-832733735523', NULL, 9, 9, 'David struck the land, and saved neither man nor woman alive, and took away the sheep, and the cattle, and the donkeys, and the camels, and the clothing; and he returned, and came to Achish.'),
  ('f59cc096-1790-5fe8-a43b-b41f335f87cc', 'a0df22de-dded-5689-a737-832733735523', NULL, 10, 10, 'Achish said, "Against whom have you made a raid today?" David said, "Against the South of Judah, against the South of the Jerahmeelites, and against the South of the Kenites."'),
  ('3a6015b3-eab7-5f2a-a7fe-3d81e39e29ca', 'a0df22de-dded-5689-a737-832733735523', NULL, 11, 11, 'David saved neither man nor woman alive, to bring them to Gath, saying, "Lest they should tell of us, saying, ''So did David, and so has been his way all the while he has lived in the country of the Philistines.''"'),
  ('603fd0a7-e16d-55e7-ac4e-e9e564c7cdc9', 'a0df22de-dded-5689-a737-832733735523', NULL, 12, 12, 'Achish believed David, saying, "He has made his people Israel utterly to abhor him. Therefore he shall be my servant forever."'),
  ('3984050f-7e76-54c4-a023-3c7e0dc8aebb', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 1, 1, 'It happened in those days, that the Philistines gathered their armies together for warfare, to fight with Israel. Achish said to David, "Know assuredly that you shall go out with me in the army, you and your men."'),
  ('4ef48dd7-009e-5b1c-a5c6-1c3078522a2e', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 2, 2, 'David said to Achish, "Therefore you shall know what your servant will do." Achish said to David, "Therefore will I make you my bodyguard for ever."'),
  ('7da09385-7ae3-59c2-a81f-53f9f3573dde', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 3, 3, 'Now Samuel was dead, and all Israel had lamented him, and buried him in Ramah, even in his own city. Saul had put away those who had familiar spirits, and the wizards, out of the land.'),
  ('02c81e09-7137-58db-a2f1-d7e299316c1b', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 4, 4, 'The Philistines gathered themselves together, and came and encamped in Shunem: and Saul gathered all Israel together, and they encamped in Gilboa.'),
  ('cc95d7bf-08a8-57e8-a7e1-dbd5f93fc885', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 5, 5, 'When Saul saw the army of the Philistines, he was afraid, and his heart trembled greatly.'),
  ('297ec93a-7c80-5391-aff2-3b206cc28c9a', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 6, 6, 'When Saul inquired of Yahweh, Yahweh didn''t answer him, neither by dreams, nor by Urim, nor by prophets.'),
  ('ee8fa319-f334-5c23-ab0c-0de1abeaab2c', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 7, 7, 'Then Saul said to his servants, "Seek me a woman who has a familiar spirit, that I may go to her, and inquire of her." His servants said to him, "Behold, there is a woman who has a familiar spirit at Endor."'),
  ('3ce559b7-e199-50d4-a5dd-642f6515df77', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 8, 8, 'Saul disguised himself, and put on other clothing, and went, he and two men with him, and they came to the woman by night: and he said, "Please divine to me by the familiar spirit, and bring me up whoever I shall name to you."'),
  ('29ef4988-cd94-576b-a750-4d06619c2a92', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 9, 9, 'The woman said to him, "Behold, you know what Saul has done, how he has cut off those who have familiar spirits, and the wizards, out of the land. Why then do you lay a snare for my life, to cause me to die?"'),
  ('eadeea6e-9632-590f-ad00-08495b81fced', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 10, 10, 'Saul swore to her by Yahweh, saying, "As Yahweh lives, no punishment shall happen to you for this thing."'),
  ('0fb8c65b-34da-525f-afd8-873404972a21', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 11, 11, 'Then the woman said, "Whom shall I bring up to you?" He said, "Bring Samuel up for me."'),
  ('631670e2-7bdf-578c-a3f9-3251655302bd', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 12, 12, 'When the woman saw Samuel, she cried with a loud voice; and the woman spoke to Saul, saying, "Why have you deceived me? For you are Saul!"'),
  ('f0ef661d-82ca-5bb1-ab73-28919cc89fcf', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 13, 13, 'The king said to her, "Don''t be afraid. For what do you see?" The woman said to Saul, "I see a god coming up out of the earth."'),
  ('11327615-7e8f-5653-a112-336da3c6bddc', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 14, 14, 'He said to her, "What does he look like?" She said, "An old man comes up. He is covered with a robe." Saul perceived that it was Samuel, and he bowed with his face to the ground, and did obeisance.'),
  ('31d81ef5-9a34-5600-a890-b2bf6c23ea84', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 15, 15, 'Samuel said to Saul, "Why have you disturbed me, to bring me up?" Saul answered, "I am very distressed; for the Philistines make war against me, and God has departed from me, and answers me no more, neither by prophets, nor by dreams. Therefore I have called you, that you may make known to me what I shall do."'),
  ('15df78a0-a533-5da9-a413-80298d50ae1e', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 16, 16, 'Samuel said, "Why then do you ask of me, since Yahweh has departed from you and has become your adversary?'),
  ('d02b3d94-2c72-57cc-ae48-932acdde6c4a', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 17, 17, 'Yahweh has done to you as he spoke by me. Yahweh has torn the kingdom out of your hand, and given it to your neighbor, even to David.'),
  ('83364517-7dd7-526c-a7d8-78e855b3f9a5', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 18, 18, 'Because you didn''t obey the voice of Yahweh, and didn''t execute his fierce wrath on Amalek, therefore Yahweh has done this thing to you this day.'),
  ('625f1966-2bd9-593e-a5d3-88bf27c9a391', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 19, 19, 'Moreover Yahweh will deliver Israel also with you into the hand of the Philistines; and tomorrow you and your sons will be with me. Yahweh will deliver the army of Israel also into the hand of the Philistines."'),
  ('23178c6c-c368-591b-a491-0c3072bec2a3', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 20, 20, 'Then Saul fell immediately his full length on the earth, and was terrified, because of the words of Samuel. There was no strength in him; for he had eaten no bread all the day, nor all the night.'),
  ('b7503269-d538-53a3-a607-0d955767b273', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 21, 21, 'The woman came to Saul, and saw that he was very troubled, and said to him, "Behold, your handmaid has listened to your voice, and I have put my life in my hand, and have listened to your words which you spoke to me.'),
  ('40ddf992-c13a-5c9a-ac42-f07449e685d1', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 22, 22, 'Now therefore, please listen also to the voice of your handmaid, and let me set a morsel of bread before you; and eat, that you may have strength, when you go on your way."'),
  ('a7e5dd9b-6625-5be4-ac64-20362dbd0e14', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 23, 23, 'But he refused, and said, I will not eat. But his servants, together with the woman, constrained him; and he listened to their voice. So he arose from the earth, and sat on the bed.'),
  ('2869673e-4999-51ba-a438-a24005447da2', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 24, 24, 'The woman had a fattened calf in the house. She hurried and killed it; and she took flour, and kneaded it, and baked unleavened bread of it.'),
  ('2387fa2c-84e1-5b3c-af6b-56965d2165ef', 'aa4036c7-d9ef-58ae-a2a9-14140577c864', NULL, 25, 25, 'She brought it before Saul, and before his servants; and they ate. Then they rose up, and went away that night.'),
  ('c2138686-5ed6-560d-ab0f-19e29da1f4b5', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 1, 1, 'Now the Philistines gathered together all their armies to Aphek: and the Israelites encamped by the spring which is in Jezreel.'),
  ('52ec046d-17d5-5383-aaee-06c0b30cb730', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 2, 2, 'The lords of the Philistines passed on by hundreds, and by thousands; and David and his men passed on in the rear with Achish.'),
  ('f3c41176-35c4-57e9-a4d2-b1bb1f620f0f', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 3, 3, 'Then the princes of the Philistines said, "What about these Hebrews?" Achish said to the princes of the Philistines, "Isn''t this David, the servant of Saul the king of Israel, who has been with me these days, or rather these years, and I have found no fault in him since he fell away to this day?"'),
  ('3e5c5bc6-3e75-575f-af2b-c802f97b4a5c', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 4, 4, 'But the princes of the Philistines were angry with him; and the princes of the Philistines said to him, "Make the man return, that he may go back to his place where you have appointed him, and let him not go down with us to battle, lest in the battle he become an adversary to us. For with what should this fellow reconcile himself to his lord? Should it not be with the heads of these men?'),
  ('218e4296-3f5c-55a6-a681-e326b23bed65', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 5, 5, 'Is not this David, of whom they sang one to another in dances, saying, ''Saul has slain his thousands, David his ten thousands?''"'),
  ('8caab7f8-05a1-5854-afdc-7c69df965884', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 6, 6, 'Then Achish called David, and said to him, "As Yahweh lives, you have been upright, and your going out and your coming in with me in the army is good in my sight; for I have not found evil in you since the day of your coming to me to this day. Nevertheless, the lords don''t favor you.'),
  ('cc4a454a-9051-5356-a163-ac79e3e39ddf', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 7, 7, 'Therefore now return, and go in peace, that you not displease the lords of the Philistines."'),
  ('48c11bf1-4cda-53b6-aac7-382b30ad94ee', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 8, 8, 'David said to Achish, "But what have I done? What have you found in your servant so long as I have been before you to this day, that I may not go and fight against the enemies of my lord the king?"'),
  ('822231d5-f4b6-51cd-a583-2a94a67b211a', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 9, 9, 'Achish answered David, "I know that you are good in my sight, as an angel of God. Notwithstanding the princes of the Philistines have said, ''He shall not go up with us to the battle.'''),
  ('7b777432-8496-5f26-a4f4-0db9bc371c3a', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 10, 10, 'Therefore now rise up early in the morning with the servants of your lord who have come with you; and as soon as you are up early in the morning, and have light, depart."'),
  ('04a86031-2dfd-5220-a97d-47d76582af54', 'cd04ba92-1130-5bd2-a961-8a4f897d4e85', NULL, 11, 11, 'So David rose up early, he and his men, to depart in the morning, to return into the land of the Philistines. The Philistines went up to Jezreel.'),
  ('5e588920-cb06-5e95-af77-9eaeb27bf7a0', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 1, 1, 'It happened, when David and his men were come to Ziklag on the third day, that the Amalekites had made a raid on the South, and on Ziklag, and had struck Ziklag, and burned it with fire,'),
  ('4732609b-7ff0-54d6-a0cc-b60720fdcb43', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 2, 2, 'and had taken captive the women and all who were therein, both small and great. They didn''t kill any, but carried them off, and went their way.'),
  ('318ae282-3873-5af4-afdf-2701d556e4ff', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 3, 3, 'When David and his men came to the city, behold, it was burned with fire; and their wives, and their sons, and their daughters, were taken captive.'),
  ('fd3a0b8f-955a-5c3a-af5f-7b599664d905', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 4, 4, 'Then David and the people who were with him lifted up their voice and wept, until they had no more power to weep.'),
  ('4ba23af7-896d-5cb9-acbc-a321656ede0b', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 5, 5, 'David''s two wives were taken captive, Ahinoam the Jezreelitess, and Abigail the wife of Nabal the Carmelite.'),
  ('00565b85-35d2-5947-ae48-07ac47024bc9', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 6, 6, 'David was greatly distressed; for the people spoke of stoning him, because the soul of all the people was grieved, every man for his sons and for his daughters: but David strengthened himself in Yahweh his God.'),
  ('2fb89195-8060-59e2-a51d-445c85a9b914', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 7, 7, 'David said to Abiathar the priest, the son of Ahimelech, "Please bring me here the ephod." Abiathar brought the ephod to David.'),
  ('53d765f7-c218-58a0-a6de-46cfdaef6cc5', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 8, 8, 'David inquired of Yahweh, saying, "If I pursue after this troop, shall I overtake them?" He answered him, "Pursue; for you shall surely overtake them, and shall without fail recover all."'),
  ('aa5e926d-b68d-5d3a-a100-f5824734ba85', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 9, 9, 'So David went, he and the six hundred men who were with him, and came to the brook Besor, where those who were left behind stayed.'),
  ('92240958-5371-5ad4-ad54-2f1b960fc82d', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 10, 10, 'But David pursued, he and four hundred men; for two hundred stayed behind, who were so faint that they couldn''t go over the brook Besor.'),
  ('b0859438-d664-5e4d-a8cb-64ee2a634cf9', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 11, 11, 'They found an Egyptian in the field, and brought him to David, and gave him bread, and he ate; and they gave him water to drink.'),
  ('e5d7a387-f8c3-5302-a0a5-bc8cc3a7c229', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 12, 12, 'They gave him a piece of a cake of figs, and two clusters of raisins. when he had eaten, his spirit came again to him; for he had eaten no bread, nor drunk any water, three days and three nights.'),
  ('95d56f83-63ff-5f9f-a2e1-eee644243274', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 13, 13, 'David asked him, "To whom do you belong? Where are you from?" He said, "I am a young man of Egypt, servant to an Amalekite; and my master left me, because three days ago I fell sick.'),
  ('4433a1ca-c4c7-5240-a484-530b9590a5bd', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 14, 14, 'We made a raid on the South of the Cherethites, and on that which belongs to Judah, and on the South of Caleb; and we burned Ziklag with fire."'),
  ('b6b21a36-1fe0-5a12-af99-8f0178a698cd', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 15, 15, 'David said to him, "Will you bring me down to this troop?" He said, "Swear to me by God that you will neither kill me, nor deliver me up into the hands of my master, and I will bring you down to this troop."'),
  ('a575af43-9b46-5284-ae12-1cc62c4dfe4f', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 16, 16, 'When he had brought him down, behold, they were spread around over all the ground, eating, drinking, and dancing, because of all the great spoil that they had taken out of the land of the Philistines, and out of the land of Judah.'),
  ('d598e4ea-8055-5d9d-ae75-841158008676', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 17, 17, 'David struck them from the twilight even to the evening of the next day. Not a man of them escaped from there, except four hundred young men, who rode on camels and fled.'),
  ('4355e3d1-36f5-56d1-ae0b-b86bb522252b', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 18, 18, 'David recovered all that the Amalekites had taken; and David rescued his two wives.'),
  ('679f8823-1ab8-5664-a854-1bd2408894ee', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 19, 19, 'There was nothing lacking to them, neither small nor great, neither sons nor daughters, neither spoil, nor anything that they had taken to them. David brought back all.'),
  ('4e7cf98b-fa6e-596b-a802-da167b56bebd', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 20, 20, 'David took all the flocks and the herds, [which] they drove before those [other] livestock, and said, "This is David''s spoil."'),
  ('1eb958c0-5fbd-57ad-a60e-e2f05396742f', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 21, 21, 'David came to the two hundred men, who were so faint that they could not follow David, whom also they had made to stay at the brook Besor; and they went forth to meet David, and to meet the people who were with him. When David came near to the people, he greeted them.'),
  ('99d41322-893b-55d1-a48f-cbb31b3efb41', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 22, 22, 'Then all the wicked men and base fellows, of those who went with David, answered and said, "Because they didn''t go with us, we will not give them anything of the spoil that we have recovered, except to every man his wife and his children, that he may lead them away, and depart."'),
  ('f29579b1-d8d7-5e4c-aee8-f3c9eab6d0d5', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 23, 23, 'Then David said, "You shall not do so, my brothers, with that which Yahweh has given to us, who has preserved us, and delivered the troop that came against us into our hand.'),
  ('da8bdf76-8986-5b65-a16e-efce06cf1302', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 24, 24, 'Who will listen to you in this matter? For as his share is who goes down to the battle, so shall his share be who tarries by the baggage: they shall share alike."'),
  ('2b0e8b72-0a5a-5b60-a78d-5fae6f2e92da', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 25, 25, 'It was so from that day forward, that he made it a statute and an ordinance for Israel to this day.'),
  ('75487b1a-3711-58fc-ad75-47c08f7dbebf', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 26, 26, 'When David came to Ziklag, he sent of the spoil to the elders of Judah, even to his friends, saying, "Behold, a present for you of the spoil of the enemies of Yahweh."'),
  ('9619821e-9a24-5b6c-ad62-5389d5307b0c', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 27, 27, 'He sent it to those who were in Bethel, and to those who were in Ramoth of the South, and to those who were in Jattir,'),
  ('b7451a2c-2135-5eb1-a699-e5a8200b25eb', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 28, 28, 'and to those who were in Aroer, and to those who were in Siphmoth, and to those who were in Eshtemoa,'),
  ('11355f5b-2ca0-5565-a78f-36ed4deeba16', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 29, 29, 'and to those who were in Racal, and to those who were in the cities of the Jerahmeelites, and to those who were in the cities of the Kenites,'),
  ('ebd961e5-2dfb-552b-a3cd-d92e6875e827', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 30, 30, 'and to those who were in Hormah, and to those who were in Borashan, and to those who were in Athach,'),
  ('ef0f741e-be4a-5b42-aa19-8a8526b80120', 'a60d2051-697f-58ac-afc5-76a7e9f2d1db', NULL, 31, 31, 'and to those who were in Hebron, and to all the places where David himself and his men used to stay.'),
  ('5b402308-5c99-552d-a731-7bbbfcba4ac6', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 1, 1, 'Now the Philistines fought against Israel: and the men of Israel fled from before the Philistines, and fell down slain on Mount Gilboa.'),
  ('14f42e8e-46b6-5b84-a0d3-95cd78160d17', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 2, 2, 'The Philistines followed hard on Saul and on his sons; and the Philistines killed Jonathan, and Abinadab, and Malchishua, the sons of Saul.'),
  ('96be5438-d01f-5ef9-aa17-c17b545a2a46', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 3, 3, 'The battle went hard against Saul, and the archers overtook him; and he was greatly distressed by reason of the archers.'),
  ('54635082-0c58-577d-abef-47ca8e6ba7e4', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 4, 4, 'Then Saul said to his armor bearer, "Draw your sword, and thrust me through with it, lest these uncircumcised come and thrust me through, and abuse me!" But his armor bearer would not; for he was terrified. Therefore Saul took his sword, and fell on it.'),
  ('b715f912-364c-52f0-aa76-b76623e138c2', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 5, 5, 'When his armor bearer saw that Saul was dead, he likewise fell on his sword, and died with him.'),
  ('50c4530e-edaa-5a03-ae6e-486d6589c980', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 6, 6, 'So Saul died, and his three sons, and his armor bearer, and all his men, that same day together.'),
  ('e7ec85f6-734b-523a-a4dd-5b14ae622a62', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 7, 7, 'When the men of Israel who were on the other side of the valley, and those who were beyond the Jordan, saw that the men of Israel fled, and that Saul and his sons were dead, they forsook the cities, and fled; and the Philistines came and lived in them.'),
  ('d74e0838-a6a3-5375-aedf-e5a4147f7e3e', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 8, 8, 'It happened on the next day, when the Philistines came to strip the slain, that they found Saul and his three sons fallen on Mount Gilboa.'),
  ('54e8bda7-0458-5f44-a724-58377ed02716', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 9, 9, 'They cut off his head, and stripped off his armor, and sent into the land of the Philistines all around, to carry the news to the house of their idols, and to the people.'),
  ('150b39a3-0bcd-551a-a3d2-3f1d3acbfed5', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 10, 10, 'They put his armor in the house of the Ashtaroth; and they fastened his body to the wall of Beth Shan.'),
  ('ad474cc2-a045-50fd-a9a2-1cb13b913f3a', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 11, 11, 'When the inhabitants of Jabesh Gilead heard concerning him that which the Philistines had done to Saul,'),
  ('345d4abc-880d-528a-a167-d95eb2589d8e', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 12, 12, 'all the valiant men arose, and went all night, and took the body of Saul and the bodies of his sons from the wall of Beth Shan; and they came to Jabesh, and burnt them there.'),
  ('f784780d-0115-5fb0-a152-451e532f8905', '935c2e7f-1998-584c-aada-f6858a04080a', NULL, 13, 13, 'They took their bones, and buried them under the tamarisk tree in Jabesh, and fasted seven days.'),
  ('7a63285b-e74e-5f45-a28c-98cbf74c2f80', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 1, 1, 'It happened after the death of Saul, when David was returned from the slaughter of the Amalekites, and David had stayed two days in Ziklag;'),
  ('a707d1ad-4a9c-51ed-a372-2ec6f7d504a2', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 2, 2, 'it happened on the third day, that behold, a man came out of the camp from Saul, with his clothes torn, and earth on his head: and so it was, when he came to David, that he fell to the earth, and did obeisance.'),
  ('e0b14734-00f0-54d6-aa25-76df2cec5d40', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 3, 3, 'David said to him, "Where do you come from?" He said to him, "I have escaped out of the camp of Israel."'),
  ('f96766df-689c-5a80-a2df-2454340d3e60', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 4, 4, 'David said to him, "How did it go? Please tell me." He answered, "The people have fled from the battle, and many of the people also have fallen and are dead; and Saul and Jonathan his son are dead also."'),
  ('1b508ed8-4de9-5eb7-a2ce-bb1e3f617488', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 5, 5, 'David said to the young man who told him, "How do you know that Saul and Jonathan his son are dead?"'),
  ('1795967e-c171-5cca-a9f2-4fb5c2cdcf82', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 6, 6, 'The young man who told him said, "As I happened by chance on Mount Gilboa, behold, Saul was leaning on his spear; and behold, the chariots and the horsemen followed hard after him.'),
  ('95be4456-8576-57ce-a45c-940747ced0cc', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 7, 7, 'When he looked behind him, he saw me, and called to me. I answered, ''Here I am.'''),
  ('94b9e2fd-bd98-59c5-a0fd-3c51b117a923', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 8, 8, 'He said to me, ''Who are you?'' I answered him, ''I am an Amalekite.'''),
  ('7a93a95a-a45a-5ee0-adc2-55b0304f39f2', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 9, 9, 'He said to me, ''Please stand beside me, and kill me; for anguish has taken hold of me, because my life is yet whole in me.'''),
  ('c3812e26-348c-5ae6-aeec-f13ffdf75cb1', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 10, 10, 'So I stood beside him, and killed him, because I was sure that he could not live after that he had fallen. I took the crown that was on his head, and the bracelet that was on his arm, and have brought them here to my lord."'),
  ('695903ff-846e-5e8b-a933-1528bf7cf2eb', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 11, 11, 'Then David took hold on his clothes, and tore them; and likewise all the men who were with him.'),
  ('2232397d-1498-5eb3-ad7b-b39ca686dcca', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 12, 12, 'They mourned, and wept, and fasted until evening, for Saul, and for Jonathan his son, and for the people of Yahweh, and for the house of Israel; because they were fallen by the sword.'),
  ('036b9d95-65c2-5e0e-a25c-e28867daf279', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 13, 13, 'David said to the young man who told him, "Where are you from?" He answered, "I am the son of a foreigner, an Amalekite."'),
  ('627b6d11-fef5-5f18-a505-3a0976ecc85c', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 14, 14, 'David said to him, "How were you not afraid to put forth your hand to destroy Yahweh''s anointed?"'),
  ('9cf4a816-cfdc-53dd-a8eb-9c78ef001c46', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 15, 15, 'David called one of the young men, and said, "Go near, and fall on him." He struck him, so that he died.'),
  ('dbf0ed8c-bd12-5842-aed0-28cc4a4205a2', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 16, 16, 'David said to him, "Your blood be on your head; for your mouth has testified against you, saying, ''I have slain Yahweh''s anointed.''"'),
  ('ba9a28c2-e67a-5902-a6cf-cb41f05b4702', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 17, 17, 'David lamented with this lamentation over Saul and over Jonathan his son'),
  ('9f700588-8958-532b-a651-4c897a102b97', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 18, 18, '(and he commanded them to teach the children of Judah [the song of] the bow: behold, it is written in the book of Jashar):'),
  ('95943aa5-9edd-58c5-abcd-d0488aa8cd27', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 19, 19, '"Your glory, Israel, is slain on your high places! How the mighty have fallen!'),
  ('b2eee74a-f39e-5ab4-a9ec-7b420bcff28f', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 20, 20, 'Don''t tell it in Gath. Don''t publish it in the streets of Ashkelon, lest the daughters of the Philistines rejoice, lest the daughters of the uncircumcised triumph.'),
  ('a0dedaa6-a3ef-56de-a7cd-60f77bd72152', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 21, 21, 'You mountains of Gilboa, let there be no dew nor rain on you, neither fields of offerings; For there the shield of the mighty was vilely cast away, The shield of Saul was not anointed with oil.'),
  ('50b3039d-e109-5ca7-a538-141009d2a093', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 22, 22, 'From the blood of the slain, from the fat of the mighty, Jonathan''s bow didn''t turn back. Saul''s sword didn''t return empty.'),
  ('55bdfea3-90c5-57fb-a21c-9edfd20d486e', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 23, 23, 'Saul and Jonathan were lovely and pleasant in their lives. In their death, they were not divided. They were swifter than eagles. They were stronger than lions.'),
  ('aef36b81-42cc-59ff-af84-e7fa115f4621', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 24, 24, 'You daughters of Israel, weep over Saul, who clothed you in scarlet delicately, who put ornaments of gold on your clothing.'),
  ('df5dc994-2932-5e78-a24e-af843755c0fc', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 25, 25, 'How are the mighty fallen in the midst of the battle! Jonathan is slain on your high places.'),
  ('9d24b0a7-4c0a-5862-ab84-21bea8340c7c', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 26, 26, 'I am distressed for you, my brother Jonathan. You have been very pleasant to me. Your love to me was wonderful, passing the love of women.'),
  ('7488d592-141f-596f-a913-e177a89ee9a0', 'f2171a0d-b075-5e8d-acf3-13f0ff0ba0de', NULL, 27, 27, 'How are the mighty fallen, and the weapons of war perished!"'),
  ('8a21df24-b4ae-5f00-a726-7e56f681202c', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 1, 1, 'It happened after this, that David inquired of Yahweh, saying, "Shall I go up into any of the cities of Judah?" Yahweh said to him, "Go up." David said, "Where shall I go up?" He said, "To Hebron."'),
  ('4ad441ac-93cc-571c-a548-77c6f14e6601', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 2, 2, 'So David went up there, and his two wives also, Ahinoam the Jezreelitess, and Abigail the wife of Nabal the Carmelite.'),
  ('b9cbf84b-d870-5f42-a9a1-91ba3e5b2f41', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 3, 3, 'David brought up his men who were with him, every man with his household. They lived in the cities of Hebron.'),
  ('d3766d90-f698-553f-ac0e-b817550d0ad6', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 4, 4, 'The men of Judah came, and there they anointed David king over the house of Judah. They told David, saying, "The men of Jabesh Gilead were those who buried Saul."'),
  ('bba2d567-c5e9-504c-afdd-a29c2aa0044d', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 5, 5, 'David sent messengers to the men of Jabesh Gilead, and said to them, "Blessed are you by Yahweh, that you have shown this kindness to your lord, even to Saul, and have buried him.'),
  ('4f48a0a7-24c9-5a89-a98e-c7ea4cdee785', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 6, 6, 'Now may Yahweh show loving kindness and truth to you. I also will reward you for this kindness, because you have done this thing.'),
  ('363e531a-cab3-5c55-a59c-67c68bf9785b', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 7, 7, 'Now therefore let your hands be strong, and be valiant; for Saul your lord is dead, and also the house of Judah have anointed me king over them."'),
  ('73ea079d-b111-5cc6-a623-f3d37e3cb053', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 8, 8, 'Now Abner the son of Ner, captain of Saul''s army, had taken Ishbosheth the son of Saul, and brought him over to Mahanaim;'),
  ('cf23dbb0-018d-5320-a69a-a405fa783a57', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 9, 9, 'and he made him king over Gilead, and over the Ashurites, and over Jezreel, and over Ephraim, and over Benjamin, and over all Israel.'),
  ('77adbc7a-b071-5da1-a210-ab724496e7c8', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 10, 10, 'Ishbosheth, Saul''s son, was forty years old when he began to reign over Israel, and he reigned two years. But the house of Judah followed David.'),
  ('143f6cf2-4ed5-5bed-a4f5-dc5205ebc1d1', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 11, 11, 'The time that David was king in Hebron over the house of Judah was seven years and six months.'),
  ('64ea5227-de82-5c58-aab6-c2a6a6639e58', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 12, 12, 'Abner the son of Ner, and the servants of Ishbosheth the son of Saul, went out from Mahanaim to Gibeon.'),
  ('6775ccb4-bf48-52c8-a31b-4fcc47fa0e81', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 13, 13, 'Joab the son of Zeruiah, and the servants of David, went out, and met them by the pool of Gibeon; and they sat down, the one on the one side of the pool, and the other on the other side of the pool.'),
  ('b88250cd-109d-5091-a62e-f09a7e4521dc', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 14, 14, 'Abner said to Joab, "Please let the young men arise and play before us!" Joab said, "Let them arise!"'),
  ('9bc589c1-5036-562b-ae62-934d8fc074d8', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 15, 15, 'Then they arose and went over by number: twelve for Benjamin, and for Ishbosheth the son of Saul, and twelve of the servants of David.'),
  ('a2a8f337-8c01-5b1c-a7ff-90ed25670f8f', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 16, 16, 'They caught everyone his fellow by the head, and [thrust] his sword in his fellow''s side; so they fell down together: therefore that place was called Helkath Hazzurim, which is in Gibeon.'),
  ('d3a2ff7a-8cf7-57c8-a180-f32fdf0e7bbc', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 17, 17, 'The battle was very severe that day: and Abner was beaten, and the men of Israel, before the servants of David.'),
  ('7e6cdde0-55ec-5035-aa4a-f5a7eaf2efe5', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 18, 18, 'The three sons of Zeruiah were there, Joab, and Abishai, and Asahel: and Asahel was as light of foot as a wild gazelle.'),
  ('c0583f15-6310-5793-a007-a927b118d6f7', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 19, 19, 'Asahel pursued after Abner; and in going he didn''t turn to the right hand nor to the left from following Abner.'),
  ('66d748c4-f212-5ec1-a360-7a2c33b86de1', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 20, 20, 'Then Abner looked behind him, and said, "Is it you, Asahel?" He answered, "It is I."'),
  ('add3beb5-3a0e-5f42-ab0b-1926962c56f9', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 21, 21, 'Abner said to him, "Turn aside to your right hand or to your left, and grab one of the young men, and take his armor." But Asahel would not turn aside from following him.'),
  ('9afbad88-b836-501e-a932-242a6ba5d9ed', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 22, 22, 'Abner said again to Asahel, "Turn aside from following me. Why should I strike you to the ground? How then should I hold up my face to Joab your brother?"'),
  ('a6a54503-aa1d-597b-ad68-27fcf5a96458', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 23, 23, 'However he refused to turn aside. Therefore Abner with the back end of the spear struck him in the body, so that the spear came out behind him; and he fell down there, and died in the same place. It happened, that as many as came to the place where Asahel fell down and died stood still.'),
  ('1b03650c-0249-59b8-a5f3-a0c2c48d059b', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 24, 24, 'But Joab and Abishai pursued after Abner: and the sun went down when they were come to the hill of Ammah, that lies before Giah by the way of the wilderness of Gibeon.'),
  ('16bec108-1cc8-5c1a-a342-3efef8a3c9d1', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 25, 25, 'The children of Benjamin gathered themselves together after Abner, and became one band, and stood on the top of a hill.'),
  ('02f70bab-03be-5db6-a940-1c6d958babac', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 26, 26, 'Then Abner called to Joab, and said, "Shall the sword devour forever? Don''t you know that it will be bitterness in the latter end? How long shall it be then, before you ask the people to return from following their brothers?"'),
  ('d0f89afc-80a9-550e-ac13-47824c018cc3', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 27, 27, 'Joab said, "As God lives, if you had not spoken, surely then in the morning the people would have gone away, and not each followed his brother."'),
  ('c0e63289-58a1-5097-a8ff-54f9d6d6c1ee', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 28, 28, 'So Joab blew the trumpet; and all the people stood still, and pursued after Israel no more, neither fought they any more.'),
  ('40564daa-4d68-5dab-a0e3-21db0a46400f', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 29, 29, 'Abner and his men went all that night through the Arabah; and they passed over the Jordan, and went through all Bithron, and came to Mahanaim.'),
  ('7328874c-1072-5430-aff2-f01d6063fc6a', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 30, 30, 'Joab returned from following Abner: and when he had gathered all the people together, there lacked of David''s servants nineteen men and Asahel.'),
  ('840307f5-32c3-52e3-ad1b-c60cd110f886', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 31, 31, 'But the servants of David had struck of Benjamin, and of Abner''s men, [so that] three hundred sixty men died.'),
  ('9f7f2027-d722-5514-ac09-eca8a8c9364e', 'c4f7b5e7-17cd-5f21-a98e-ee1cb16024ea', NULL, 32, 32, 'They took up Asahel, and buried him in the tomb of his father, which was in Bethlehem. Joab and his men went all night, and the day broke on them at Hebron.'),
  ('4a215737-3023-5f5f-adf3-240b249a5fbf', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 1, 1, 'Now there was long war between the house of Saul and the house of David: and David grew stronger and stronger, but the house of Saul grew weaker and weaker.'),
  ('0407f0c0-7aaf-5ae4-ac0f-a9a6bc906f57', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 2, 2, 'To David were sons born in Hebron: and his firstborn was Amnon, of Ahinoam the Jezreelitess;'),
  ('374b6675-543f-5520-a883-8a48e4382bdb', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 3, 3, 'and his second, Chileab, of Abigail the wife of Nabal the Carmelite; and the third, Absalom the son of Maacah the daughter of Talmai king of Geshur;'),
  ('3415d392-bb87-5166-aab0-82ac531688db', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 4, 4, 'and the fourth, Adonijah the son of Haggith; and the fifth, Shephatiah the son of Abital;'),
  ('039ffb0c-f4d4-52ae-a2b8-6a6413c1b7ba', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 5, 5, 'and the sixth, Ithream, of Eglah, David''s wife. These were born to David in Hebron.'),
  ('89bee768-3192-5a20-a277-76f36964a5cf', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 6, 6, 'It happened, while there was war between the house of Saul and the house of David, that Abner made himself strong in the house of Saul.'),
  ('f2a01b85-f930-59cd-a663-f1c9c29feb27', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 7, 7, 'Now Saul had a concubine, whose name was Rizpah, the daughter of Aiah: and [Ishbosheth] said to Abner, "Why have you gone in to my father''s concubine?"'),
  ('4a39ad4f-65cf-5e26-a62f-532e034a7291', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 8, 8, 'Then was Abner very angry for the words of Ishbosheth, and said, "Am I a dog''s head that belongs to Judah? Today I show kindness to the house of Saul your father, to his brothers, and to his friends, and have not delivered you into the hand of David; and yet you charge me this day with a fault concerning this woman!'),
  ('4dbc5849-a5ee-52ea-a7c0-c8d43ced4ac5', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 9, 9, 'God do so to Abner, and more also, if, as Yahweh has sworn to David, I don''t do even so to him;'),
  ('61399dde-8626-53f3-ae94-891122ffac48', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 10, 10, 'to transfer the kingdom from the house of Saul, and to set up the throne of David over Israel and over Judah, from Dan even to Beersheba."'),
  ('e106d60a-dd07-5a05-ae5d-f79ac15f50a4', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 11, 11, 'He could not answer Abner another word, because he feared him.'),
  ('947fad2b-4dc2-52e2-a012-a92549294494', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 12, 12, 'Abner sent messengers to David on his behalf, saying, "Whose is the land?" and saying, "Make your alliance with me, and behold, my hand shall be with you, to bring all Israel around to you."'),
  ('f5b9f11c-878a-5038-afa0-07ada0264c00', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 13, 13, 'He said, "Good; I will make a treaty with you; but one thing I require of you. That is, you shall not see my face, unless you first bring Michal, Saul''s daughter, when you come to see my face."'),
  ('99c8e53f-5ed1-56d6-afdb-717a036b6042', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 14, 14, 'David sent messengers to Ishbosheth, Saul''s son, saying, "Deliver me my wife Michal, whom I pledged to be married to me for one hundred foreskins of the Philistines."'),
  ('39a91e6e-0185-541b-a3a3-2ee416bb1677', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 15, 15, 'Ishbosheth sent, and took her from her husband, even from Paltiel the son of Laish.'),
  ('7cab9538-04e1-577d-a6a1-7ba257b1b33c', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 16, 16, 'Her husband went with her, weeping as he went, and followed her to Bahurim. Then Abner said to him, "Go! Return!" and he returned.'),
  ('bbd87d4b-4bff-5dba-a77c-5c0f69de207a', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 17, 17, 'Abner had communication with the elders of Israel, saying, "In times past, you sought for David to be king over you.'),
  ('613e018f-9dc7-5652-a4c3-6b981d20c396', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 18, 18, 'Now then do it; for Yahweh has spoken of David, saying, ''By the hand of my servant David, I will save my people Israel out of the hand of the Philistines, and out of the hand of all their enemies.''"'),
  ('7035d146-2591-5a24-a33a-97c14f268e45', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 19, 19, 'Abner also spoke in the ears of Benjamin: and Abner went also to speak in the ears of David in Hebron all that seemed good to Israel, and to the whole house of Benjamin.'),
  ('438d16b7-175d-530b-afca-7c4f877c554f', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 20, 20, 'So Abner came to David to Hebron, and twenty men with him. David made Abner and the men who were with him a feast.'),
  ('0305b1f3-79d2-509d-add3-2b1c5a16ec8b', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 21, 21, 'Abner said to David, "I will arise and go, and will gather all Israel to my lord the king, that they may make a covenant with you, and that you may reign over all that your soul desires." David sent Abner away; and he went in peace.'),
  ('bbce4644-885f-5b04-ac97-ea4424c9fb26', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 22, 22, 'Behold, the servants of David and Joab came from a foray, and brought in a great spoil with them: but Abner was not with David in Hebron; for he had sent him away, and he was gone in peace.'),
  ('ab5e9a35-99e5-5418-a19b-1d6baf3cc1d8', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 23, 23, 'When Joab and all the army who was with him had come, they told Joab, saying, Abner the son of Ner came to the king, and he has sent him away, and he is gone in peace.'),
  ('726f3702-6ede-5a0e-a0ee-bac8103774d7', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 24, 24, 'Then Joab came to the king, and said, "What have you done? Behold, Abner came to you. Why is it that you have sent him away, and he is quite gone?'),
  ('40ca740d-1207-58c9-a543-939a6f595b8c', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 25, 25, 'You know Abner the son of Ner, that he came to deceive you, and to know your going out and your coming in, and to know all that you do."'),
  ('e2a7ddeb-d8c6-5b28-a34a-db8152ac68ca', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 26, 26, 'When Joab had come out from David, he sent messengers after Abner, and they brought him back from the well of Sirah; but David didn''t know it.'),
  ('602d780f-cbc5-51db-ad4a-50e01e43ac22', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 27, 27, 'When Abner was returned to Hebron, Joab took him aside into the midst of the gate to speak with him quietly, and struck him there in the body, so that he died, for the blood of Asahel his brother.'),
  ('2f6ac865-6f77-5256-ac4f-f59c16dce541', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 28, 28, 'Afterward, when David heard it, he said, "I and my kingdom are guiltless before Yahweh forever of the blood of Abner the son of Ner.'),
  ('7bc56435-8f1d-535d-a949-69087b6b0a11', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 29, 29, 'Let it fall on the head of Joab, and on all his father''s house. Let there not fail from the house of Joab one who has an issue, or who is a leper, or who leans on a staff, or who falls by the sword, or who lacks bread."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('508ad7b1-83af-5e6d-a9cb-4144ecde887d', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 30, 30, 'So Joab and Abishai his brother killed Abner, because he had killed their brother Asahel at Gibeon in the battle.'),
  ('76323c9f-56dc-5dfe-a70c-410328011be2', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 31, 31, 'David said to Joab, and to all the people who were with him, Tear your clothes, and clothe yourselves with sackcloth, and mourn before Abner. King David followed the bier.'),
  ('91bc9451-6c56-5a89-aa4f-f82222cbc022', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 32, 32, 'They buried Abner in Hebron: and the king lifted up his voice, and wept at the grave of Abner; and all the people wept.'),
  ('c6138773-250c-52eb-a43d-fcbdc2463d9b', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 33, 33, 'The king lamented for Abner, and said, "Should Abner die as a fool dies?'),
  ('e2b04d45-4c96-50ba-a709-ceaf9dff9cc9', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 34, 34, 'Your hands were not bound, nor your feet put into fetters. As a man falls before the children of iniquity, so you fell." All the people wept again over him.'),
  ('7e5a1d26-2b94-527d-aebf-8acf2ca352a0', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 35, 35, 'All the people came to cause David to eat bread while it was yet day; but David swore, saying, "God do so to me, and more also, if I taste bread, or anything else, until the sun goes down."'),
  ('241f8b11-f2f5-5249-a713-0e4a30642503', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 36, 36, 'All the people took notice of it, and it pleased them; as whatever the king did pleased all the people.'),
  ('5b1cf70c-7b92-561a-a503-2ab98e0b8643', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 37, 37, 'So all the people and all Israel understood that day that it was not of the king to kill Abner the son of Ner.'),
  ('d9ed144f-e6ec-5fc4-a20e-b491cba9909c', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 38, 38, 'The king said to his servants, "Don''t you know that there a prince and a great man has fallen this day in Israel?'),
  ('5f4ee16c-57d5-5246-a64e-87d26b739fb6', 'cbbf0b28-08b2-5ed2-a6a2-e123bfd09991', NULL, 39, 39, 'I am this day weak, though anointed king; and these men the sons of Zeruiah are too hard for me. May Yahweh reward the evildoer according to his wickedness."'),
  ('210af324-2bfe-5e0b-aff0-da4d95656893', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 1, 1, 'When [Ishbosheth], Saul''s son, heard that Abner was dead in Hebron, his hands became feeble, and all the Israelites were troubled.'),
  ('10577d23-79bb-5997-a71f-5ff4bf0ff4ae', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 2, 2, '[Ishbosheth], Saul''s son, [had] two men who were captains of bands: the name of the one was Baanah, and the name of the other Rechab, the sons of Rimmon the Beerothite, of the children of Benjamin (for Beeroth also is reckoned to Benjamin:'),
  ('3745128c-8ee5-5644-ab7f-398f12a6131b', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 3, 3, 'and the Beerothites fled to Gittaim, and have lived as foreigners there until this day).'),
  ('d1b82baa-393a-5490-ad8b-ba69ef0bfe26', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 4, 4, 'Now Jonathan, Saul''s son, had a son who was lame of his feet. He was five years old when the news came of Saul and Jonathan out of Jezreel; and his nurse took him up, and fled: and it happened, as she made haste to flee, that he fell, and became lame. His name was Mephibosheth.'),
  ('92a7cf5f-a47c-5e03-a869-64c078ac758d', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 5, 5, 'The sons of Rimmon the Beerothite, Rechab and Baanah, went, and came about the heat of the day to the house of Ishbosheth, as he took his rest at noon.'),
  ('373fd297-0adb-551e-a303-8380742f0feb', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 6, 6, 'They came there into the midst of the house, as though they would have fetched wheat; and they struck him in the body: and Rechab and Baanah his brother escaped.'),
  ('35c16b9f-d259-5d07-ab87-6e298c2cddd7', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 7, 7, 'Now when they came into the house, as he lay on his bed in his bedroom, they struck him, and killed him, and beheaded him, and took his head, and went by the way of the Arabah all night.'),
  ('f674e883-7101-5e5d-a75e-cfdfa590b313', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 8, 8, 'They brought the head of Ishbosheth to David to Hebron, and said to the king, "Behold, the head of Ishbosheth, the son of Saul, your enemy, who sought your life! Yahweh has avenged my lord the king this day of Saul, and of his seed."'),
  ('76270093-3b83-5fc5-ac42-1337e6faa117', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 9, 9, 'David answered Rechab and Baanah his brother, the sons of Rimmon the Beerothite, and said to them, "As Yahweh lives, who has redeemed my soul out of all adversity,'),
  ('3a6ee02a-f55e-5727-af03-0e142e34af22', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 10, 10, 'when someone told me, ''Behold, Saul is dead,'' thinking to have brought good news, I took hold of him, and killed him in Ziklag, which was the reward I gave him for his news.'),
  ('127c427d-f63a-5e0b-af10-2e73d07ba4c0', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 11, 11, 'How much more, when wicked men have slain a righteous person in his own house on his bed, shall I not now require his blood of your hand, and take you away from the earth?"'),
  ('5c1af35f-f3f2-5e90-abee-c55e46b29e96', '9fc7a355-22eb-56f5-a8ff-d1d1d131bb7d', NULL, 12, 12, 'David commanded his young men, and they killed them, and cut off their hands and their feet, and hanged them up beside the pool in Hebron. But they took the head of Ishbosheth, and buried it in the grave of Abner in Hebron.'),
  ('312fbb1b-7ceb-563d-a528-e467b50da4e3', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 1, 1, 'Then came all the tribes of Israel to David to Hebron, and spoke, saying, "Behold, we are your bone and your flesh.'),
  ('e1a12a46-82a1-5ee4-aedb-e94be08f69e3', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 2, 2, 'In times past, when Saul was king over us, it was you who led out and brought in Israel. Yahweh said to you, ''You shall be shepherd of my people Israel, and you shall be prince over Israel.''"'),
  ('90188018-8f17-5075-a6f9-05290dfccf27', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 3, 3, 'So all the elders of Israel came to the king to Hebron; and king David made a covenant with them in Hebron before Yahweh; and they anointed David king over Israel.'),
  ('1cf8ace6-fa3f-53b4-a98e-32d7bd6175c6', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 4, 4, 'David was thirty years old when he began to reign, and he reigned forty years.'),
  ('6aec0f9c-98fc-5fdf-ae74-9647965a8adc', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 5, 5, 'In Hebron he reigned over Judah seven years and six months; and in Jerusalem he reigned thirty-three years over all Israel and Judah.'),
  ('3c068264-c801-5172-add6-6f214baa8248', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 6, 6, 'The king and his men went to Jerusalem against the Jebusites, the inhabitants of the land, who spoke to David, saying, "Unless you take away the blind and the lame, you shall not come in here;" thinking, "David can''t come in here."'),
  ('14143ee5-1070-5b72-a414-0f1c22a13af3', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 7, 7, 'Nevertheless David took the stronghold of Zion; the same is the city of David.'),
  ('ac85ae45-2edd-5792-a1a8-0d30a300e633', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 8, 8, 'David said on that day, "Whoever strikes the Jebusites, let him get up to the watercourse, and strike the lame and the blind, who are hated by David''s soul." Therefore they say, "The blind and the lame can''t come into the house."'),
  ('3fdf7300-d43e-55ce-a5d6-ec1791b08b5b', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 9, 9, 'David lived in the stronghold, and called it the city of David. David built around from Millo and inward.'),
  ('c06d6d18-cebb-55e8-afe3-4a68d690dfa2', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 10, 10, 'David grew greater and greater; for Yahweh, the God of Armies, was with him.'),
  ('fcfcbfaf-e9c7-529a-aba3-b923ba151324', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 11, 11, 'Hiram king of Tyre sent messengers to David, and cedar trees, and carpenters, and masons; and they built David a house.'),
  ('6d86e558-f76d-5435-a151-8ffd20858793', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 12, 12, 'David perceived that Yahweh had established him king over Israel, and that he had exalted his kingdom for his people Israel''s sake.'),
  ('19049b61-ce7e-5114-a727-f1015447bba2', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 13, 13, 'David took him more concubines and wives out of Jerusalem, after he was come from Hebron; and there were yet sons and daughters born to David.'),
  ('afdba308-9a6c-5974-a808-8087ada8f97b', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 14, 14, 'These are the names of those who were born to him in Jerusalem: Shammua, and Shobab, and Nathan, and Solomon,'),
  ('45af9d7f-7894-57ed-a99d-a861b68e4217', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 15, 15, 'and Ibhar, and Elishua, and Nepheg, and Japhia,'),
  ('25f7e83b-a4ab-5559-ac99-b9672ab9e8fb', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 16, 16, 'and Elishama, and Eliada, and Eliphelet.'),
  ('957ebecb-cf7d-50ad-a7ad-8d7bb9e6a6fd', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 17, 17, 'When the Philistines heard that they had anointed David king over Israel, all the Philistines went up to seek David; and David heard of it, and went down to the stronghold.'),
  ('d31c181a-a890-5447-aee7-88c8b48234f7', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 18, 18, 'Now the Philistines had come and spread themselves in the valley of Rephaim.'),
  ('982be671-d2f3-5b85-a6bc-11432d694d33', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 19, 19, 'David inquired of Yahweh, saying, "Shall I go up against the Philistines? Will you deliver them into my hand?" Yahweh said to David, "Go up; for I will certainly deliver the Philistines into your hand."'),
  ('d1e03d2a-efc9-598c-a5d5-31fca95c9e4c', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 20, 20, 'David came to Baal Perazim, and David struck them there; and he said, "Yahweh has broken my enemies before me, like the breach of waters." Therefore he called the name of that place Baal Perazim.'),
  ('437d14b6-7ea3-538a-a655-8a0027c9f10d', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 21, 21, 'They left their images there; and David and his men took them away.'),
  ('6f589d6d-3298-5931-a433-f8876c970633', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 22, 22, 'The Philistines came up yet again, and spread themselves in the valley of Rephaim.'),
  ('ed8046d7-a841-5dab-a1d6-3166126104c5', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 23, 23, 'When David inquired of Yahweh, he said, "You shall not go up. Circle around behind them, and attack them over against the mulberry trees.'),
  ('743d568d-c7c8-5d37-a039-f3ce3efd2924', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 24, 24, 'It shall be, when you hear the sound of marching in the tops of the mulberry trees, that then you shall stir yourself up; for then Yahweh has gone out before you to strike the army of the Philistines."'),
  ('0d867590-b77f-595e-a618-382b20434f49', 'badd5c49-42ab-56e6-a552-f4378ada4ce7', NULL, 25, 25, 'David did so, as Yahweh commanded him, and struck the Philistines from Geba until you come to Gezer.'),
  ('edccad73-f4c9-5832-a468-a6f016221a5d', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 1, 1, 'David again gathered together all the chosen men of Israel, thirty thousand.'),
  ('ea5cb759-fecc-543c-ae38-9ae105ec956a', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 2, 2, 'David arose, and went with all the people who were with him, from Baale Judah, to bring up from there the ark of God, which is called by the Name, even the name of Yahweh of Armies who sits [above] the cherubim.'),
  ('d27364b9-2098-5d9f-a174-7b760cb993cf', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 3, 3, 'They set the ark of God on a new cart, and brought it out of the house of Abinadab that was in the hill: and Uzzah and Ahio, the sons of Abinadab, drove the new cart.'),
  ('6e40945c-2329-555d-a313-0a7fa31b8b45', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 4, 4, 'They brought it out of the house of Abinadab, which was in the hill, with the ark of God: and Ahio went before the ark.'),
  ('cab8024f-932a-5141-aaaa-487b03f42664', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 5, 5, 'David and all the house of Israel played before Yahweh with all kinds of [instruments made of] fir wood, and with harps, and with stringed instruments, and with tambourines, and with castanets, and with cymbals.'),
  ('d614e9f4-cd6d-56aa-a3a4-019a7a730ade', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 6, 6, 'When they came to the threshing floor of Nacon, Uzzah put forth [his hand] to the ark of God, and took hold of it; for the cattle stumbled.'),
  ('1b4e4aad-61ce-518e-a9cd-1a1a4995f562', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 7, 7, 'The anger of Yahweh was kindled against Uzzah; and God struck him there for his error; and there he died by the ark of God.'),
  ('b815aa2e-03b8-5ef3-a51e-23864353cde8', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 8, 8, 'David was displeased, because Yahweh had broken forth on Uzzah; and he called that place Perez Uzzah, to this day.'),
  ('276ea90e-6358-5c14-add0-af77f353c43a', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 9, 9, 'David was afraid of Yahweh that day; and he said, "How shall the ark of Yahweh come to me?"'),
  ('48e42232-1fbe-5be3-a263-9866daa18f2e', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 10, 10, 'So David would not move the ark of Yahweh to be with him in the city of David; but David carried it aside into the house of Obed-Edom the Gittite.'),
  ('7ce8e298-32ca-5197-abe6-4900ce190ee0', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 11, 11, 'The ark of Yahweh remained in the house of Obed-Edom the Gittite three months: and Yahweh blessed Obed-Edom, and all his house.'),
  ('2eb950ff-fe1f-5548-acef-75d8c9ffca22', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 12, 12, 'It was told king David, saying, "Yahweh has blessed the house of Obed-Edom, and all that pertains to him, because of the ark of God." David went and brought up the ark of God from the house of Obed-Edom into the city of David with joy.'),
  ('b9437068-0460-5791-a90b-9404bad874a5', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 13, 13, 'It was so, that, when those who bore the ark of Yahweh had gone six paces, he sacrificed an ox and a fattened calf.'),
  ('1316bc43-3a1c-5616-a6b9-9e55281be199', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 14, 14, 'David danced before Yahweh with all his might; and David was clothed in a linen ephod.'),
  ('ce29982c-b43c-5d99-a0fe-d0b933d8f7ce', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 15, 15, 'So David and all the house of Israel brought up the ark of Yahweh with shouting, and with the sound of the trumpet.'),
  ('2f9c7dfd-3d68-54dc-a6db-ef3953b75dce', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 16, 16, 'It was so, as the ark of Yahweh came into the city of David, that Michal the daughter of Saul looked out at the window, and saw king David leaping and dancing before Yahweh; and she despised him in her heart.'),
  ('babb1008-2e95-55a0-a639-82d17f719976', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 17, 17, 'They brought in the ark of Yahweh, and set it in its place, in the midst of the tent that David had pitched for it; and David offered burnt offerings and peace offerings before Yahweh.'),
  ('9d444a89-000d-5c50-a216-a88fe6f87422', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 18, 18, 'When David had made an end of offering the burnt offering and the peace offerings, he blessed the people in the name of Yahweh of Armies.'),
  ('c8198232-1e61-5b51-a16c-d13f0faffee4', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 19, 19, 'He dealt among all the people, even among the whole multitude of Israel, both to men and women, to everyone a cake of bread, and a portion [of flesh], and a cake of raisins. So all the people departed everyone to his house.'),
  ('1361fcc6-1714-568a-a877-72675792fa73', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 20, 20, 'Then David returned to bless his household. Michal the daughter of Saul came out to meet David, and said, "How glorious the king of Israel was today, who uncovered himself today in the eyes of the handmaids of his servants, as one of the vain fellows shamelessly uncovers himself!"'),
  ('d4c47db1-3781-5246-a876-b50a9688de76', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 21, 21, 'David said to Michal, "It was before Yahweh, who chose me above your father, and above all his house, to appoint me prince over the people of Yahweh, over Israel. Therefore will I celebrate before Yahweh.'),
  ('36a3d21a-c918-5bf4-af23-787c410e9544', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 22, 22, 'I will be yet more vile than this, and will be base in my own sight. But of the handmaids of whom you have spoken, they shall honor me."'),
  ('a8e3ad7d-5acb-569b-af49-b1e7d9b4b256', '4ae3bd64-db6c-5196-add4-e45080976565', NULL, 23, 23, 'Michal the daughter of Saul had no child to the day of her death.'),
  ('2f5f181f-fd9b-5e7f-a33d-f8b195d09ca5', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 1, 1, 'It happened, when the king lived in his house, and Yahweh had given him rest from all his enemies all around,'),
  ('80bdb1ab-10e2-5501-a5ac-8e0409cf930b', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 2, 2, 'that the king said to Nathan the prophet, "See now, I dwell in a house of cedar, but the ark of God dwells within curtains."'),
  ('71719f73-137e-5bd0-a854-551524afc4ce', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 3, 3, 'Nathan said to the king, "Go, do all that is in your heart; for Yahweh is with you."'),
  ('372875d2-a64d-53f3-a202-8f47a9e1d89a', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 4, 4, 'It happened the same night, that the word of Yahweh came to Nathan, saying,'),
  ('d1496fcb-d5ef-5f63-aef6-48d90f037d8e', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 5, 5, '"Go and tell my servant David, ''Thus says Yahweh, "Shall you build me a house for me to dwell in?'),
  ('973ad7fd-e169-5e49-a23a-1b6ec22f1dff', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 6, 6, 'For I have not lived in a house since the day that I brought up the children of Israel out of Egypt, even to this day, but have moved around in a tent and in a tabernacle.'),
  ('04599f03-9333-5763-a2c9-98fc16588631', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 7, 7, 'In all places in which I have walked with all the children of Israel, did I say a word to any of the tribes of Israel, whom I commanded to be shepherd of my people Israel, saying, ''Why have you not built me a house of cedar?''"'''),
  ('815a3926-cc47-5bbd-a1ed-f1954878818d', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 8, 8, 'Now therefore you shall tell my servant David this, ''Thus says Yahweh of Armies, "I took you from the sheep pen, from following the sheep, that you should be prince over my people, over Israel.'),
  ('92a8d71d-15b5-59a3-a3fa-39da6ef082cd', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 9, 9, 'I have been with you wherever you went, and have cut off all your enemies from before you. I will make you a great name, like the name of the great ones who are in the earth.'),
  ('6ca9c59d-7783-5440-a8b4-fd9dbd403115', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 10, 10, 'I will appoint a place for my people Israel, and will plant them, that they may dwell in their own place, and be moved no more; neither shall the children of wickedness afflict them any more, as at the first,'),
  ('3a14f528-bdcf-5255-afa8-2eb3a55de279', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 11, 11, 'and as from the day that I commanded judges to be over my people Israel. I will cause you to rest from all your enemies. Moreover Yahweh tells you that Yahweh will make you a house.'),
  ('09457ab2-639d-5aef-a248-cf33adf0f351', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 12, 12, 'When your days are fulfilled, and you shall sleep with your fathers, I will set up your seed after you, who shall proceed out of your bowels, and I will establish his kingdom.'),
  ('45f77498-0547-5235-ab96-f5add07c9ffd', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 13, 13, 'He shall build a house for my name, and I will establish the throne of his kingdom forever.'),
  ('672aa119-bd50-549b-afb9-56d61575ed7e', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 14, 14, 'I will be his father, and he shall be my son. If he commits iniquity, I will chasten him with the rod of men, and with the stripes of the children of men;'),
  ('9a836751-f81e-522f-a5c1-aaad26fdcaeb', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 15, 15, 'but my loving kindness shall not depart from him, as I took it from Saul, whom I put away before you.'),
  ('8c5da51b-de4d-5b27-a39b-94198e5e53ce', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 16, 16, 'Your house and your kingdom shall be made sure forever before you. Your throne shall be established forever."''"'),
  ('2601470f-a055-5479-a216-7e28622e0cee', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 17, 17, 'According to all these words, and according to all this vision, so Nathan spoke to David.'),
  ('83844c80-d8fc-590a-abc5-0430ec152c71', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 18, 18, 'Then David the king went in, and sat before Yahweh; and he said, "Who am I, Lord Yahweh, and what is my house, that you have brought me thus far?'),
  ('654ab062-0b89-5de7-af67-19820adb5dcb', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 19, 19, 'This was yet a small thing in your eyes, Lord Yahweh; but you have spoken also of your servant''s house for a great while to come; and this after the way of men, Lord Yahweh!'),
  ('1fb7c092-9f47-5fde-aafa-c377a78d34a5', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 20, 20, 'What more can David say to you? For you know your servant, Lord Yahweh.'),
  ('e20f2a6b-e559-5dca-a343-902962d5fbe1', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 21, 21, 'For your word''s sake, and according to your own heart, you have worked all this greatness, to make your servant know it.'),
  ('f0600a76-3ba3-5307-ab09-dbe538e9ffeb', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 22, 22, 'Therefore you are great, Yahweh God. For there is none like you, neither is there any God besides you, according to all that we have heard with our ears.'),
  ('62d2bb0c-c099-5fa7-ae5a-15c456062d33', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 23, 23, 'What one nation in the earth is like your people, even like Israel, whom God went to redeem to himself for a people, and to make him a name, and to do great things for you, and awesome things for your land, before your people, whom you redeem to you out of Egypt, [from] the nations and their gods?'),
  ('2cef11c7-5910-59bf-a4cc-915eab026cea', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 24, 24, 'You established for yourself your people Israel to be a people to you forever; and you, Yahweh, became their God.'),
  ('890e2836-06df-5e21-a369-d8b5e2f23684', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 25, 25, 'Now, Yahweh God, the word that you have spoken concerning your servant, and concerning his house, confirm it forever, and do as you have spoken.'),
  ('84c542e3-9594-5dad-aa6e-54e29f11d651', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 26, 26, 'Let your name be magnified forever, saying, ''Yahweh of Armies is God over Israel; and the house of your servant David shall be established before you.'''),
  ('3115b009-fe30-5506-abf1-26a02d6140f7', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 27, 27, 'For you, Yahweh of Armies, the God of Israel, have revealed to your servant, saying, ''I will build you a house.'' Therefore your servant has found in his heart to pray this prayer to you.'),
  ('8f6c6ed6-a416-531c-aafb-0959c7c0ac14', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 28, 28, '"Now, O Lord Yahweh, you are God, and your words are truth, and you have promised this good thing to your servant.'),
  ('fd693c43-bd21-5219-ae2a-ced8b375f162', '57759a59-a99b-59b6-aeb4-d5921087688a', NULL, 29, 29, 'Now therefore let it please you to bless the house of your servant, that it may continue forever before you; for you, Lord Yahweh, have spoken it. Let the house of your servant be blessed forever with your blessing."'),
  ('bae0c821-f8c7-5a8d-ab25-98e7f42890e5', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 1, 1, 'After this it happened that David struck the Philistines, and subdued them: and David took the bridle of the mother city out of the hand of the Philistines.'),
  ('9321b9a4-18c0-5b75-aee2-29a2a8f4697c', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 2, 2, 'He struck Moab, and measured them with the line, making them to lie down on the ground; and he measured two lines to put to death, and one full line to keep alive. The Moabites became servants to David, and brought tribute.'),
  ('25651fb4-9e9e-5f46-ac4e-b13aaeff527f', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 3, 3, 'David struck also Hadadezer the son of Rehob, king of Zobah, as he went to recover his dominion at the River.'),
  ('1cfeb49a-ed32-52b8-a0f3-5723a14a47bc', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 4, 4, 'David took from him one thousand seven hundred horsemen, and twenty thousand footmen: and David hamstrung all the chariot horses, but reserved of them for one hundred chariots.'),
  ('9ffe8568-88f3-5cf5-a41e-0a3354a03fca', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 5, 5, 'When the Syrians of Damascus came to help Hadadezer king of Zobah, David struck of the Syrians two and twenty thousand men.'),
  ('7c30ec5b-da4e-5a18-aa07-0bed97adb664', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 6, 6, 'Then David put garrisons in Syria of Damascus; and the Syrians became servants to David, and brought tribute. Yahweh gave victory to David wherever he went.'),
  ('f78d726e-db49-597c-afdf-54e395a37815', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 7, 7, 'David took the shields of gold that were on the servants of Hadadezer, and brought them to Jerusalem.'),
  ('80ba4eab-a01f-5205-ad80-fb3069eeb9c9', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 8, 8, 'From Betah and from Berothai, cities of Hadadezer, king David took exceeding much brass.'),
  ('b9dc6c20-b2c5-5826-a398-c7c73218ab8f', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 9, 9, 'When Toi king of Hamath heard that David had struck all the army of Hadadezer,'),
  ('6efea200-8eef-5e36-a335-e9c00bb1a234', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 10, 10, 'then Toi sent Joram his son to king David, to Greet him, and to bless him, because he had fought against Hadadezer and struck him: for Hadadezer had wars with Toi. [Joram] brought with him vessels of silver, and vessels of gold, and vessels of brass:'),
  ('da379da0-586b-5136-ac55-0bf76a3a7ac3', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 11, 11, 'These also did king David dedicate to Yahweh, with the silver and gold that he dedicated of all the nations which he subdued;'),
  ('8d254aa5-d42c-5154-a774-9c88a24c4986', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 12, 12, 'of Syria, and of Moab, and of the children of Ammon, and of the Philistines, and of Amalek, and of the spoil of Hadadezer, son of Rehob, king of Zobah.'),
  ('fa4d1120-865e-5b85-adf5-b8c859d4c7e7', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 13, 13, 'David earned a reputation when he returned from smiting the Syrians in the Valley of Salt, even eighteen thousand men.'),
  ('e3bcfe9e-e128-584f-aba5-f64a7891ab73', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 14, 14, 'He put garrisons in Edom; throughout all Edom put he garrisons, and all the Edomites became servants to David. Yahweh gave victory to David wherever he went.'),
  ('6f4e00f4-695e-565c-a95c-848e536463cc', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 15, 15, 'David reigned over all Israel; and David executed justice and righteousness to all his people.'),
  ('21c4541c-6678-540f-abc3-0c432e5fcaf7', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 16, 16, 'Joab the son of Zeruiah was over the army; and Jehoshaphat the son of Ahilud was recorder;'),
  ('e70246ab-ca10-513a-a59e-d47b6bbc3648', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 17, 17, 'and Zadok the son of Ahitub, and Ahimelech the son of Abiathar, were priests; and Seraiah was scribe;'),
  ('95ae1f6f-a408-59f6-aed0-995d2a849457', '9c804e56-069b-5397-a20d-eef16189e866', NULL, 18, 18, 'and Benaiah the son of Jehoiada [was over] the Cherethites and the Pelethites; and David''s sons were chief ministers.'),
  ('3f857e03-3535-5b69-ac7a-8ab8fb55fe40', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 1, 1, 'David said, "Is there yet any who is left of the house of Saul, that I may show him kindness for Jonathan''s sake?"'),
  ('115916d5-6d75-50ec-a043-7c1b8ef25382', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 2, 2, 'There was of the house of Saul a servant whose name was Ziba, and they called him to David; and the king said to him, "Are you Ziba?" He said, "Your servant is he."'),
  ('ae52ca28-8d21-5c9d-a026-c7b51ace81d6', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 3, 3, 'The king said, "Is there not yet any of the house of Saul, that I may show the kindness of God to him?" Ziba said to the king, "Jonathan has yet a son, who is lame of his feet."'),
  ('2deb6e9b-3a05-588d-a4ad-5a5f97a06682', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 4, 4, 'The king said to him, "Where is he?" Ziba said to the king, "Behold, he is in the house of Machir the son of Ammiel, in Lo Debar."'),
  ('5ed10da1-eac5-5a85-a539-b970d792ec14', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 5, 5, 'Then king David sent, and fetched him out of the house of Machir the son of Ammiel, from Lo Debar.'),
  ('e7fdd7b3-308c-545b-a4f3-9c06c785abb2', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 6, 6, 'Mephibosheth, the son of Jonathan, the son of Saul, came to David, and fell on his face, and did obeisance. David said, "Mephibosheth." He answered, "Behold, your servant!"'),
  ('b7a324e7-d2a4-5462-abf5-9a57151d4435', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 7, 7, 'David said to him, "Don''t be afraid of him; for I will surely show you kindness for Jonathan your father''s sake, and will restore to you all the land of Saul your father. You shall eat bread at my table continually."'),
  ('e7d5028d-dd71-5661-a4ea-b0a458215524', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 8, 8, 'He did obeisance, and said, "What is your servant, that you should look on such a dead dog as I am?"'),
  ('c0d1498e-2016-564e-adc9-5b785b2a078f', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 9, 9, 'Then the king called to Ziba, Saul''s servant, and said to him, "All that pertained to Saul and to all his house have I given to your master''s son.'),
  ('df8a4118-e3d5-57db-ad39-a7b19c8a1b2e', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 10, 10, 'You shall till the land for him, you, and your sons, and your servants; and you shall bring in [the fruits], that your master''s son may have bread to eat: but Mephibosheth your master''s son shall eat bread always at my table." Now Ziba had fifteen sons and twenty servants.'),
  ('60ad93fa-88ad-54f8-accd-b48751ce7511', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 11, 11, 'Then Ziba said to the king, "According to all that my lord the king commands his servant, so your shall servant do." So Mephibosheth ate at the king''s table, like one of the king''s sons.'),
  ('63411f97-898e-57a0-aa75-dbb7b7340060', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 12, 12, 'Mephibosheth had a young son, whose name was Mica. All that lived in the house of Ziba were servants to Mephibosheth.'),
  ('c3c86b5e-0556-5ab1-a703-29e205b312ae', '5bacdb1c-2ebb-58ab-a0c8-5c79da2eea38', NULL, 13, 13, 'So Mephibosheth lived in Jerusalem; for he ate continually at the king''s table. He was lame in both his feet.'),
  ('5bee04eb-0eca-54b1-a13a-3326b78396a8', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 1, 1, 'It happened after this, that the king of the children of Ammon died, and Hanun his son reigned in his place.'),
  ('ccc79cf2-4047-5717-ad8c-731131ed435a', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 2, 2, 'David said, "I will show kindness to Hanun the son of Nahash, as his father showed kindness to me." So David sent by his servants to comfort him concerning his father. David''s servants came into the land of the children of Ammon.'),
  ('da473722-7251-59f9-aec0-088bddbff86c', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 3, 3, 'But the princes of the children of Ammon said to Hanun their lord, "Do you think that David honors your father, in that he has sent comforters to you? Hasn''t David sent his servants to you to search the city, and to spy it out, and to overthrow it?"'),
  ('95fbfee4-a48c-5757-a84f-699f27e6c3d1', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 4, 4, 'So Hanun took David''s servants, and shaved off the one half of their beards, and cut off their garments in the middle, even to their buttocks, and sent them away.'),
  ('ec21e6c9-e614-5a14-a994-7d7dbfe21986', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 5, 5, 'When they told it to David, he sent to meet them; for the men were greatly ashamed. The king said, "Wait at Jericho until your beards have grown, and then return."'),
  ('54642c74-f143-5efa-a726-90cce3d09091', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 6, 6, 'When the children of Ammon saw that they were become odious to David, the children of Ammon sent and hired the Syrians of Beth Rehob, and the Syrians of Zobah, twenty thousand footmen, and the king of Maacah with one thousand men, and the men of Tob twelve thousand men.'),
  ('c0055f43-dd35-5de4-a83e-5c0cf9c6b809', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 7, 7, 'When David heard of it, he sent Joab, and all the army of the mighty men.'),
  ('e0c96b4d-eb55-5df0-af7d-676daa54f2f3', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 8, 8, 'The children of Ammon came out, and put the battle in array at the entrance of the gate: and the Syrians of Zobah and of Rehob, and the men of Tob and Maacah, were by themselves in the field.'),
  ('6c00fa19-eab9-5dcd-afb1-3f205ff64592', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 9, 9, 'Now when Joab saw that the battle was set against him before and behind, he chose of all the choice men of Israel, and put them in array against the Syrians:'),
  ('e98ac736-e7d8-5b2f-a7f1-89e6eaa134dc', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 10, 10, 'The rest of the people he committed into the hand of Abishai his brother; and he put them in array against the children of Ammon.'),
  ('44e1f2d6-dd94-5e4c-a457-65a4efcb9c28', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 11, 11, 'He said, "If the Syrians are too strong for me, then you shall help me; but if the children of Ammon are too strong for you, then I will come and help you.'),
  ('1efa6abb-72d1-539c-aa11-47d2aed38a0a', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 12, 12, 'Be courageous, and let us be strong for our people, and for the cities of our God; and Yahweh do that which seems good to him."'),
  ('7980a0ee-3abd-50f0-a347-8bdf30831b82', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 13, 13, 'So Joab and the people who were with him drew near to the battle against the Syrians: and they fled before him.'),
  ('12b9efb0-905f-5ebb-acbb-0acbf2651f19', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 14, 14, 'When the children of Ammon saw that the Syrians had fled, they likewise fled before Abishai, and entered into the city. Then Joab returned from the children of Ammon, and came to Jerusalem.'),
  ('df2f3aa1-73f8-5995-a159-a18f580e86d6', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 15, 15, 'When the Syrians saw that they were defeated by Israel, they gathered themselves together.'),
  ('587a17ca-525d-5ebd-a0ba-5f8c4f8684e4', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 16, 16, 'Hadadezer sent, and brought out the Syrians who were beyond the River: and they came to Helam, with Shobach the captain of the army of Hadadezer at their head.'),
  ('4d30f970-7120-5cce-aaa6-a38d3f4302c1', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 17, 17, 'It was told David; and he gathered all Israel together, and passed over the Jordan, and came to Helam. The Syrians set themselves in array against David, and fought with him.'),
  ('45208a08-37dd-5503-abd2-1574b13cfb0f', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 18, 18, 'The Syrians fled before Israel; and David killed of the Syrians [the men of] seven hundred chariots, and forty thousand horsemen, and struck Shobach the captain of their army, so that he died there.'),
  ('e2dff983-6075-584a-a85b-e849e1e97ff1', '7de03742-202f-5a85-a9d5-ae90b0b4f9d2', NULL, 19, 19, 'When all the kings who were servants to Hadadezer saw that they were defeated before Israel, they made peace with Israel, and served them. So the Syrians feared to help the children of Ammon any more.'),
  ('dd397cbb-4c24-54ee-a5f4-699f909aa8ea', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 1, 1, 'It happened, at the return of the year, at the time when kings go out [to battle], that David sent Joab, and his servants with him, and all Israel; and they destroyed the children of Ammon, and besieged Rabbah. But David stayed at Jerusalem.'),
  ('04106b4f-642c-51da-a4d5-56c55b2d4f33', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 2, 2, 'It happened at evening, that David arose from off his bed, and walked on the roof of the king''s house: and from the roof he saw a woman bathing; and the woman was very beautiful to look on.'),
  ('7f0b06f3-f7e4-504d-a14f-95dc58521876', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 3, 3, 'David sent and inquired after the woman. One said, "Isn''t this Bathsheba, the daughter of Eliam, the wife of Uriah the Hittite?"'),
  ('21051010-2f6c-529b-a589-4e7854f348a3', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 4, 4, 'David sent messengers, and took her; and she came in to him, and he lay with her (for she was purified from her uncleanness); and she returned to her house.'),
  ('029d717f-2900-53df-a1e8-ad8dc17749b7', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 5, 5, 'The woman conceived; and she sent and told David, and said, "I am with child."'),
  ('4dcb3805-09b3-5bd7-a324-af4c5dbe359f', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 6, 6, 'David sent to Joab, [saying], "Send me Uriah the Hittite." Joab sent Uriah to David.'),
  ('3a5ad56b-147d-5934-a3a9-e83f6db2da2f', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 7, 7, 'When Uriah was come to him, David asked of him how Joab did, and how the people fared, and how the war prospered.'),
  ('31687e62-0892-5d02-a1b4-8e8a64ebd8ef', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 8, 8, 'David said to Uriah, "Go down to your house, and wash your feet." Uriah departed out of the king''s house, and a gift from the king was sent after him.'),
  ('dbe19b8f-4202-5036-ae82-8f55d004a72d', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 9, 9, 'But Uriah slept at the door of the king''s house with all the servants of his lord, and didn''t go down to his house.'),
  ('0b01be9d-c3bd-56b6-a6b2-bfbc207fe7ad', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 10, 10, 'When they had told David, saying, "Uriah didn''t go down to his house," David said to Uriah, "Haven''t you come from a journey? Why didn''t you go down to your house?"'),
  ('a4b8daf1-773d-5242-a120-d7e3d6e1a73c', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 11, 11, 'Uriah said to David, "The ark, Israel, and Judah, are staying in tents; and my lord Joab, and the servants of my lord, are encamped in the open field. Shall I then go into my house to eat and to drink, and to lie with my wife? As you live, and as your soul lives, I will not do this thing!"'),
  ('8191e293-409e-5539-a5d2-4dbeba9fbe38', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 12, 12, 'David said to Uriah, "Stay here today also, and tomorrow I will let you depart." So Uriah stayed in Jerusalem that day, and the next day.'),
  ('cfc43338-bc07-5317-a4cb-bd666d0c6205', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 13, 13, 'When David had called him, he ate and drink before him; and he made him drunk. At evening, he went out to lie on his bed with the servants of his lord, but didn''t go down to his house.'),
  ('dd30c612-9745-57c5-a984-aaa68b96efe6', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 14, 14, 'It happened in the morning, that David wrote a letter to Joab, and sent it by the hand of Uriah.'),
  ('fd8b32f1-20d6-5c7b-afd6-9ead6717de8a', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 15, 15, 'He wrote in the letter, saying, "Send Uriah to the forefront of the hottest battle, and retreat from him, that he may be struck, and die."'),
  ('a325a4d4-09ca-564e-a0f1-1b318d183e5a', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 16, 16, 'It happened, when Joab kept watch on the city, that he assigned Uriah to the place where he knew that valiant men were.'),
  ('62a09ae2-6c80-5735-a870-010587b91cf9', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 17, 17, 'The men of the city went out, and fought with Joab. Some of the people fell, even of the servants of David; and Uriah the Hittite died also.'),
  ('b66e3d27-b521-5fb3-a9a8-92a5329614c3', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 18, 18, 'Then Joab sent and told David all the things concerning the war;'),
  ('90dfd9d4-ab44-53e3-a027-0489bf24ee28', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 19, 19, 'and he commanded the messenger, saying, "When you have finished telling all the things concerning the war to the king,'),
  ('d67d74c4-3870-5187-affd-14583a7dadfb', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 20, 20, 'it shall be that, if the king''s wrath arise, and he asks you, ''Why did you go so near to the city to fight? Didn''t you know that they would shoot from the wall?'),
  ('867cf202-8642-5962-a4be-e737d72add34', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 21, 21, 'who struck Abimelech the son of Jerubbesheth? Didn''t a woman cast an upper millstone on him from the wall, so that he died at Thebez? Why did you go so near the wall?'' then you shall say, ''Your servant Uriah the Hittite is dead also.''"'),
  ('5b7c36e6-ff93-535b-a5df-f01b5179f4d0', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 22, 22, 'So the messenger went, and came and showed David all that Joab had sent him for.'),
  ('84e62cf0-675c-526b-ab5f-eafed23c2fd1', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 23, 23, 'The messenger said to David, "The men prevailed against us, and came out to us into the field, and we were on them even to the entrance of the gate.'),
  ('fa1882f9-f936-552c-abea-15a9f3d52e88', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 24, 24, 'The shooters shot at your servants from off the wall; and some of the king''s servants are dead, and your servant Uriah the Hittite is dead also."'),
  ('03b140dc-7e4f-5a3a-a3bc-915519e63d9a', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 25, 25, 'Then David said to the messenger, "Thus you shall tell Joab, ''Don''t let this thing displease you, for the sword devours one as well as another. Make your battle stronger against the city, and overthrow it.'' Encourage him."'),
  ('47af9074-72e1-5261-a67e-d0b4bbe6186c', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 26, 26, 'When the wife of Uriah heard that Uriah her husband was dead, she made lamentation for her husband.'),
  ('fe04f63b-079a-580e-a29e-da3c1c1d2141', '49679a51-bbdb-5e71-a8f1-077cfc7f2cb3', NULL, 27, 27, 'When the mourning was past, David sent and took her home to his house, and she became his wife, and bore him a son. But the thing that David had done displeased Yahweh.'),
  ('77c66bbf-999a-543f-ab10-7e64d40ed6a3', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 1, 1, 'Yahweh sent Nathan to David. He came to him, and said to him, "There were two men in one city; the one rich, and the other poor.'),
  ('e9ce5e98-f16e-5aa8-ac4f-458cb077a89a', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 2, 2, 'The rich man had very many flocks and herds,'),
  ('b6168b77-1349-5275-a0fa-b2dbca97c63c', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 3, 3, 'but the poor man had nothing, except one little ewe lamb, which he had bought and raised. It grew up together with him, and with his children. It ate of his own food, drank of his own cup, and lay in his bosom, and was to him like a daughter.'),
  ('845f81cd-cb2e-5763-a73d-88f72a2953af', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 4, 4, 'A traveler came to the rich man, and he spared to take of his own flock and of his own herd, to dress for the wayfaring man who had come to him, but took the poor man''s lamb, and dressed it for the man who had come to him."'),
  ('8e110db2-eb64-529f-affd-9f44f426ddd1', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 5, 5, 'David''s anger was greatly kindled against the man, and he said to Nathan, "As Yahweh lives, the man who has done this is worthy to die!'),
  ('b7154cad-f792-5964-aa92-b75aa53c8b18', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 6, 6, 'He shall restore the lamb fourfold, because he did this thing, and because he had no pity!"'),
  ('1f284443-fb52-5f8a-a7ec-75007b95fb90', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 7, 7, 'Nathan said to David, "You are the man. This is what Yahweh, the God of Israel, says: ''I anointed you king over Israel, and I delivered you out of the hand of Saul.'),
  ('83bd350d-f69c-51e0-a60e-f37b6b08a877', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 8, 8, 'I gave you your master''s house, and your master''s wives into your bosom, and gave you the house of Israel and of Judah; and if that would have been too little, I would have added to you many more such things.'),
  ('eb55d64d-893a-5ace-acac-f4e327d238d7', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 9, 9, 'Why have you despised the word of Yahweh, to do that which is evil in his sight? You have struck Uriah the Hittite with the sword, and have taken his wife to be your wife, and have slain him with the sword of the children of Ammon.'),
  ('f9805577-f9c3-592f-a2e2-c83ec3490577', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 10, 10, 'Now therefore the sword will never depart from your house, because you have despised me, and have taken the wife of Uriah the Hittite to be your wife.'''),
  ('1023d17f-0251-5da0-a42e-3b2fdacec610', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 11, 11, '"This is what Yahweh says: ''Behold, I will raise up evil against you out of your own house; and I will take your wives before your eyes, and give them to your neighbor, and he will lie with your wives in the sight of this sun.'),
  ('feef16cc-0ef6-5fb5-aa65-d5e740236991', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 12, 12, 'For you did it secretly, but I will do this thing before all Israel, and before the sun.''"'),
  ('1a6fe2ec-6e50-5ac1-abdd-522cee298c60', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 13, 13, 'David said to Nathan, "I have sinned against Yahweh." Nathan said to David, "Yahweh also has put away your sin. You will not die.'),
  ('6085c3ac-d3c4-5274-a214-813d66236623', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 14, 14, 'However, because by this deed you have given great occasion to Yahweh''s enemies to blaspheme, the child also who is born to you shall surely die."'),
  ('87f03f3a-c83c-5119-ab34-d942f2a1df98', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 15, 15, 'Nathan departed to his house. Yahweh struck the child that Uriah''s wife bore to David, and it was very sick.'),
  ('d339c61f-fc9e-5daa-a3fb-b3b8de790a4b', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 16, 16, 'David therefore begged God for the child; and David fasted, and went in, and lay all night on the earth.'),
  ('5034270e-b14b-5326-a434-28ab862d6620', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 17, 17, 'The elders of his house arose, [and stood] beside him, to raise him up from the earth: but he would not, neither did he eat bread with them.'),
  ('2386adc7-cbed-5d5b-a28b-56ac4166f1f1', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 18, 18, 'It happened on the seventh day, that the child died. The servants of David feared to tell him that the child was dead; for they said, "Behold, while the child was yet alive, we spoke to him, and he didn''t listen to our voice. How will he then harm himself, if we tell him that the child is dead?"'),
  ('77493e43-e1bc-53ac-a88e-fae93ed8e91f', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 19, 19, 'But when David saw that his servants were whispering together, David perceived that the child was dead; and David said to his servants, "Is the child dead?" They said, "He is dead."'),
  ('0e92d31f-65d2-527e-abff-f0cfcffecfbd', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 20, 20, 'Then David arose from the earth, and washed, and anointed himself, and changed his clothing; and he came into the house of Yahweh, and worshiped: then he came to his own house; and when he required, they set bread before him, and he ate.'),
  ('21083455-ca2f-505b-af3f-2d69f9629e7b', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 21, 21, 'Then his servants said to him, "What is this that you have done? You fasted and wept for the child while he was alive; but when the child was dead, you rose up and ate bread."'),
  ('602ce3c2-bd33-54bf-ae43-40b9ed7edcd4', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 22, 22, 'He said, "While the child was yet alive, I fasted and wept; for I said, ''Who knows whether Yahweh will not be gracious to me, that the child may live?'''),
  ('87a7e4d6-b9f5-5f68-a0c9-98f79d6e83d6', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 23, 23, 'But now he is dead, why should I fast? Can I bring him back again? I shall go to him, but he will not return to me."'),
  ('b0758620-2045-58d6-a02f-fdd0a31bc71b', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 24, 24, 'David comforted Bathsheba his wife, and went in to her, and lay with her. She bore a son, and he called his name Solomon. Yahweh loved him;'),
  ('7c0528fd-b6ce-5f6b-ab2b-510f62187b47', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 25, 25, 'and he sent by the hand of Nathan the prophet; and he named him Jedidiah, for Yahweh''s sake.'),
  ('250fbd9a-bc9f-5946-ac2b-329687286ca1', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 26, 26, 'Now Joab fought against Rabbah of the children of Ammon, and took the royal city.'),
  ('0ba82a59-cf7a-5880-afd7-47bb02a79243', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 27, 27, 'Joab sent messengers to David, and said, "I have fought against Rabbah. Yes, I have taken the city of waters.'),
  ('535baaee-2aa6-55f7-a653-a23ddd6db853', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 28, 28, 'Now therefore gather the rest of the people together, and encamp against the city, and take it; lest I take the city, and it be called after my name."'),
  ('64636084-1863-5bc6-aeb2-2cb3fd1fdbcc', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 29, 29, 'David gathered all the people together, and went to Rabbah, and fought against it, and took it.'),
  ('17711300-52da-55f7-a4ee-ed35fd008284', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 30, 30, 'He took the crown of their king from off his head; and its weight was a talent of gold, and [in it were] precious stones; and it was set on David''s head. He brought forth the spoil of the city, exceeding much.'),
  ('a3e016ab-1afb-5991-a83a-7f44b05baefa', '37033964-d7d9-50ed-af50-17618fd917d9', NULL, 31, 31, 'He brought forth the people who were therein, and put them under saws, and under iron picks, and under axes of iron, and made them pass through the brick kiln: and he did so to all the cities of the children of Ammon. David and all the people returned to Jerusalem.'),
  ('2b442b71-4c2d-5603-aacd-9bce7c3ac794', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 1, 1, 'It happened after this, that Absalom the son of David had a beautiful sister, whose name was Tamar; and Amnon the son of David loved her.'),
  ('13829b44-2df7-5550-aa51-d816cf6c2c98', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 2, 2, 'Amnon was so troubled that he fell sick because of his sister Tamar; for she was a virgin; and it seemed hard to Amnon to do anything to her.'),
  ('6badb268-78d3-58d1-af2e-5bb808621213', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 3, 3, 'But Amnon had a friend, whose name was Jonadab, the son of Shimeah, David''s brother; and Jonadab was a very subtle man.'),
  ('907ee660-c475-52f8-a7da-22ab3680a834', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 4, 4, 'He said to him, "Why, son of the king, are you so sad from day to day? Won''t you tell me?" Amnon said to him, "I love Tamar, my brother Absalom''s sister."'),
  ('4c537871-6076-5ae2-add3-626442383edc', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 5, 5, 'Jonadab said to him, "Lay down on your bed, and pretend to be sick. When your father comes to see you, tell him, ''Please let my sister Tamar come and give me bread to eat, and dress the food in my sight, that I may see it, and eat it from her hand.''"'),
  ('fbf1f97b-f89b-5211-a9f4-2127d2628fa4', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 6, 6, 'So Amnon lay down and faked being sick. When the king came to see him, Amnon said to the king, "Please let my sister Tamar come, and make me a couple of cakes in my sight, that I may eat from her hand."'),
  ('929218d3-ee84-5d3e-a66b-895712d55220', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 7, 7, 'Then David sent home to Tamar, saying, "Go now to your brother Amnon''s house, and prepare food for him."'),
  ('7486c7d7-ac8a-5435-a54d-0800d29547c5', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 8, 8, 'So Tamar went to her brother Amnon''s house; and he was laid down. She took dough, and kneaded it, and made cakes in his sight, and baked the cakes.'),
  ('b658c078-4d0f-549e-aa9e-1449323bd8e8', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 9, 9, 'She took the pan, and poured them out before him; but he refused to eat. Amnon said, "Have all men leave me." Every man went out from him.'),
  ('bcf97774-d060-523e-a62b-65ecd187811a', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 10, 10, 'Amnon said to Tamar, "Bring the food into the room, that I may eat from your hand." Tamar took the cakes which she had made, and brought them into the room to Amnon her brother.'),
  ('06280cd2-02b2-564d-a93f-f7bbde4d7458', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 11, 11, 'When she had brought them near to him to eat, he took hold of her, and said to her, "Come, lie with me, my sister!"'),
  ('68bfc7a5-729c-518b-a390-a059b6b15c2b', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 12, 12, 'She answered him, "No, my brother, do not force me! For no such thing ought to be done in Israel. Don''t you do this folly.'),
  ('cb692858-d649-5408-a90c-08518cd87b4f', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 13, 13, 'I, where would I carry my shame? And as for you, you will be as one of the fools in Israel. Now therefore, please speak to the king; for he will not withhold me from you."'),
  ('30631473-ee72-57ad-a0d1-2512dd969b9c', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 14, 14, 'However he would not listen to her voice; but being stronger than she, he forced her, and lay with her.'),
  ('7381caaa-cc5b-5764-a641-58a975ae650c', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 15, 15, 'Then Amnon hated her with exceeding great hatred; for the hatred with which he hated her was greater than the love with which he had loved her. Amnon said to her, "Arise, be gone!"'),
  ('f45c646f-9901-5c9c-a7f1-66161c24653d', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 16, 16, 'She said to him, "Not so, because this great wrong in sending me away is worse than the other that you did to me!" But he would not listen to her.'),
  ('f3b83df8-7ef2-5626-ae9e-5766d971b280', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 17, 17, 'Then he called his servant who ministered to him, and said, "Put now this woman out from me, and bolt the door after her."'),
  ('dbfb6b09-f5cd-5211-afa9-d56246f21a9c', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 18, 18, 'She had a garment of various colors on her; for with such robes were the king''s daughters who were virgins dressed. Then his servant brought her out, and bolted the door after her.'),
  ('e7af1867-9ec7-5c5e-a752-879acd451271', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 19, 19, 'Tamar put ashes on her head, and tore her garment of various colors that was on her; and she laid her hand on her head, and went her way, crying aloud as she went.'),
  ('88d50dbb-770d-501a-a613-17b48fcc683c', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 20, 20, 'Absalom her brother said to her, "Has Amnon your brother been with you? But now hold your peace, my sister. He is your brother. Don''t take this thing to heart." So Tamar remained desolate in her brother Absalom''s house.'),
  ('b81d16d0-2ed2-5708-acf7-bb13e091255f', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 21, 21, 'But when king David heard of all these things, he was very angry.'),
  ('b4537897-caba-584d-a8e8-6fbc1a5590c0', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 22, 22, 'Absalom spoke to Amnon neither good nor bad; for Absalom hated Amnon, because he had forced his sister Tamar.'),
  ('56aaa4de-b12e-5da4-a627-e970b4d0e44e', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 23, 23, 'It happened after two full years, that Absalom had sheepshearers in Baal Hazor, which is beside Ephraim: and Absalom invited all the king''s sons.'),
  ('64ad1fb0-3195-572a-a6a1-442318af48a2', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 24, 24, 'Absalom came to the king, and said, "See now, your servant has sheepshearers. Please let the king and his servants go with your servant."'),
  ('36c0a5ee-d839-5e8f-a103-ae4cba8cf970', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 25, 25, 'The king said to Absalom, "No, my son, let us not all go, lest we be burdensome to you." He pressed him; however he would not go, but blessed him.'),
  ('607c170e-3498-5aeb-a404-484b9649152e', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 26, 26, 'Then Absalom said, "If not, please let my brother Amnon go with us." The king said to him, "Why should he go with you?"'),
  ('3cabe678-f88b-5110-a16e-07c242dd3c1b', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 27, 27, 'But Absalom pressed him, and he let Amnon and all the king''s sons go with him.'),
  ('52ffed2b-44f9-56ca-ac88-4077c1854835', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 28, 28, 'Absalom commanded his servants, saying, "Mark now, when Amnon''s heart is merry with wine; and when I tell you, ''Strike Amnon,'' then kill him. Don''t be afraid. Haven''t I commanded you? Be courageous, and be valiant!"'),
  ('94fc6347-883e-56d1-a3f9-dc4baa9a43c0', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 29, 29, 'The servants of Absalom did to Amnon as Absalom had commanded. Then all the king''s sons arose, and every man got up on his mule, and fled.'),
  ('462d1b9d-420b-5a17-a231-c8691da892a9', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 30, 30, 'It happened, while they were in the way, that the news came to David, saying, "Absalom has slain all the king''s sons, and there is not one of them left!"'),
  ('35ff2069-c037-5e52-a81e-2d0bcd2885aa', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 31, 31, 'Then the king arose, and tore his garments, and lay on the earth; and all his servants stood by with their clothes torn.'),
  ('1e8a5fd8-7ea7-5b2b-aaec-8a36a81526b3', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 32, 32, 'Jonadab, the son of Shimeah, David''s brother, answered, "Don''t let my lord suppose that they have killed all the young men the king''s sons; for Amnon only is dead; for by the appointment of Absalom this has been determined from the day that he forced his sister Tamar.'),
  ('a91a3d84-8a2d-552c-a1fa-3e483b4976c3', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 33, 33, 'Now therefore don''t let my lord the king take the thing to his heart, to think that all the king''s sons are dead; for Amnon only is dead."'),
  ('500df1a3-292a-5d7e-a2be-2c85f3105e5f', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 34, 34, 'But Absalom fled. The young man who kept the watch lifted up his eyes, and looked, and behold, many people were coming by way of the hillside behind him.'),
  ('c6d00599-3a76-5cb3-a6a1-83f813ed4fdb', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 35, 35, 'Jonadab said to the king, "Behold, the king''s sons are coming! It is as your servant said."'),
  ('13ada8b9-7400-53c6-a805-a5683c837268', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 36, 36, 'It happened, as soon as he had finished speaking, that behold, the king''s sons came, and lifted up their voice, and wept. The king also and all his servants wept bitterly.'),
  ('c74e020b-ca6a-5885-ae96-6706f6685e44', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 37, 37, 'But Absalom fled, and went to Talmai the son of Ammihur, king of Geshur. David mourned for his son every day.'),
  ('ae614798-5245-5f12-a665-1f2a219d48f8', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 38, 38, 'So Absalom fled, and went to Geshur, and was there three years.'),
  ('0e70a4e7-205d-5584-abc3-803acaf09fce', 'f60317ef-a168-516a-ad40-325b91a4506d', NULL, 39, 39, '[the soul of] king David longed to go forth to Absalom: for he was comforted concerning Amnon, since he was dead.'),
  ('d5020936-5db3-5672-ae00-dbdb72f8bc4f', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 1, 1, 'Now Joab the son of Zeruiah perceived that the king''s heart was toward Absalom.'),
  ('fdcc61ea-4ca8-5fc5-ab16-48ba14498bde', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 2, 2, 'Joab sent to Tekoa, and fetched there a wise woman, and said to her, "Please act like a mourner, and put on mourning clothing, please, and don''t anoint yourself with oil, but be as a woman who has mourned a long time for the dead.'),
  ('4821b1ac-1ff1-521f-ab7d-5e6076eca49e', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 3, 3, 'Go in to the king, and speak like this to him." So Joab put the words in her mouth.'),
  ('1b522d97-bd09-584c-aecb-e68f6d9e1bf5', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 4, 4, 'When the woman of Tekoa spoke to the king, she fell on her face to the ground, and did obeisance, and said, "Help, O king!"')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2b53ee32-0c77-5164-a2d6-9428e9e3f7ad', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 5, 5, 'The king said to her, "What ails you?" She answered, "Truly I am a widow, and my husband is dead.'),
  ('6cd2b840-2367-5b36-aec1-ad8a8546b32d', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 6, 6, 'Your handmaid had two sons, and they both fought together in the field, and there was no one to part them, but the one struck the other, and killed him.'),
  ('d23b5241-6f56-5e18-aa1c-4ac560e93bb5', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 7, 7, 'Behold, the whole family has risen against your handmaid, and they say, ''Deliver him who struck his brother, that we may kill him for the life of his brother whom he killed, and so destroy the heir also.'' Thus they would quench my coal which is left, and would leave to my husband neither name nor remainder on the surface of the earth."'),
  ('efedbaf6-d047-5e6e-ae3c-0788699e21de', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 8, 8, 'The king said to the woman, "Go to your house, and I will give a command concerning you."'),
  ('3af90db6-08ac-5447-a168-417d41fa712d', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 9, 9, 'The woman of Tekoa said to the king, "My lord, O king, the iniquity be on me, and on my father''s house; and the king and his throne be guiltless."'),
  ('3f8b2edd-04df-589f-a955-f73a0661bc94', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 10, 10, 'The king said, "Whoever says anything to you, bring him to me, and he shall not touch you any more."'),
  ('adafb0b8-5b57-53f1-ab2e-42f2345ecad0', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 11, 11, 'Then she said, "Please let the king remember Yahweh your God, that the avenger of blood destroy not any more, lest they destroy my son." He said, "As Yahweh lives, not one hair of your son shall fall to the earth."'),
  ('633ce7e7-120e-536f-a678-96ab4cdcd817', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 12, 12, 'Then the woman said, "Please let your handmaid speak a word to my lord the king." He said, "Say on."'),
  ('e4c1dbf9-07d4-5a95-ae78-9f1024ad72c0', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 13, 13, 'The woman said, "Why then have you devised such a thing against the people of God? For in speaking this word the king is as one who is guilty, in that the king does not bring home again his banished one.'),
  ('e59405ac-604c-56ef-a1d4-2a88e96c16c2', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 14, 14, 'For we must die, and are as water split on the ground, which can''t be gathered up again; neither does God take away life, but devises means, that he who is banished not be an outcast from him.'),
  ('17268c8b-d94b-5c30-a034-7de42dfd9511', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 15, 15, 'Now therefore seeing that I have come to speak this word to my lord the king, it is because the people have made me afraid: and your handmaid said, ''I will now speak to the king; it may be that the king will perform the request of his servant.'''),
  ('227b84a3-e4c4-50f7-a84c-9a7caaf01464', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 16, 16, 'For the king will hear, to deliver his servant out of the hand of the man who would destroy me and my son together out of the inheritance of God.'),
  ('d99bc292-0550-5535-a7cd-8e2c943c1c7f', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 17, 17, 'Then your handmaid said, ''Please let the word of my lord the king bring rest; for as an angel of God, so is my lord the king to discern good and bad. May Yahweh, your God, be with you.''"'),
  ('98aedded-d71e-52fd-a5f9-0cd3188f3482', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 18, 18, 'Then the king answered the woman, "Please don''t hide anything from me that I ask you." The woman said, "Let my lord the king now speak."'),
  ('01ba9339-a29a-5b79-a06b-c1652929d2ff', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 19, 19, 'The king said, "Is the hand of Joab with you in all this?" The woman answered, "As your soul lives, my lord the king, no one can turn to the right hand or to the left from anything that my lord the king has spoken; for your servant Joab, he urged me, and he put all these words in the mouth of your handmaid;'),
  ('67fcc6c4-a907-5897-af40-4882b647f814', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 20, 20, 'to change the face of the matter has your servant Joab done this thing. My lord is wise, according to the wisdom of an angel of God, to know all things that are in the earth."'),
  ('745c30be-f136-5753-aa44-f81d2df5363a', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 21, 21, 'The king said to Joab, "Behold now, I have done this thing. Go therefore, bring the young man Absalom back."'),
  ('60fd6a0e-6d25-5c66-a583-99ff85c8e8d4', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 22, 22, 'Joab fell to the ground on his face, and did obeisance, and blessed the king. Joab said, "Today your servant knows that I have found favor in your sight, my lord, king, in that the king has performed the request of his servant."'),
  ('0a885779-0f75-52f5-a940-13b4906110fe', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 23, 23, 'So Joab arose and went to Geshur, and brought Absalom to Jerusalem.'),
  ('5fa442ad-7a18-5577-afab-2646f8c7c8aa', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 24, 24, 'The king said, "Let him return to his own house, but let him not see my face." So Absalom returned to his own house, and didn''t see the king''s face.'),
  ('fd162d30-53d1-5e08-a0cc-1f2ec6cc5a69', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 25, 25, 'Now in all Israel there was none to be so much praised as Absalom for his beauty: from the sole of his foot even to the crown of his head there was no blemish in him.'),
  ('801470b0-bd98-58e0-a41e-baa4bbfbecc9', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 26, 26, 'When he cut the hair of his head (now it was at every year''s end that he cut it; because it was heavy on him, therefore he cut it); he weighed the hair of his head at two hundred shekels, after the king''s weight.'),
  ('da9ee37e-c030-5071-a2cf-23e03ba13bfd', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 27, 27, 'To Absalom there were born three sons, and one daughter, whose name was Tamar: she was a woman of a beautiful face.'),
  ('2035f897-28b9-5168-a84c-9f4884049908', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 28, 28, 'Absalom lived two full years in Jerusalem; and he didn''t see the king''s face.'),
  ('9a4f9aab-a7b0-56a6-ac5b-0abe378d866e', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 29, 29, 'Then Absalom sent for Joab, to send him to the king; but he would not come to him: and he sent again a second time, but he would not come.'),
  ('edb431ee-fa93-5672-a8d3-26875bf6474c', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 30, 30, 'Therefore he said to his servants, "Behold, Joab''s field is near mine, and he has barley there. Go and set it on fire." Absalom''s servants set the field on fire.'),
  ('ed3b0dc1-ab3d-56f6-a189-c571710d6bbe', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 31, 31, 'Then Joab arose, and came to Absalom to his house, and said to him, "Why have your servants set my field on fire?"'),
  ('ae72bce9-2575-5417-a9c6-9641d2d78ade', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 32, 32, 'Absalom answered Joab, "Behold, I sent to you, saying, ''Come here, that I may send you to the king, to say, "Why have I come from Geshur? It would be better for me to be there still. Now therefore let me see the king''s face; and if there is iniquity in me, let him kill me."''"'),
  ('079f0d66-91c0-58c1-ae7e-2fff332c1b55', '9dad962e-0dc1-5593-ace0-5e1a3733e765', NULL, 33, 33, 'So Joab came to the king, and told him; and when he had called for Absalom, he came to the king, and bowed himself on his face to the ground before the king: and the king kissed Absalom.'),
  ('a44a16fb-4318-5168-a0f7-7874ec1e9eac', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 1, 1, 'It happened after this, that Absalom prepared him a chariot and horses, and fifty men to run before him.'),
  ('fda0751e-48bc-5d10-a2fc-a786807ab7d7', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 2, 2, 'Absalom rose up early, and stood beside the way of the gate. It was so, that when any man had a suit which should come to the king for judgment, then Absalom called to him, and said, "What city are you from?" He said, "Your servant is of one of the tribes of Israel."'),
  ('040caadc-c9ec-5c3d-a1ed-7ad0f1bb0b98', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 3, 3, 'Absalom said to him, "Behold, your matters are good and right; but there is no man deputized by the king to hear you."'),
  ('7d519a43-409a-524a-a222-8d730c87933a', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 4, 4, 'Absalom said moreover, "Oh that I were made judge in the land, that every man who has any suit or cause might come to me, and I would do him justice!"'),
  ('d668a4bf-cfe0-5bc1-a7f5-2e417e23485c', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 5, 5, 'It was so, that when any man came near to do him obeisance, he put forth his hand, and took hold of him, and kissed him.'),
  ('f3b430d2-e241-500e-a7fc-d4cfdcd00e4a', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 6, 6, 'Absalom did this sort of thing to all Israel who came to the king for judgment. So Absalom stole the hearts of the men of Israel.'),
  ('8e3852e6-5aa6-53d0-a86d-a253ec988ed9', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 7, 7, 'It happened at the end of forty years, that Absalom said to the king, "Please let me go and pay my vow, which I have vowed to Yahweh, in Hebron.'),
  ('5b444214-462c-5804-af52-9d0289be2c3e', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 8, 8, 'For your servant vowed a vow while I stayed at Geshur in Syria, saying, ''If Yahweh shall indeed bring me again to Jerusalem, then I will serve Yahweh.''"'),
  ('4867df4e-d9f3-58f1-a553-5c5eacad0bbf', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 9, 9, 'The king said to him, "Go in peace." So he arose, and went to Hebron.'),
  ('5bab435f-4557-5efd-a90c-ec4694466c49', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 10, 10, 'But Absalom sent spies throughout all the tribes of Israel, saying, "As soon as you hear the sound of the trumpet, then you shall say, ''Absalom is king in Hebron!''"'),
  ('ae953b6f-3d3e-5773-ac2b-fc5290e79be3', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 11, 11, 'Two hundred men went with Absalom out of Jerusalem, who were invited, and went in their simplicity; and they didn''t know anything.'),
  ('aac4326c-3950-523a-a650-61b81a9c033b', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 12, 12, 'Absalom sent for Ahithophel the Gilonite, David''s counselor, from his city, even from Giloh, while he was offering the sacrifices. The conspiracy was strong; for the people increased continually with Absalom.'),
  ('e0b07461-1906-542f-a3d6-d3f919e62f94', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 13, 13, 'A messenger came to David, saying, "The hearts of the men of Israel are after Absalom."'),
  ('ca0cb285-4f66-52a4-a89b-8745e4b19d48', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 14, 14, 'David said to all his servants who were with him at Jerusalem, "Arise, and let us flee; for else none of us shall escape from Absalom. Make speed to depart, lest he overtake us quickly, and bring down evil on us, and strike the city with the edge of the sword."'),
  ('c10d8005-f175-5116-aaed-ffc7ee3b6fbf', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 15, 15, 'The king''s servants said to the king, "Behold, your servants are ready to do whatever my lord the king chooses."'),
  ('cdb504d5-15bd-542b-a4ee-fd388872e65e', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 16, 16, 'The king went forth, and all his household after him. The king left ten women, who were concubines, to keep the house.'),
  ('5432603c-abc3-5be9-a50c-e52f977782fd', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 17, 17, 'The king went forth, and all the people after him; and they stayed in Beth Merhak.'),
  ('adaa8a9f-65e6-5f8d-a665-f9d4d875fb2a', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 18, 18, 'All his servants passed on beside him; and all the Cherethites, and all the Pelethites, and all the Gittites, six hundred men who came after him from Gath, passed on before the king.'),
  ('974874d0-62c5-5e2e-a8ee-d7dba0aedba4', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 19, 19, 'Then the king said to Ittai the Gittite, "Why do you also go with us? Return, and stay with the king; for you are a foreigner, and also an exile. Return to your own place.'),
  ('5eea1eb3-ac93-5212-a930-d31cf5a665bf', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 20, 20, 'Whereas you came but yesterday, should I this day make you go up and down with us, since I go where I may? Return, and take back your brothers. Mercy and truth be with you."'),
  ('56d1e985-dcde-5cd1-a684-8c29afca2f1c', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 21, 21, 'Ittai answered the king, and said, "As Yahweh lives, and as my lord the king lives, surely in what place my lord the king shall is, whether for death or for life, even there also will your servant be."'),
  ('d286caab-f0b7-552a-a7c9-c346925f322c', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 22, 22, 'David said to Ittai, "Go and pass over." Ittai the Gittite passed over, and all his men, and all the little ones who were with him.'),
  ('7b501b45-ff4d-510f-ac6f-bec940438378', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 23, 23, 'All the country wept with a loud voice, and all the people passed over: the king also himself passed over the brook Kidron, and all the people passed over, toward the way of the wilderness.'),
  ('b828c3e9-91ce-5eae-aef2-094d9d7dd9e2', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 24, 24, 'Behold, Zadok also came, and all the Levites with him, bearing the ark of the covenant of God; and they set down the ark of God; and Abiathar went up, until all the people finished passing out of the city.'),
  ('6e0f5224-88e4-50d1-ae6e-19d23d117906', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 25, 25, 'The king said to Zadok, "Carry back the ark of God into the city. If I find favor in the eyes of Yahweh, he will bring me again, and show me both it, and his habitation;'),
  ('d313827d-3fef-58ab-af5e-036140500a92', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 26, 26, 'but if he say thus, ''I have no delight in you;'' behold, here am I. Let him do to me as seems good to him."'),
  ('c628e0f6-0b8c-5777-a735-a4adc340f8dd', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 27, 27, 'The king said also to Zadok the priest, "Aren''t you a seer? Return into the city in peace, and your two sons with you, Ahimaaz your son, and Jonathan the son of Abiathar.'),
  ('7e898d7b-4859-50f0-a582-bd661388e87a', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 28, 28, 'Behold, I will stay at the fords of the wilderness, until word comes from you to inform me."'),
  ('ea77c092-f8e0-58e4-ad08-622cfa12ff16', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 29, 29, 'Zadok therefore and Abiathar carried the ark of God again to Jerusalem; and they stayed there.'),
  ('7b1b4c9f-acf9-5220-a34b-acb14e4a73a8', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 30, 30, 'David went up by the ascent of the [Mount of] Olives, and wept as he went up; and he had his head covered, and went barefoot: and all the people who were with him covered every man his head, and they went up, weeping as they went up.'),
  ('985a0291-90c0-5a24-a265-218b32e92986', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 31, 31, 'Someone told David, saying, "Ahithophel is among the conspirators with Absalom." David said, "Yahweh, please turn the counsel of Ahithophel into foolishness."'),
  ('367daf3d-c2f2-5174-a235-1b306031f084', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 32, 32, 'It happened that when David had come to the top [of the ascent], where God was worshiped, behold, Hushai the Archite came to meet him with his coat torn, and earth on his head.'),
  ('49564170-1693-527c-af86-f71b63d45f22', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 33, 33, 'David said to him, "If you pass on with me, then you will be a burden to me;'),
  ('ede9f4be-4047-525c-aedf-9519942d03f5', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 34, 34, 'but if you return to the city, and tell Absalom, ''I will be your servant, O king. As I have been your father''s servant in time past, so will I now be your servant; then will you defeat for me the counsel of Ahithophel.'''),
  ('8f2a9135-eb98-5d36-af4c-3b9c471b89aa', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 35, 35, 'Don''t you have Zadok and Abiathar the priests there with you? Therefore it shall be, that whatever thing you shall hear out of the king''s house, you shall tell it to Zadok and Abiathar the priests.'),
  ('ec7cb4a9-25a5-58d7-a4c3-2083656b4ca7', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 36, 36, 'Behold, they have there with them their two sons, Ahimaaz, Zadok''s son, and Jonathan, Abiathar''s son; and by them you shall send to me everything that you shall hear."'),
  ('6e3a8eaa-1193-5ebd-ac15-842c530a98df', '4c207a9a-15c3-5ffe-a588-155b05719ebc', NULL, 37, 37, 'So Hushai, David''s friend, came into the city; and Absalom came into Jerusalem.'),
  ('4c1c018e-727c-530f-a9df-93b05477bc61', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 1, 1, 'When David was a little past the top [of the ascent], behold, Ziba the servant of Mephibosheth met him, with a couple of donkeys saddled, and on them two hundred loaves of bread, and one hundred clusters of raisins, and one hundred summer fruits, and a bottle of wine.'),
  ('bd8f9915-2b2a-5a3a-ad4e-82d7220654d0', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 2, 2, 'The king said to Ziba, What do you mean by these? Ziba said, The donkeys are for the king''s household to ride on; and the bread and summer fruit for the young men to eat; and the wine, that such as are faint in the wilderness may drink.'),
  ('953c17e8-94a9-55a2-a550-6d4f67f7b355', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 3, 3, 'The king said, "Where is your master''s son?" Ziba said to the king, "Behold, he is staying in Jerusalem; for he said, ''Today the house of Israel will restore me the kingdom of my father.''"'),
  ('047a150b-99da-5621-ada9-1268d07dea3a', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 4, 4, 'Then the king said to Ziba, "Behold, all that pertains to Mephibosheth is yours." Ziba said, "I do obeisance. Let me find favor in your sight, my lord, O king."'),
  ('b7a79467-2ce1-5b33-acf9-441de222b9da', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 5, 5, 'When king David came to Bahurim, behold, a man of the family of the house of Saul came out, whose name was Shimei, the son of Gera. He came out, and cursed still as he came.'),
  ('f6612629-618b-50a2-a0f6-34f2a8e326c6', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 6, 6, 'He cast stones at David, and at all the servants of king David, and all the people and all the mighty men were on his right hand and on his left.'),
  ('ba74ab4a-6b00-52df-a2f2-ff42f2b1067c', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 7, 7, 'Shimei said when he cursed, "Be gone, be gone, you man of blood, and base fellow!'),
  ('3b4cc149-8765-55f2-ae6f-c11d2b8cf09e', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 8, 8, 'Yahweh has returned on you all the blood of the house of Saul, in whose place you have reigned! Yahweh has delivered the kingdom into the hand of Absalom your son! Behold, you are caught by your own mischief, because you are a man of blood!"'),
  ('74529608-0f21-5280-a9bd-1c855f018392', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 9, 9, 'Then Abishai the son of Zeruiah said to the king, "Why should this dead dog curse my lord the king? Please let me go over and take off his head."'),
  ('b7f98b35-0d95-57a7-a176-ab827f06885b', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 10, 10, 'The king said, "What have I to do with you, you sons of Zeruiah? Because he curses, and because Yahweh has said to him, ''Curse David;'' who then shall say, ''Why have you done so?''"'),
  ('355d2779-83a1-56de-a258-f505e36ad73e', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 11, 11, 'David said to Abishai, and to all his servants, "Behold, my son, who came forth from my bowels, seeks my life. How much more this Benjamite, now? Leave him alone, and let him curse; for Yahweh has invited him.'),
  ('70edd1cd-4875-5a25-acc3-f5fc930593ae', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 12, 12, 'It may be that Yahweh will look on the wrong done to me, and that Yahweh will repay me good for the cursing of me today."'),
  ('368a61c8-b869-5172-ab8d-1eb6e80b15dd', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 13, 13, 'So David and his men went by the way; and Shimei went along on the hillside opposite him, and cursed as he went, threw stones at him, and threw dust.'),
  ('c843a3fb-4e02-503d-a724-053a7a48db7d', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 14, 14, 'The king, and all the people who were with him, came weary; and he refreshed himself there.'),
  ('18d206d0-a4c8-5f32-a685-e8046b7cec90', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 15, 15, 'Absalom, and all the people, the men of Israel, came to Jerusalem, and Ahithophel with him.'),
  ('3a72ec8a-5125-5e7f-a921-a0fc0f45c621', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 16, 16, 'It happened, when Hushai the Archite, David''s friend, had come to Absalom, that Hushai said to Absalom, "Long live the king! Long live the king!"'),
  ('4aac4532-7285-51de-afe6-632a55abc7a4', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 17, 17, 'Absalom said to Hushai, "Is this your kindness to your friend? Why didn''t you go with your friend?"'),
  ('24f89886-74c5-54a0-a1c7-18aa562daafd', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 18, 18, 'Hushai said to Absalom, "No; but whoever Yahweh, and this people, and all the men of Israel have chosen, his will I be, and with him I will stay.'),
  ('925f4231-bc23-51e6-a713-3d2c591fa972', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 19, 19, 'Again, whom should I serve? Shouldn''t I serve in the presence of his son? As I have served in your father''s presence, so will I be in your presence."'),
  ('579b2ea5-9e6f-5311-a3f2-0ed0e2d752ad', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 20, 20, 'Then Absalom said to Ahithophel, "Give your counsel what we shall do."'),
  ('122914ce-0398-5e0c-a69a-cb312d522b5b', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 21, 21, 'Ahithophel said to Absalom, "Go in to your father''s concubines, that he has left to keep the house. Then all Israel will hear that you are abhorred by your father. Then the hands of all who are with you will be strong."'),
  ('f2f25c49-7ee2-5765-aa08-8eb917f7449e', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 22, 22, 'So they spread Absalom a tent on the top of the house; and Absalom went in to his father''s concubines in the sight of all Israel.'),
  ('828ec05e-172b-53e3-a5f4-5961084f74e2', '3ad481be-1ab7-5215-a696-76b4b56aecde', NULL, 23, 23, 'The counsel of Ahithophel, which he gave in those days, was as if a man inquired at the oracle of God: so was all the counsel of Ahithophel both with David and with Absalom.'),
  ('8bfcb830-f218-58f0-a62b-93dd8f7a891a', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 1, 1, 'Moreover Ahithophel said to Absalom, "Let me now choose twelve thousand men, and I will arise and pursue after David tonight.'),
  ('13e1f200-e0d9-5058-af6c-a22439ac7029', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 2, 2, 'I will come on him while he is weary and exhausted, and will make him afraid. All the people who are with him shall flee. I will strike the king only;'),
  ('34f9acb7-fcd1-5144-a320-97afb0b30c63', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 3, 3, 'and I will bring back all the people to you. The man whom you seek is as if all returned. All the people shall be in peace."'),
  ('a75d8e5a-57a3-56df-aeab-108bec9770e6', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 4, 4, 'The saying pleased Absalom well, and all the elders of Israel.'),
  ('cacd39f2-0265-5555-a3e7-c9d23f433655', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 5, 5, 'Then Absalom said, "Now call Hushai the Archite also, and let us hear likewise what he says."'),
  ('a94a6f58-36bb-5ba6-a145-a6c7892e185d', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 6, 6, 'When Hushai was come to Absalom, Absalom spoke to him, saying, "Ahithophel has spoken like this. Shall we do what he says? If not, speak up."'),
  ('73255cb2-3531-5a83-a408-c3a20a873b3e', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 7, 7, 'Hushai said to Absalom, "The counsel that Ahithophel has given this time is not good."'),
  ('2487f3eb-8670-5fb0-a7e4-28b95fce4b95', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 8, 8, 'Hushai said moreover, "You know your father and his men, that they are mighty men, and they are fierce in their minds, like a bear robbed of her cubs in the field. Your father is a man of war, and will not lodge with the people.'),
  ('10bca9fd-7e89-51a1-aaaa-5407f166f66a', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 9, 9, 'Behold, he is now hidden in some pit, or in some other place. It will happen, when some of them have fallen at the first, that whoever hears it will say, ''There is a slaughter among the people who follow Absalom!'''),
  ('6949dc67-7473-5336-affc-74a69da90dc8', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 10, 10, 'Even he who is valiant, whose heart is as the heart of a lion, will utterly melt; for all Israel knows that your father is a mighty man, and those who are with him are valiant men.'),
  ('6070f8ec-f66f-55a7-a705-d9543a7e0aa3', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 11, 11, 'But I counsel that all Israel be gathered together to you, from Dan even to Beersheba, as the sand that is by the sea for multitude; and that you go to battle in your own person.'),
  ('7c1ad1f1-b55b-576f-a464-2c18a9be753e', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 12, 12, 'So shall we come on him in some place where he shall be found, and we will light on him as the dew falls on the ground; and of him and of all the men who are with him we will not leave so much as one.'),
  ('83a99250-3dd1-58ca-a9f8-c866a7d0cf1c', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 13, 13, 'Moreover, if he be gone into a city, then shall all Israel bring ropes to that city, and we will draw it into the river, until there isn''t one small stone found there."'),
  ('18bd04d9-c08c-5f3e-ae04-1244ed62fc08', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 14, 14, 'Absalom and all the men of Israel said, "The counsel of Hushai the Archite is better than the counsel of Ahithophel." For Yahweh had ordained to defeat the good counsel of Ahithophel, to the intent that Yahweh might bring evil on Absalom.'),
  ('fce5362d-e57d-5836-ab3f-98054083ece8', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 15, 15, 'Then Hushai said to Zadok and to Abiathar the priests, "Ahithophel counseled Absalom and the elders of Israel that way; and I have counseled this way.'),
  ('0ba349a1-0a6f-5f90-a31c-43a7fe3f36c5', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 16, 16, 'Now therefore send quickly, and tell David, saying, ''Don''t lodge this night at the fords of the wilderness, but by all means pass over; lest the king be swallowed up, and all the people who are with him.''"'),
  ('73b3bb45-8444-5cfd-a839-934582f8a5a1', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 17, 17, 'Now Jonathan and Ahimaaz were staying by En Rogel; and a female servant used to go and tell them; and they went and told king David. For they might not be seen to come into the city.'),
  ('95006284-1ac6-53ca-a83b-abae0f9dbced', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 18, 18, 'But a boy saw them, and told Absalom. Then they both went away quickly, and came to the house of a man in Bahurim, who had a well in his court; and they went down there.'),
  ('dd01f9fe-1b7b-5aa0-aafc-e018e83abd2f', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 19, 19, 'The woman took and spread the covering over the well''s mouth, and spread out bruised grain on it; and nothing was known.'),
  ('156a1a59-fb97-5052-a410-f560d10c23cb', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 20, 20, 'Absalom''s servants came to the woman to the house; and they said, "Where are Ahimaaz and Jonathan?" The woman said to them, "They have gone over the brook of water." When they had sought and could not find them, they returned to Jerusalem.'),
  ('c39f6771-c6c9-51ea-afd8-10b5ce92fe40', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 21, 21, 'It happened, after they had departed, that they came up out of the well, and went and told king David; and they said to David, "Arise and pass quickly over the water; for thus has Ahithophel counseled against you."'),
  ('c775a202-7ec6-5851-adf5-e50d5b824245', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 22, 22, 'Then David arose, and all the people who were with him, and they passed over the Jordan. By the morning light there lacked not one of them who had not gone over the Jordan.'),
  ('021303a0-d804-526d-a7c8-6f3e2c8fd031', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 23, 23, 'When Ahithophel saw that his counsel was not followed, he saddled his donkey, and arose, and went home, to his city, and set his house in order, and hanged himself; and he died, and was buried in the tomb of his father.'),
  ('444db455-cc96-5415-a0ea-ac121e23fa83', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 24, 24, 'Then David came to Mahanaim. Absalom passed over the Jordan, he and all the men of Israel with him.'),
  ('452a07d8-67fa-503f-a85c-ee12c43c9ff6', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 25, 25, 'Absalom set Amasa over the army instead of Joab. Now Amasa was the son of a man, whose name was Ithra the Israelite, who went in to Abigail the daughter of Nahash, sister to Zeruiah, Joab''s mother.'),
  ('3338d0bf-88fa-5728-a17d-29133314b174', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 26, 26, 'Israel and Absalom encamped in the land of Gilead.'),
  ('944b839a-9756-500e-acee-d8d6001596be', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 27, 27, 'It happened, when David was come to Mahanaim, that Shobi the son of Nahash of Rabbah of the children of Ammon, and Machir the son of Ammiel of Lodebar, and Barzillai the Gileadite of Rogelim,'),
  ('abd45e98-d78c-521f-afad-38548135dbc6', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 28, 28, 'brought beds, and basins, and earthen vessels, and wheat, and barley, and meal, and parched [grain], and beans, and lentils, and parched [pulse],'),
  ('1ce5ab6e-bd9e-5ce1-a813-25a3949d1b1a', 'e81f950f-5080-5e60-a9f1-0e1aab69554c', NULL, 29, 29, 'and honey, and butter, and sheep, and cheese of the herd, for David, and for the people who were with him, to eat: for they said, "The people are hungry, and weary, and thirsty, in the wilderness."'),
  ('fb8eda7d-6785-5b7c-a0f0-1c04211746bb', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 1, 1, 'David numbered the people who were with him, and set captains of thousands and captains of hundreds over them.'),
  ('88ee0258-26be-5727-ab91-7670d4c42081', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 2, 2, 'David sent forth the people, a third part under the hand of Joab, and a third part under the hand of Abishai the son of Zeruiah, Joab''s brother, and a third part under the hand of Ittai the Gittite. The king said to the people, "I will surely go forth with you myself also."'),
  ('91fe7607-4168-5eee-ae0a-bd0c69fc5a02', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 3, 3, 'But the people said, "You shall not go forth; for if we flee away, they will not care for us; neither if half of us die, will they care for us. But you are worth ten thousand of us. Therefore now it is better that you are ready to help us out of the city."'),
  ('32a8b9d7-9237-55e7-a4ff-cce36a5254e8', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 4, 4, 'The king said to them, "I will do what seems best to you." The king stood beside the gate, and all the people went out by hundreds and by thousands.'),
  ('4fb7432a-50a8-5067-a854-92d44900c619', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 5, 5, 'The king commanded Joab and Abishai and Ittai, saying, "Deal gently for my sake with the young man, even with Absalom." All the people heard when the king commanded all the captains concerning Absalom.'),
  ('fa2e3491-d1f2-5e7e-a71a-890d4bb99cad', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 6, 6, 'So the people went out into the field against Israel: and the battle was in the forest of Ephraim.'),
  ('0a91209b-2c3e-5bf0-aebd-e91b9075b209', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 7, 7, 'The people of Israel were struck there before the servants of David, and there was a great slaughter there that day of twenty thousand men.'),
  ('bffeb22f-b50d-54c8-add1-11630ccd376b', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 8, 8, 'For the battle was there spread over the surface of all the country; and the forest devoured more people that day than the sword devoured.'),
  ('600e4bf8-3e22-568a-a14b-31f2d7d36fc7', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 9, 9, 'Absalom happened to meet the servants of David. Absalom was riding on his mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the sky and earth; and the mule that was under him went on.'),
  ('b3fb1cfa-6cbb-5abb-a83d-84b064b72b5e', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 10, 10, 'A certain man saw it, and told Joab, and said, "Behold, I saw Absalom hanging in an oak."'),
  ('4d6694a2-6e3d-53e9-a551-4a82e9aaf03f', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 11, 11, 'Joab said to the man who told him, "Behold, you saw it, and why didn''t you strike him there to the ground? I would have given you ten pieces of silver, and a sash."'),
  ('53915109-94b4-5125-a2ea-2bbe6ccbf433', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 12, 12, 'The man said to Joab, "Though I should receive a thousand pieces of silver in my hand, I still wouldn''t put forth my hand against the king''s son; for in our hearing the king commanded you and Abishai and Ittai, saying, ''Beware that none touch the young man Absalom.'''),
  ('29912905-5aba-506a-a910-5ea1f4d95488', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 13, 13, 'Otherwise if I had dealt falsely against his life (and there is no matter hidden from the king), then you yourself would have set yourself against me."'),
  ('328885c2-6b85-5b8e-a945-5c33a8659791', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 14, 14, 'Then Joab said, "I''m not going to wait like this with you." He took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak.'),
  ('c0ab35f8-e590-59d8-ae29-7282b8650cb1', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 15, 15, 'Ten young men who bore Joab''s armor surrounded and struck Absalom, and killed him.'),
  ('70dd93cf-17b0-5b7d-abdb-6d9e9814facc', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 16, 16, 'Joab blew the trumpet, and the people returned from pursuing after Israel; for Joab held back the people.'),
  ('23cf81cb-f7bd-58a1-ae7c-a0c7a66214e1', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 17, 17, 'They took Absalom, and cast him into the great pit in the forest, and raised over him a very great heap of stones. Then all Israel fled everyone to his tent.'),
  ('68bcaf3f-0bb5-5065-a21a-30ed6c123317', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 18, 18, 'Now Absalom in his lifetime had taken and reared up for himself the pillar, which is in the king''s dale; for he said, "I have no son to keep my name in memory." He called the pillar after his own name; and it is called Absalom''s monument, to this day.'),
  ('8fff4155-f86b-55b6-a458-78efa7fbd430', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 19, 19, 'Then Ahimaaz the son of Zadok said, "Let me now run, and bear the king news, how that Yahweh has avenged him of his enemies."'),
  ('6d9dc4b3-7b25-5ae4-ac9c-c2b22e219528', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 20, 20, 'Joab said to him, "You shall not be the bearer of news this day, but you shall bear news another day. But today you shall bear no news, because the king''s son is dead."'),
  ('1d9f075b-05b6-53e5-a75c-285498df24a9', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 21, 21, 'Then Joab said to the Cushite, "Go, tell the king what you have seen!" The Cushite bowed himself to Joab, and ran.'),
  ('e904f8b2-d09b-5aae-a99f-c53000fc80b0', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 22, 22, 'Then Ahimaaz the son of Zadok said yet again to Joab, "But come what may, please let me also run after the Cushite." Joab said, "Why do you want to run, my son, since that you will have no reward for the news?"'),
  ('7315531a-1010-582e-a6e7-a7bb3eb327e4', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 23, 23, '"But come what may," he said, "I will run." He said to him, "Run!" Then Ahimaaz ran by the way of the Plain, and outran the Cushite.'),
  ('68a10f13-050e-5470-a76a-8d89d58c2820', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 24, 24, 'Now David was sitting between the two gates: and the watchman went up to the roof of the gate to the wall, and lifted up his eyes, and looked, and, behold, a man running alone.'),
  ('24c3f083-8319-5486-a445-087fcaaa8166', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 25, 25, 'The watchman cried, and told the king. The king said, "If he is alone, there is news in his mouth." He came closer and closer.'),
  ('ea811006-959a-5694-a03c-5643667ef09e', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 26, 26, 'The watchman saw another man running; and the watchman called to the porter, and said, "Behold, a man running alone!" The king said, "He also brings news."'),
  ('f00691fc-2e28-57ee-a8a2-c6a2f4c0ba5f', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 27, 27, 'The watchman said, "I think the running of the first one is like the running of Ahimaaz the son of Zadok." The king said, "He is a good man, and comes with good news."'),
  ('bf542ed4-6f72-54a7-acb2-4494d3fa0fdf', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 28, 28, 'Ahimaaz called, and said to the king, "All is well." He bowed himself before the king with his face to the earth, and said, "Blessed is Yahweh your God, who has delivered up the men who lifted up their hand against my lord the king!"'),
  ('f17c637e-34ac-567b-aa06-1a76ce709565', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 29, 29, 'The king said, "Is it well with the young man Absalom?" Ahimaaz answered, "When Joab sent the king''s servant, even me your servant, I saw a great tumult, but I don''t know what it was."'),
  ('e2b8127e-1fe9-536f-a45f-a2d988ec44b3', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 30, 30, 'The king said, "Turn aside, and stand here." He turned aside, and stood still.'),
  ('a975727b-1496-5a4b-aeda-cb61f5e6948e', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 31, 31, 'Behold, the Cushite came. The Cushite said, "News for my lord the king; for Yahweh has avenged you this day of all those who rose up against you."'),
  ('38a2c6ec-0d24-5538-aa6b-97776643ca73', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 32, 32, 'The king said to the Cushite, "Is it well with the young man Absalom?" The Cushite answered, "May the enemies of my lord the king, and all who rise up against you to do you harm, be as that young man is."'),
  ('3e5c3537-1ec0-53c3-abd1-9a60cbb282c1', '2b77efc6-9d5f-5621-a02a-7d2ceebc5ef2', NULL, 33, 33, 'The king was much moved, and went up to the room over the gate, and wept. As he went, he said, "My son Absalom! My son, my son Absalom! I wish I had died for you, Absalom, my son, my son!"'),
  ('0f925f93-2b44-5505-a37f-1c3f5c260e18', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 1, 1, 'It was told Joab, "Behold, the king weeps and mourns for Absalom."'),
  ('000458c2-5b90-5d4b-a987-eb75fc6d197b', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 2, 2, 'The victory that day was turned into mourning to all the people; for the people heard it said that day, "The king grieves for his son."'),
  ('192dc17e-a299-5ac2-ad91-fa7839dccc0e', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 3, 3, 'The people snuck into the city that day, as people who are ashamed steal away when they flee in battle.'),
  ('9248f8b0-cdb4-5083-a6af-a721b6ac786e', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 4, 4, 'The king covered his face, and the king cried with a loud voice, "My son Absalom, Absalom, my son, my son!"'),
  ('69782de5-1e45-5890-af0d-96155e6274d7', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 5, 5, 'Joab came into the house to the king, and said, "You have shamed this day the faces of all your servants, who this day have saved your life, and the lives of your sons and of your daughters, and the lives of your wives, and the lives of your concubines;'),
  ('4e4bee32-c9f1-582b-ae73-086fac7b4787', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 6, 6, 'in that you love those who hate you, and hate those who love you. For you have declared this day, that princes and servants are nothing to you. For today I perceive that if Absalom had lived, and all we had died this day, then it would have pleased you well.'),
  ('a77be5cc-2efd-5a63-a796-81d7857d0b15', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 7, 7, 'Now therefore arise, go out, and speak to comfort your servants; for I swear by Yahweh, if you don''t go out, not a man will stay with you this night. That would be worse to you than all the evil that has happened to you from your youth until now."'),
  ('3c1dab0c-6377-5b99-ab02-df77c5cbd17b', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 8, 8, 'Then the king arose, and sat in the gate. They told to all the people, saying, "Behold, the king is sitting in the gate." All the people came before the king. Now Israel had fled every man to his tent.'),
  ('5ffec675-c8df-5db1-aa55-bc4fa78e1fb5', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 9, 9, 'All the people were at strife throughout all the tribes of Israel, saying, "The king delivered us out of the hand of our enemies, and he saved us out of the hand of the Philistines; and now he has fled out of the land from Absalom.'),
  ('c9e97e57-6f15-5bbc-ae44-3723caa0065a', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 10, 10, 'Absalom, whom we anointed over us, is dead in battle. Now therefore why don''t you speak a word of bringing the king back?"'),
  ('47bd3c7f-7631-5ef4-a585-334996424350', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 11, 11, 'King David sent to Zadok and to Abiathar the priests, saying, "Speak to the elders of Judah, saying, ''Why are you the last to bring the king back to his house? Since the speech of all Israel has come to the king, to return him to his house.'),
  ('c1e8636d-79b5-5236-a4f7-4d5c37e1c5f2', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 12, 12, 'You are my brothers, you are my bone and my flesh. Why then are you the last to bring back the king?'''),
  ('a5878974-c69b-5081-a1d5-de72c6a34c5c', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 13, 13, 'Say to Amasa, ''Aren''t you my bone and my flesh? God do so to me, and more also, if you aren''t captain of the army before me continually in the room of Joab.''"'),
  ('75be613d-69b2-58da-abfc-1e6ba657458c', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 14, 14, 'He bowed the heart of all the men of Judah, even as [the heart of] one man; so that they sent to the king, saying, "Return, you and all your servants."'),
  ('c97287cd-756d-5d83-ae1a-2f9bbe212d7f', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 15, 15, 'So the king returned, and came to the Jordan. Judah came to Gilgal, to go to meet the king, to bring the king over the Jordan.'),
  ('ee2eb4f5-16d4-5452-adf8-e655e427e00f', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 16, 16, 'Shimei the son of Gera, the Benjamite, who was of Bahurim, hurried and came down with the men of Judah to meet king David.'),
  ('bcbcd930-dc14-501e-a691-e11a6debf5a3', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 17, 17, 'There were a thousand men of Benjamin with him, and Ziba the servant of the house of Saul, and his fifteen sons and his twenty servants with him; and they went through the Jordan in the presence of the king.'),
  ('ee0ad20b-d496-54bc-ad14-685ef1b7a307', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 18, 18, 'A ferry boat went to bring over the king''s household, and to do what he thought good. Shimei the son of Gera fell down before the king, when he was come over the Jordan.'),
  ('0c392b04-d442-5b6f-a3f2-d41281fe1794', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 19, 19, 'He said to the king, "Don''t let my lord impute iniquity to me, neither do you remember that which your servant did perversely the day that my lord the king went out of Jerusalem, that the king should take it to his heart.'),
  ('adcf8e50-b73e-52d0-a8c9-b7c09b8bc74c', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 20, 20, 'For your servant knows that I have sinned. Therefore, behold, I have come this day the first of all the house of Joseph to go down to meet my lord the king."'),
  ('da7e7a23-61c3-5335-a70b-0d12ca36bb95', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 21, 21, 'But Abishai the son of Zeruiah answered, "Shall Shimei not be put to death for this, because he cursed Yahweh''s anointed?"'),
  ('7c761938-2c4f-5694-ad1a-eebc602f20cd', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 22, 22, 'David said, "What have I to do with you, you sons of Zeruiah, that you should this day be adversaries to me? Shall there any man be put to death this day in Israel? For don''t I know that I am this day king over Israel?"'),
  ('528b87e4-34e0-55f1-a35c-1948ed230720', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 23, 23, 'The king said to Shimei, "You shall not die." The king swore to him.'),
  ('734cb35d-2446-5e4a-a5b5-4af2ad5619a7', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 24, 24, 'Mephibosheth the son of Saul came down to meet the king; and he had neither groomed his feet, nor trimmed his beard, nor washed his clothes, from the day the king departed until the day he came home in peace.'),
  ('4bf9933e-dea3-5eb6-ac39-91279fe3345f', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 25, 25, 'It happened, when he had come to Jerusalem to meet the king, that the king said to him, "Why didn''t you go with me, Mephibosheth?"'),
  ('182117b4-ee85-5d80-aa95-cad89c4395d5', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 26, 26, 'He answered, "My lord, O king, my servant deceived me. For your servant said, I will saddle me a donkey, that I may ride thereon, and go with the king; because your servant is lame.'),
  ('058d0aca-5ff6-5fdb-a5db-7f15159aa375', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 27, 27, 'He has slandered your servant to my lord the king; but my lord the king is as an angel of God. Do therefore what is good in your eyes.'),
  ('2643cd03-8416-5093-ac3e-04762770775c', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 28, 28, 'For all my father''s house were but dead men before my lord the king; yet you set your servant among those who ate at your own table. What right therefore have I yet that I should cry any more to the king?"'),
  ('1af31f8d-f817-5a01-a914-71d833b72788', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 29, 29, 'The king said to him, "Why do you speak any more of your matters? I say, you and Ziba divide the land."'),
  ('7910d7df-961d-52ed-aa43-d6732dbfbcd5', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 30, 30, 'Mephibosheth said to the king, "Yes, let him take all, because my lord the king has come in peace to his own house."'),
  ('57e0844f-13d6-595e-ade9-d61f5b5e989e', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 31, 31, 'Barzillai the Gileadite came down from Rogelim; and he went over the Jordan with the king, to conduct him over the Jordan.'),
  ('6bb9c3dc-f9d9-5785-a928-ff806e26c72c', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 32, 32, 'Now Barzillai was a very aged man, even eighty years old: and he had provided the king with sustenance while he lay at Mahanaim; for he was a very great man.'),
  ('3801732e-9061-5126-a64f-19a4a5647981', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 33, 33, 'The king said to Barzillai, "Come over with me, and I will sustain you with me in Jerusalem."'),
  ('8821baef-b56f-58bc-a254-aa43e9573405', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 34, 34, 'Barzillai said to the king, "How many are the days of the years of my life, that I should go up with the king to Jerusalem?'),
  ('0c98422e-3a19-59ab-a96a-7346781d332e', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 35, 35, 'I am this day eighty years old. Can I discern between good and bad? Can your servant taste what I eat or what I drink? Can I hear any more the voice of singing men and singing women? Why then should your servant be yet a burden to my lord the king?'),
  ('d50008d4-22d3-5a49-ab05-4a72983adb1f', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 36, 36, 'Your servant would but just go over the Jordan with the king. Why should the king repay me with such a reward?'),
  ('c3cf0afb-0e51-5ed3-a9f1-de29f21c56aa', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 37, 37, 'Please let your servant turn back again, that I may die in my own city, by the grave of my father and my mother. But behold, your servant Chimham; let him go over with my lord the king; and do to him what shall seem good to you."'),
  ('e043f52e-3c1c-5d57-a5df-58d718ed8932', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 38, 38, 'The king answered, "Chimham shall go over with me, and I will do to him that which shall seem good to you. Whatever you require of me, that I will do for you."'),
  ('7d274952-3451-59e6-a884-d46fd2360086', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 39, 39, 'All the people went over the Jordan, and the king went over. Then the king kissed Barzillai, and blessed him; and he returned to his own place.'),
  ('02d7960c-22af-58cc-acc9-26c94ecd2eb7', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 40, 40, 'So the king went over to Gilgal, and Chimham went over with him. All the people of Judah brought the king over, and also half the people of Israel.'),
  ('5cc7453a-25d6-5a10-a323-9b6fdc135187', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 41, 41, 'Behold, all the men of Israel came to the king, and said to the king, "Why have our brothers the men of Judah stolen you away, and brought the king, and his household, over the Jordan, and all David''s men with him?"'),
  ('107469df-23f3-59a4-a7a6-bb9ef09d5e43', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 42, 42, 'All the men of Judah answered the men of Israel, "Because the king is a close relative to us. Why then are you angry about this matter? Have we eaten at all at the king''s cost? Or has he given us any gift?"'),
  ('19ae5651-6547-5a93-a61e-a0b17b0b7cbf', 'a777545c-8ee0-5184-a212-b48968f070af', NULL, 43, 43, 'The men of Israel answered the men of Judah, and said, "We have ten parts in the king, and we have also more claim to David than you. Why then did you despise us, that our advice should not be first had in bringing back our king?" The words of the men of Judah were fiercer than the words of the men of Israel.'),
  ('b45a3f29-caf4-59d9-af43-4a87e88c5e04', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 1, 1, 'There happened to be there a base fellow, whose name was Sheba, the son of Bichri, a Benjamite: and he blew the trumpet, and said, "We have no portion in David, neither have we inheritance in the son of Jesse. Every man to his tents, Israel!"'),
  ('da0ca4e0-f5ba-5679-a0f4-39eee9c2085d', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 2, 2, 'So all the men of Israel went up from following David, and followed Sheba the son of Bichri; but the men of Judah joined with their king, from the Jordan even to Jerusalem.'),
  ('5c80fc32-b5d7-5d27-ad35-252ff03c721b', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 3, 3, 'David came to his house at Jerusalem; and the king took the ten women his concubines, whom he had left to keep the house, and put them in custody, and provided them with sustenance, but didn''t go in to them. So they were shut up to the day of their death, living in widowhood.'),
  ('5f612e76-83e5-509d-aee4-697a750a5246', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 4, 4, 'Then the king said to Amasa, "Call me the men of Judah together within three days, and be here present."'),
  ('8337135d-e4a4-56e9-aa0a-a50363e1923f', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 5, 5, 'So Amasa went to call [the men of] Judah together; but he stayed longer than the set time which he had appointed him.'),
  ('9b277bb5-2074-52c2-a3e9-b4a4846fba8a', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 6, 6, 'David said to Abishai, "Now Sheba the son of Bichri will do us more harm than did Absalom. Take your lord''s servants, and pursue after him, lest he get himself fortified cities, and escape out of our sight."'),
  ('244ae4e3-29ed-5b14-aa1f-255fde33cff6', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 7, 7, 'There went out after him Joab''s men, and the Cherethites and the Pelethites, and all the mighty men; and they went out of Jerusalem, to pursue after Sheba the son of Bichri.'),
  ('15d1f88d-33da-51d7-a7f8-8096e62d6ed0', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 8, 8, 'When they were at the great stone which is in Gibeon, Amasa came to meet them. Joab was clothed in his apparel of war that he had put on, and on it was a sash with a sword fastened on his waist in its sheath; and as he went forth it fell out.'),
  ('31ab000d-7a01-52fb-a75e-df8b2d1f8a21', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 9, 9, 'Joab said to Amasa, "Is it well with you, my brother?" Joab took Amasa by the beard with his right hand to kiss him.'),
  ('13633122-8a7d-5cc6-a03a-570ed83cd09b', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 10, 10, 'But Amasa took no heed to the sword that was in Joab''s hand. So he struck him with it in the body, and shed out his bowels to the ground, and didn''t strike him again; and he died. Joab and Abishai his brother pursued after Sheba the son of Bichri.'),
  ('e5a5b80d-cd9a-50d5-a531-99122ae124f4', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 11, 11, 'There stood by him one of Joab''s young men, and said, "He who favors Joab, and he who is for David, let him follow Joab!"'),
  ('c72cc5fe-c716-54bb-a7f3-dad337d68742', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 12, 12, 'Amasa lay wallowing in his blood in the midst of the highway. When the man saw that all the people stood still, he carried Amasa out of the highway into the field, and cast a garment over him, when he saw that everyone who came by him stood still.'),
  ('969d8fed-94a9-5dba-a10e-69a68d20efd6', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 13, 13, 'When he was removed out of the highway, all the people went on after Joab, to pursue after Sheba the son of Bichri.'),
  ('5406104e-9211-5e28-a6cb-4a633fdb9504', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 14, 14, 'He went through all the tribes of Israel to Abel, and to Beth Maacah, and all the Berites: and they were gathered together, and went also after him.'),
  ('0a496640-c682-510a-a3c2-38294aec497b', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 15, 15, 'They came and besieged him in Abel of Beth Maacah, and they cast up a mound against the city, and it stood against the rampart; and all the people who were with Joab battered the wall, to throw it down.'),
  ('5fc2bc60-61ec-5380-a76b-88ccbbe7380d', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 16, 16, 'Then a wise woman cried out of the city, "Hear, hear! Please say to Joab, ''Come near here, that I may speak with you.''"'),
  ('e9912495-c418-5645-a0cb-88ab0ebc6c1c', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 17, 17, 'He came near to her; and the woman said, "Are you Joab?" He answered, "I am." Then she said to him, "Hear the words of your handmaid." He answered, "I do hear."'),
  ('8ce7bb71-52dc-5151-a56e-1697af327d40', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 18, 18, 'Then she spoke, saying, "They were used to say in old times, ''They shall surely ask counsel at Abel;'' and so they settled it.'),
  ('30e8bc5f-f91b-5be7-ac78-a690ff4b594c', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 19, 19, 'I am among those who are peaceable and faithful in Israel. You seek to destroy a city and a mother in Israel. Why will you swallow up the inheritance of Yahweh?"'),
  ('830a2771-bcf6-5c00-ace1-e2638ab41198', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 20, 20, 'Joab answered, "Far be it, far be it from me, that I should swallow up or destroy.'),
  ('c9dc5e56-2ce3-5a1e-a7ae-5e0d8f58d601', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 21, 21, 'The matter is not so. But a man of the hill country of Ephraim, Sheba the son of Bichri by name, has lifted up his hand against the king, even against David. Deliver him only, and I will depart from the city." The woman said to Joab, "Behold, his head shall be thrown to you over the wall."'),
  ('2da2395f-b5c8-526b-ace8-7f837ac815df', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 22, 22, 'Then the woman went to all the people in her wisdom. They cut off the head of Sheba the son of Bichri, and threw it out to Joab. He blew the trumpet, and they were dispersed from the city, every man to his tent. Joab returned to Jerusalem to the king.'),
  ('5636d539-a359-590b-a7ed-6496c28e8934', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 23, 23, 'Now Joab was over all the army of Israel; and Benaiah the son of Jehoiada was over the Cherethites and over the Pelethites;'),
  ('17ffb8d1-8e77-51c9-a8b4-f41a4de1e0ab', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 24, 24, 'and Adoram was over the men subject to forced labor; and Jehoshaphat the son of Ahilud was the recorder;'),
  ('87b00b21-1c20-5cf4-a7d8-f4e920eb642f', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 25, 25, 'and Sheva was scribe; and Zadok and Abiathar were priests;'),
  ('e0a61ae9-a1f5-5717-aa4c-337bf6198554', '48a3bc91-50aa-591d-af03-4683ae0cb526', NULL, 26, 26, 'and also Ira the Jairite was chief minister to David.'),
  ('a3b8f9bd-0835-51fb-a70e-4a4bd3c0de27', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 1, 1, 'There was a famine in the days of David three years, year after year; and David sought the face of Yahweh. Yahweh said, "It is for Saul, and for his bloody house, because he put to death the Gibeonites."'),
  ('7ca991d2-f330-59a1-a346-145d9035c04b', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 2, 2, 'The king called the Gibeonites, and said to them (now the Gibeonites were not of the children of Israel, but of the remnant of the Amorites; and the children of Israel had sworn to them: and Saul sought to kill them in his zeal for the children of Israel and Judah);'),
  ('1899b7cd-d326-5da1-ae20-b9fa0e9beb08', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 3, 3, 'and David said to the Gibeonites, "What shall I do for you? And with what shall I make atonement, that you may bless the inheritance of Yahweh?"'),
  ('0eeaef4e-8603-5fa7-a0b7-d92eff63bd22', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 4, 4, 'The Gibeonites said to him, "It is no matter of silver or gold between us and Saul, or his house; neither is it for us to put any man to death in Israel." He said, "Whatever you say, that will I do for you."'),
  ('e561e84a-e4c7-5e64-a3ba-9b186d3c80b9', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 5, 5, 'They said to the king, "The man who consumed us, and who devised against us, that we should be destroyed from remaining in any of the borders of Israel,'),
  ('302f4294-b082-5c12-a422-e0281b5b3ed1', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 6, 6, 'let seven men of his sons be delivered to us, and we will hang them up to Yahweh in Gibeah of Saul, the chosen of Yahweh." The king said, "I will give them."'),
  ('a09ef2a7-019f-539c-a605-96c8f1c9c108', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 7, 7, 'But the king spared Mephibosheth, the son of Jonathan the son of Saul, because of Yahweh''s oath that was between them, between David and Jonathan the son of Saul.'),
  ('f616bb58-f8a6-501f-a528-fd89743543d5', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 8, 8, 'But the king took the two sons of Rizpah the daughter of Aiah, whom she bore to Saul, Armoni and Mephibosheth; and the five sons of Michal the daughter of Saul, whom she bore to Adriel the son of Barzillai the Meholathite.'),
  ('18c4c9a7-cba4-50a3-a3e3-2d25db5a7ef0', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 9, 9, 'He delivered them into the hands of the Gibeonites, and they hanged them in the mountain before Yahweh, and all seven of them fell together. They were put to death in the days of harvest, in the first days, at the beginning of barley harvest.'),
  ('99213439-7f28-5af0-a40b-b29e53b3611b', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 10, 10, 'Rizpah the daughter of Aiah took sackcloth, and spread it for her on the rock, from the beginning of harvest until water was poured on them from the sky. She allowed neither the birds of the sky to rest on them by day, nor the animals of the field by night.'),
  ('5e89f87a-5d11-57e2-acf9-df75cb00d19e', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 11, 11, 'It was told David what Rizpah the daughter of Aiah, the concubine of Saul, had done.'),
  ('485e84b1-c2f0-58d4-a955-a346498fa9c9', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 12, 12, 'David went and took the bones of Saul and the bones of Jonathan his son from the men of Jabesh Gilead, who had stolen them from the street of Beth Shan, where the Philistines had hanged them, in the day that the Philistines killed Saul in Gilboa;'),
  ('ea8ac71a-c049-5bc9-a455-4f720b05a215', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 13, 13, 'and he brought up from there the bones of Saul and the bones of Jonathan his son: and they gathered the bones of those who were hanged.'),
  ('078977b0-8a7a-5477-a8a2-bd3286ef0f02', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 14, 14, 'They buried the bones of Saul and Jonathan his son in the country of Benjamin in Zela, in the tomb of Kish his father: and they performed all that the king commanded. After that God was entreated for the land.'),
  ('19ff7eb2-4ed2-53e4-add8-bef2ef077fcd', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 15, 15, 'The Philistines had war again with Israel; and David went down, and his servants with him, and fought against the Philistines. David grew faint;'),
  ('7a141f02-3ac2-53d1-a581-5a9171fea6de', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 16, 16, 'and Ishbibenob, who was of the sons of the giant, the weight of whose spear was three hundred [shekels] of brass in weight, he being armed with a new [sword], thought to have slain David.'),
  ('14cb365c-3889-577f-a21a-ec4953eb4aa4', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 17, 17, 'But Abishai the son of Zeruiah helped him, and struck the Philistine, and killed him. Then the men of David swore to him, saying, "You shall go no more out with us to battle, that you don''t quench the lamp of Israel."'),
  ('d45ab1b9-20c0-5f0c-a437-c5c05e8efa45', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 18, 18, 'It came to pass after this, that there was again war with the Philistines at Gob: then Sibbecai the Hushathite killed Saph, who was of the sons of the giant.'),
  ('606febc8-cfd5-5a35-a348-db16ab878fd2', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 19, 19, 'There was again war with the Philistines at Gob; and Elhanan the son of Jaareoregim the Bethlehemite killed Goliath the Gittite''s brother, the staff of whose spear was like a weaver''s beam.'),
  ('cfe834f9-54fb-5cc1-aedc-306aa011b61f', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 20, 20, 'There was again war at Gath, where there was a man of great stature, who had on every hand six fingers, and on every foot six toes, four and twenty in number; and he also was born to the giant.'),
  ('0580f261-c2b5-5d06-a772-e72d90dbbdd8', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 21, 21, 'When he defied Israel, Jonathan the son of Shimei, David''s brother, killed him.'),
  ('8ff9ff99-8383-5644-ab66-b1d743f291e7', '0102a9f4-d182-5f52-a02e-708f8ad829a0', NULL, 22, 22, 'These four were born to the giant in Gath; and they fell by the hand of David, and by the hand of his servants.'),
  ('8536bd66-afe6-5e92-a91a-007602518d07', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 1, 1, 'David spoke to Yahweh the words of this song in the day that Yahweh delivered him out of the hand of all his enemies, and out of the hand of Saul:'),
  ('84bdbfbf-1cd8-5424-a244-b0ce0ab8364d', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 2, 2, 'and he said, "Yahweh is my rock, my fortress, and my deliverer, even mine;'),
  ('752427e2-2619-5c0e-aac1-9c49f8aaaa6a', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 3, 3, 'God, my rock, in him I will take refuge; my shield, and the horn of my salvation, my high tower, and my refuge. My savior, you save me from violence.'),
  ('12ca511f-01bd-58e0-a9d8-9b33d20d0c30', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 4, 4, 'I will call on Yahweh, who is worthy to be praised: So shall I be saved from my enemies.'),
  ('b3a4c3fe-8aa8-5d5e-adcb-5171f774afaa', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 5, 5, 'For the waves of death surrounded me. The floods of ungodliness made me afraid.'),
  ('9205e068-5805-5437-afb3-a05e65f4bfcd', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 6, 6, 'The cords of Sheol were around me. The snares of death caught me.'),
  ('5ec7f793-8efe-5def-a304-23d2fc865730', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 7, 7, 'In my distress I called on Yahweh. Yes, I called to my God. He heard my voice out of his temple. My cry [came] into his ears.'),
  ('46499cd4-51c9-5ea9-a643-7198da2ae772', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 8, 8, 'Then the earth shook and trembled. The foundations of heaven quaked and were shaken, because he was angry.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('60a277e1-3f74-50c6-a98b-1cf50b83cdcc', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 9, 9, 'Smoke went up out of his nostrils. Fire out of his mouth devoured. Coals were kindled by it.'),
  ('e48d5214-b186-5d48-a743-bebb6eeed9e3', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 10, 10, 'He bowed the heavens also, and came down. Thick darkness was under his feet.'),
  ('441befff-1221-5bcf-ae1f-bacdb02a7872', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 11, 11, 'He rode on a cherub, and flew. Yes, he was seen on the wings of the wind.'),
  ('781528ee-b866-5588-a698-fb5279ce4a5c', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 12, 12, 'He made darkness pavilions around himself: gathering of waters, and thick clouds of the skies.'),
  ('118b8cc2-2953-57b7-a439-b9bbe9ea8403', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 13, 13, 'At the brightness before him, coals of fire were kindled.'),
  ('f32b957f-6413-5737-ab84-d61722b06954', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 14, 14, 'Yahweh thundered from heaven. The Most High uttered his voice.'),
  ('56f5ac74-ef89-5273-af96-bf159901a723', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 15, 15, 'He sent out arrows, and scattered them; lightning, and confused them.'),
  ('c9c1bb48-2e93-59c1-a6fd-a99781559110', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 16, 16, 'Then the channels of the sea appeared. The foundations of the world were laid bare by the rebuke of Yahweh, At the blast of the breath of his nostrils.'),
  ('3bde9b2d-1e0e-5eba-ada8-1025e3765482', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 17, 17, 'He sent from on high and he took me. He drew me out of many waters.'),
  ('28996161-23d9-5539-aa02-46dd713c58fe', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 18, 18, 'He delivered me from my strong enemy, from those who hated me, for they were too mighty for me.'),
  ('5732d8c0-5b05-50bd-a9cf-e7c9d45edfa9', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 19, 19, 'They came on me in the day of my calamity, but Yahweh was my support.'),
  ('83cccdd4-7c77-582a-aac5-e914aa288f9e', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 20, 20, 'He also brought me out into a large place. He delivered me, because he delighted in me.'),
  ('214d8c3c-96e7-59d4-ab45-befa21203524', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 21, 21, 'Yahweh rewarded me according to my righteousness. He rewarded me according to the cleanness of my hands.'),
  ('be4f39d0-e1f8-5750-a711-516394845175', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 22, 22, 'For I have kept the ways of Yahweh, and have not wickedly departed from my God.'),
  ('48ff4bef-6187-5620-aae3-81669865dda4', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 23, 23, 'For all his ordinances were before me. As for his statutes, I did not depart from them.'),
  ('3ee172a7-7db1-5eb0-a907-3d4a6e63ae81', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 24, 24, 'I was also perfect toward him. I kept myself from my iniquity.'),
  ('cc4afb92-2c06-5321-a983-2242902cdfb3', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 25, 25, 'Therefore Yahweh has rewarded me according to my righteousness, According to my cleanness in his eyesight.'),
  ('31761860-920b-5029-a00d-8116b0732c00', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 26, 26, 'With the merciful you will show yourself merciful. With the perfect man you will show yourself perfect.'),
  ('28a37053-6ac3-5c7e-ab97-606a9e893f47', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 27, 27, 'With the pure you will show yourself pure. With the crooked you will show yourself shrewd.'),
  ('befcc91a-002c-5205-a9be-6bbe1a69e84a', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 28, 28, 'You will save the afflicted people, But your eyes are on the haughty, that you may bring them down.'),
  ('959a25e7-b8b3-5e7d-aee4-34b424a13843', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 29, 29, 'For you are my lamp, Yahweh. Yahweh will light up my darkness.'),
  ('cae0fb40-ed68-527d-af18-eeb7265684d7', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 30, 30, 'For by you, I run against a troop. By my God, I leap over a wall.'),
  ('c17c0f55-3ea9-5273-acb5-10429a80d37b', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 31, 31, 'As for God, his way is perfect. The word of Yahweh is tested. He is a shield to all those who take refuge in him.'),
  ('e23ec7db-7583-56e3-ada1-aa7496594750', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 32, 32, 'For who is God, besides Yahweh? Who is a rock, besides our God?'),
  ('138b6274-74cf-5f16-a7c8-30a7139ae08b', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 33, 33, 'God is my strong fortress. He makes my way perfect.'),
  ('fdd608e6-ae3d-5ce9-a53a-05045ecff033', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 34, 34, 'He makes his feet like hinds'' [feet], and sets me on my high places.'),
  ('d1fb68d9-8992-5f1c-a431-7de2e25badb6', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 35, 35, 'He teaches my hands to war, so that my arms bend a bow of brass.'),
  ('b4c9dabd-d779-5bfd-a0b9-70dfd57b2e07', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 36, 36, 'You have also given me the shield of your salvation. Your gentleness has made me great.'),
  ('692e17e3-3ed4-549f-a591-9f304c74a794', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 37, 37, 'You have enlarged my steps under me. My feet have not slipped.'),
  ('a8330d94-8bda-5dea-a9b4-e0d898fdeff3', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 38, 38, 'I have pursued my enemies and destroyed them. I didn''t turn again until they were consumed.'),
  ('ff3a0a7e-9fef-5761-a9a3-8ecb6dba736e', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 39, 39, 'I have consumed them, and struck them through, so that they can''t arise. Yes, they have fallen under my feet.'),
  ('992d1af7-af1c-534f-aa92-b6c16d78f155', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 40, 40, 'For you have armed me with strength for the battle. You have subdued under me those who rose up against me.'),
  ('bfe7f481-6187-5884-a19e-38147cf80a5d', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 41, 41, 'You have also made my enemies turn their backs to me, that I might cut off those who hate me.'),
  ('9e240b2d-7859-5264-a9ce-9d12ad2d729c', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 42, 42, 'They looked, but there was none to save; even to Yahweh, but he didn''t answer them.'),
  ('a5cac1d4-676b-5ac8-a161-7ab443a47161', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 43, 43, 'Then I beat them as small as the dust of the earth. I crushed them as the mire of the streets, and spread them abroad.'),
  ('061fc5ed-3ffb-5d9d-a870-418fa7c100b8', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 44, 44, 'You also have delivered me from the strivings of my people. You have kept me to be the head of the nations. A people whom I have not known will serve me.'),
  ('f2f90421-8747-559d-ab29-6e38cdc345fd', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 45, 45, 'The foreigners will submit themselves to me. As soon as they hear of me, they will obey me.'),
  ('7ff11f72-2320-505a-a5fa-1748851342ad', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 46, 46, 'The foreigners will fade away, and will come trembling out of their close places.'),
  ('b00d8ead-30fb-548e-a7e8-fdab1275cfe7', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 47, 47, 'Yahweh lives! Blessed be my rock! Exalted be God, the rock of my salvation,'),
  ('4681ab41-1ed0-5719-af59-5a902ea767b2', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 48, 48, 'even the God who executes vengeance for me, who brings down peoples under me,'),
  ('b00b1b41-306d-5947-a889-6db116edc9b1', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 49, 49, 'who brings me away from my enemies. Yes, you lift me up above those who rise up against me. You deliver me from the violent man.'),
  ('98c6d732-ff77-5f1b-add0-896866a0c064', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 50, 50, 'Therefore I will give thanks to you, Yahweh, among the nations. Will sing praises to your name.'),
  ('38a1877c-c837-5e4e-a4d9-82f53f7769c5', 'e9b2fc44-1d36-54e0-a8ab-39427e4ce3c2', NULL, 51, 51, 'He gives great deliverance to his king, and shows loving kindness to his anointed, to David and to his seed, forevermore."'),
  ('f15eaae9-11f7-59d2-a713-0768546dd5f0', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 1, 1, 'Now these are the last words of David. David the son of Jesse says, the man who was raised on high says, the anointed of the God of Jacob, the sweet psalmist of Israel:'),
  ('d79c16ca-cbf9-51a4-a6a8-02c5571c95a5', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 2, 2, '"The Spirit of Yahweh spoke by me. His word was on my tongue.'),
  ('55ccf773-458f-59d8-ada4-394b6e8cdc2f', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 3, 3, 'The God of Israel said, the Rock of Israel spoke to me, ''One who rules over men righteously, who rules in the fear of God,'),
  ('38a621f0-3de0-5da8-aa54-f872ed4401c2', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 4, 4, 'shall be as the light of the morning, when the sun rises, a morning without clouds, when the tender grass springs out of the earth, through clear shining after rain.'''),
  ('0b8fc380-efd7-546b-ace2-401cc86b937e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 5, 5, 'Most certainly my house is not so with God, yet he has made with me an everlasting covenant, ordered in all things, and sure, for it is all my salvation, and all [my] desire, although he doesn''t make it grow.'),
  ('44df8b96-bbc4-573b-a556-dc075dabcc5d', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 6, 6, 'But all of the ungodly shall be as thorns to be thrust away, because they can''t be taken with the hand,'),
  ('ea54fb24-0032-5237-ae6f-17aea376b99d', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 7, 7, 'But the man who touches them must be armed with iron and the staff of a spear. They shall be utterly burned with fire in their place."'),
  ('049daaa2-6c1a-5b38-aa6f-c02ef35bf80c', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 8, 8, 'These are the names of the mighty men whom David had: Josheb Basshebeth a Tahchemonite, chief of the captains; the same was Adino the Eznite, against eight hundred slain at one time.'),
  ('a3ac54f1-7f71-51e5-ad11-ba8e9a8cfc5e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 9, 9, 'After him was Eleazar the son of Dodai the son of an Ahohite, one of the three mighty men with David, when they defied the Philistines who were there gathered together to battle, and the men of Israel were gone away.'),
  ('cc175a46-7d85-58ee-ac95-d2815cc37a4f', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 10, 10, 'He arose, and struck the Philistines until his hand was weary, and his hand froze to the sword; and Yahweh worked a great victory that day; and the people returned after him only to take spoil.'),
  ('a12d3ccd-25c8-55fc-a427-fa24ae9e1b23', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 11, 11, 'After him was Shammah the son of Agee a Hararite. The Philistines were gathered together into a troop, where there was a plot of ground full of lentils; and the people fled from the Philistines.'),
  ('65e014f6-61b8-5a66-ac84-9a3cacba3aad', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 12, 12, 'But he stood in the midst of the plot, and defended it, and killed the Philistines; and Yahweh worked a great victory.'),
  ('961f4a87-fa20-521f-a367-f769f86e84a5', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 13, 13, 'Three of the thirty chief men went down, and came to David in the harvest time to the cave of Adullam; and the troop of the Philistines was encamped in the valley of Rephaim.'),
  ('d1ced924-3fca-58a9-a616-f3f9573da6a3', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 14, 14, 'David was then in the stronghold; and the garrison of the Philistines was then in Bethlehem.'),
  ('9f062a3e-26b0-5d06-a410-1991bbd240b2', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 15, 15, 'David longed, and said, "Oh that one would give me water to drink of the well of Bethlehem, which is by the gate!"'),
  ('3ec37228-2c7e-5e5d-ab34-a38ad8ec723d', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 16, 16, 'The three mighty men broke through the army of the Philistines, and drew water out of the well of Bethlehem, that was by the gate, and took it, and brought it to David: but he would not drink of it, but poured it out to Yahweh.'),
  ('5e90d159-636d-555e-a44a-005d1e49271c', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 17, 17, 'He said, "Be it far from me, Yahweh, that I should do this! Isn''t it the blood of the men who went in jeopardy of their lives?" Therefore he would not drink it. The three mighty men did these things.'),
  ('f84e268f-813a-59c2-a63f-c0dd5f6da490', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 18, 18, 'Abishai, the brother of Joab, the son of Zeruiah, was chief of the three. He lifted up his spear against three hundred and killed them, and had a name among the three.'),
  ('b865830b-8508-5a2d-ab4d-7aa5c235bc68', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 19, 19, 'Wasn''t he most honorable of the three? therefore he was made their captain: however he didn''t attain to the [first] three.'),
  ('5dbf826c-6f37-5f49-ad09-387e38d21e51', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 20, 20, 'Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done mighty deeds, he killed the two [sons of] Ariel of Moab: he went down also and killed a lion in the midst of a pit in time of snow.'),
  ('e9a7ee1a-49c2-596d-a8ab-62b29bb6fc7d', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 21, 21, 'He killed an Egyptian, a goodly man: and the Egyptian had a spear in his hand; but he went down to him with a staff, and plucked the spear out of the Egyptian''s hand, and killed him with his own spear.'),
  ('52485ecc-96d3-5d99-a353-2a6b6f55e8f4', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 22, 22, 'These things did Benaiah the son of Jehoiada, and had a name among the three mighty men.'),
  ('2cc10e37-498a-5075-a93f-26c0adb607c5', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 23, 23, 'He was more honorable than the thirty, but he didn''t attain to the [first] three. David set him over his guard.'),
  ('9df06784-9989-50fc-a7b5-ab071f6b1e24', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 24, 24, 'Asahel the brother of Joab was one of the thirty; Elhanan the son of Dodo of Bethlehem,'),
  ('ac1270df-40a2-5df0-ae7f-673390e7344e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 25, 25, 'Shammah the Harodite, Elika the Harodite,'),
  ('97f19019-25a8-56eb-a3a8-76de0184396e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 26, 26, 'Helez the Paltite, Ira the son of Ikkesh the Tekoite,'),
  ('38139598-2802-56f5-a693-88d1443d5dca', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 27, 27, 'Abiezer the Anathothite, Mebunnai the Hushathite,'),
  ('b66bb553-ba48-5e20-ab9d-ce54bfc4bc5e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 28, 28, 'Zalmon the Ahohite, Maharai the Netophathite,'),
  ('7fa340b0-da45-50e0-a62c-abae48cfc32d', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 29, 29, 'Heleb the son of Baanah the Netophathite, Ittai the son of Ribai of Gibeah of the children of Benjamin,'),
  ('db769404-5139-59b8-af6f-ad3316d46a8e', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 30, 30, 'Benaiah a Pirathonite, Hiddai of the brooks of Gaash.'),
  ('f7b4af07-dd61-5fef-a45c-a9f71cefad31', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 31, 31, 'Abialbon the Arbathite, Azmaveth the Barhumite,'),
  ('c328dc11-d250-5f0a-ab2b-468cc0dfb137', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 32, 32, 'Eliahba the Shaalbonite, the sons of Jashen, Jonathan,'),
  ('10a07699-adce-5697-a9eb-a9d843ffc314', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 33, 33, 'Shammah the Hararite, Ahiam the son of Sharar the Ararite,'),
  ('e9e7e8ea-b0ae-59da-aa0e-536f9e81b2b3', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 34, 34, 'Eliphelet the son of Ahasbai, the son of the Maacathite, Eliam the son of Ahithophel the Gilonite,'),
  ('08062809-fc98-58ad-a88f-238d792cea9f', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 35, 35, 'Hezro the Carmelite, Paarai the Arbite,'),
  ('f3a97699-7a0b-540c-ab44-4bdf71602bee', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 36, 36, 'Igal the son of Nathan of Zobah, Bani the Gadite,'),
  ('379d632e-03cb-5449-a60d-24b52da0ea03', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 37, 37, 'Zelek the Ammonite, Naharai the Beerothite, armor bearers to Joab the son of Zeruiah,'),
  ('197a1f66-7a32-5ccd-aa7c-cc879c5a72e4', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 38, 38, 'Ira the Ithrite, Gareb the Ithrite,'),
  ('60563f5a-01ca-5144-a3da-5305d6d28ad8', 'f29d4a2f-c6f8-5d3a-ac71-91fa41b00413', NULL, 39, 39, 'Uriah the Hittite: thirty-seven in all.'),
  ('026f3a26-18c5-522f-a87b-9203e0e2e961', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 1, 1, 'Again the anger of Yahweh was kindled against Israel, and he moved David against them, saying, "Go, number Israel and Judah."'),
  ('e067b46c-79a6-546f-a333-003d7f10b717', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 2, 2, 'The king said to Joab the captain of the army, who was with him, "Now go back and forth through all the tribes of Israel, from Dan even to Beersheba, and number the people, that I may know the sum of the people."'),
  ('0735375a-f7e2-5654-a92c-f27e81fd9cd7', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 3, 3, 'Joab said to the king, "Now may Yahweh your God add to the people, however many they may be, one hundred times; and may the eyes of my lord the king see it. But why does my lord the king delight in this thing?"'),
  ('5286f416-8ae1-522a-a984-43156104abe7', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 4, 4, 'Notwithstanding, the king''s word prevailed against Joab, and against the captains of the army. Joab and the captains of the army went out from the presence of the king, to number the people of Israel.'),
  ('48c28228-78d9-53b4-a65c-ac9ce8778817', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 5, 5, 'They passed over the Jordan, and encamped in Aroer, on the right side of the city that is in the middle of the valley of Gad, and to Jazer:'),
  ('af54f962-3018-5228-a6dd-00d2e6b6cae0', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 6, 6, 'then they came to Gilead, and to the land of Tahtim Hodshi; and they came to Dan Jaan, and around to Sidon,'),
  ('05b0a3e6-26f1-51e7-a476-d684cdc546c3', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 7, 7, 'and came to the stronghold of Tyre, and to all the cities of the Hivites, and of the Canaanites; and they went out to the south of Judah, at Beersheba.'),
  ('115d9504-0ef1-590c-ab7b-bf8666d3b3e2', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 8, 8, 'So when they had gone back and forth through all the land, they came to Jerusalem at the end of nine months and twenty days.'),
  ('6ba8a196-8467-5fb9-aa88-bbd0168762f9', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 9, 9, 'Joab gave up the sum of the numbering of the people to the king: and there were in Israel eight hundred thousand valiant men who drew the sword; and the men of Judah were five hundred thousand men.'),
  ('aad7b6e8-ef7b-592d-ad47-38b5cbf41e7c', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 10, 10, 'David''s heart struck him after that he had numbered the people. David said to Yahweh, "I have sinned greatly in that which I have done. But now, Yahweh, put away, I beg you, the iniquity of your servant; for I have done very foolishly."'),
  ('de904781-c49e-5242-a375-d22a5ef05faf', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 11, 11, 'When David rose up in the morning, the word of Yahweh came to the prophet Gad, David''s seer, saying,'),
  ('c208e5bf-297c-5226-a7af-bb4cd9c811b9', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 12, 12, '"Go and speak to David, ''Thus says Yahweh, "I offer you three things. Choose one of them, that I may do it to you."''"'),
  ('a0bb59d9-f74d-5c01-a0f0-df9d623f1bf1', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 13, 13, 'So Gad came to David, and told him, and said to him, "Shall seven years of famine come to you in your land? Or will you flee three months before your foes while they pursue you? Or shall there be three days'' pestilence in your land? Now answer, and consider what answer I shall return to him who sent me."'),
  ('206ba4fb-f4db-5d4f-a294-106ac2005ae7', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 14, 14, 'David said to Gad, "I am in distress. Let us fall now into the hand of Yahweh; for his mercies are great. Let me not fall into the hand of man."'),
  ('d7945f95-394b-5a49-ac6d-a8581ae1adb2', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 15, 15, 'So Yahweh sent a pestilence on Israel from the morning even to the appointed time; and there died of the people from Dan even to Beersheba seventy thousand men.'),
  ('aa9f8b73-15a5-55f3-ac1d-7babaf8dd83d', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 16, 16, 'When the angel stretched out his hand toward Jerusalem to destroy it, Yahweh relented of the disaster, and said to the angel who destroyed the people, "It is enough. Now stay your hand." The angel of Yahweh was by the threshing floor of Araunah the Jebusite.'),
  ('23353070-7f47-5050-ab03-66fdc211d2e3', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 17, 17, 'David spoke to Yahweh when he saw the angel who struck the people, and said, "Behold, I have sinned, and I have done perversely; but these sheep, what have they done? Please let your hand be against me, and against my father''s house."'),
  ('d51c4748-2175-52b5-ae3f-cbb333200855', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 18, 18, 'Gad came that day to David, and said to him, "Go up, build an altar to Yahweh on the threshing floor of Araunah the Jebusite."'),
  ('e2145247-2299-56b7-aec8-c01af988ccd9', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 19, 19, 'David went up according to the saying of Gad, as Yahweh commanded.'),
  ('85616b5b-3d81-5053-abb1-7a8abe638a74', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 20, 20, 'Araunah looked out, and saw the king and his servants coming on toward him. Then Araunah went out, and bowed himself before the king with his face to the ground.'),
  ('1db167d9-26b2-5290-a4e5-d948e2c571c4', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 21, 21, 'Araunah said, "Why has my lord the king come to his servant?" David said, "To buy your threshing floor, to build an altar to Yahweh, that the plague may be stopped from afflicting the people."'),
  ('aaafc1d7-f3ac-5022-a862-298938d6e644', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 22, 22, 'Araunah said to David, "Let my lord the king take and offer up what seems good to him. Behold, the cattle for the burnt offering, and the threshing instruments and the yokes of the oxen for the wood:'),
  ('8a1e706a-fe2f-5dc2-af36-103939dfca9d', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 23, 23, 'all this, king, does Araunah give to the king." Araunah said to the king, "May Yahweh your God accept you."'),
  ('03ae2408-df9a-54d8-a787-63bcf7284446', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 24, 24, 'The king said to Araunah, "No; but I will most certainly buy it from you for a price. I will not offer burnt offerings to Yahweh my God which cost me nothing." So David bought the threshing floor and the oxen for fifty shekels of silver.'),
  ('be8a15fc-56de-5364-adad-76994bd947df', '9d34d708-7de4-5a3f-a7d2-52c13b9ce8cf', NULL, 25, 25, 'David built an altar to Yahweh there, and offered burnt offerings and peace offerings. So Yahweh was entreated for the land, and the plague was stayed from Israel.'),
  ('19cfda58-e04c-5b4e-a76a-6e87406336a2', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 1, 1, 'Now king David was old and stricken in years; and they covered him with clothes, but he couldn''t keep warm.'),
  ('f6dc6741-5043-5c60-ad22-b752f428136e', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 2, 2, 'Therefore his servants said to him, "Let there be sought for my lord the king a young virgin: and let her stand before the king, and cherish him; and let her lie in your bosom, that my lord the king may keep warm."'),
  ('98f9304e-3238-5cd5-a7b3-85f119a37914', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 3, 3, 'So they sought for a beautiful young lady throughout all the borders of Israel, and found Abishag the Shunammite, and brought her to the king.'),
  ('a96d67a8-bb65-50e9-a5d2-18759a5237d7', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 4, 4, 'The young lady was very beautiful; and she cherished the king, and ministered to him; but the king didn''t know her intimately.'),
  ('795eee1c-76e7-5fc3-a5d9-83fa70c3af8f', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 5, 5, 'Then Adonijah the son of Haggith exalted himself, saying, "I will be king." Then he prepared him chariots and horsemen, and fifty men to run before him.'),
  ('fd802d12-b7f6-57ca-a325-ee2348bcd199', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 6, 6, 'His father had not displeased him at any time in saying, "Why have you done so?" and he was also a very handsome man; and he was born after Absalom.'),
  ('f2654630-f361-5daf-ac77-2fd7d8ce31c1', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 7, 7, 'He conferred with Joab the son of Zeruiah, and with Abiathar the priest: and they following Adonijah helped him.'),
  ('4e73ba20-b814-567e-a168-51bc3b313855', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 8, 8, 'But Zadok the priest, and Benaiah the son of Jehoiada, and Nathan the prophet, and Shimei, and Rei, and the mighty men who belonged to David, were not with Adonijah.'),
  ('11def70c-38ad-51f9-a7cd-7af75e7e4027', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 9, 9, 'Adonijah killed sheep and cattle and fatlings by the stone of Zoheleth, which is beside En Rogel; and he called all his brothers, the king''s sons, and all the men of Judah, the king''s servants:'),
  ('823d7e2a-fbad-5b13-a5aa-2c480dc3e3f8', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 10, 10, 'but Nathan the prophet, and Benaiah, and the mighty men, and Solomon his brother, he didn''t call.'),
  ('0789e5b8-163c-569e-a4a2-15aae51dc383', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 11, 11, 'Then Nathan spoke to Bathsheba the mother of Solomon, saying, "Haven''t you heard that Adonijah the son of Haggith reigns, and David our lord doesn''t know it?'),
  ('1c7cbb46-435e-52b0-a55f-ede78c0ef82e', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 12, 12, 'Now therefore come, please let me give you counsel, that you may save your own life, and the life of your son Solomon.'),
  ('a55ce3b7-5748-529e-acd3-be5df59a3648', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 13, 13, 'Go in to king David, and tell him, ''Didn''t you, my lord, king, swear to your handmaid, saying, Assuredly Solomon your son shall reign after me, and he shall sit on my throne? Why then does Adonijah reign?'''),
  ('c594cecd-daf1-5c90-a691-1fe09299d528', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 14, 14, 'Behold, while you yet talk there with the king, I also will come in after you, and confirm your words."'),
  ('0308247d-3bcc-50d2-a23d-d30992a9f704', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 15, 15, 'Bathsheba went in to the king into the room. The king was very old; and Abishag the Shunammite was ministering to the king.'),
  ('fde4a676-bb41-5677-a033-0686d87093d6', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 16, 16, 'Bathsheba bowed, and did obeisance to the king. The king said, "What would you like?"'),
  ('6b8a9df7-a127-511b-aed3-3e22ddcb36bd', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 17, 17, 'She said to him, "My lord, you swore by Yahweh your God to your handmaid, ''Assuredly Solomon your son shall reign after me, and he shall sit on my throne.'''),
  ('e025ad3d-84fe-5f8f-ae55-e72eae80b2b5', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 18, 18, 'Now, behold, Adonijah reigns; and you, my lord the king, don''t know it.'),
  ('d7b102c5-eb9c-5dda-a664-3116200bf840', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 19, 19, 'He has slain cattle and fatlings and sheep in abundance, and has called all the sons of the king, and Abiathar the priest, and Joab the captain of the army; but he hasn''t called Solomon your servant.'),
  ('93e1ec5b-b6be-57b6-a717-b9658047992f', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 20, 20, 'You, my lord the king, the eyes of all Israel are on you, that you should tell them who shall sit on the throne of my lord the king after him.'),
  ('aa03a882-88f1-5509-a960-a1db635e8459', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 21, 21, 'Otherwise it will happen, when my lord the king shall sleep with his fathers, that I and my son Solomon shall be counted offenders."'),
  ('ccd09ac3-9504-5b31-a576-3337e2eba54d', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 22, 22, 'Behold, while she yet talked with the king, Nathan the prophet came in.'),
  ('7409610c-4fd7-59a8-ad77-50a317f75ba5', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 23, 23, 'They told the king, saying, "Behold, Nathan the prophet!" When he had come in before the king, he bowed himself before the king with his face to the ground.'),
  ('be4222df-bcd2-52ca-a214-71e469ded6fa', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 24, 24, 'Nathan said, "My lord, king, have you said, ''Adonijah shall reign after me, and he shall sit on my throne?'''),
  ('83e31e76-e5ee-53b3-a86f-b002025f62ce', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 25, 25, 'For he is gone down this day, and has slain cattle and fatlings and sheep in abundance, and has called all the king''s sons, and the captains of the army, and Abiathar the priest. Behold, they are eating and drinking before him, and say, ''Long live king Adonijah!'''),
  ('8791b75c-445e-5cd2-a23c-534ccfd9907d', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 26, 26, 'But he hasn''t called me, even me your servant, and Zadok the priest, and Benaiah the son of Jehoiada, and your servant Solomon.'),
  ('0db9cfe1-19ec-5330-a501-2cd03b350f76', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 27, 27, 'Is this thing done by my lord the king, and you haven''t shown to your servants who should sit on the throne of my lord the king after him?"'),
  ('681dd91d-6159-5c82-a3dd-340eaa628c87', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 28, 28, 'Then king David answered, "Call to me Bathsheba." She came into the king''s presence, and stood before the king.'),
  ('0da391a7-7e04-54f0-a304-56c56a8c8b30', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 29, 29, 'The king swore, and said, "As Yahweh lives, who has redeemed my soul out of all adversity,'),
  ('ae6110e7-08b4-5b53-a19b-ad7867ad37f1', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 30, 30, 'most certainly as I swore to you by Yahweh, the God of Israel, saying, ''Assuredly Solomon your son shall reign after me, and he shall sit on my throne in my place;'' most certainly so will I do this day."'),
  ('1ef08561-b23e-524f-a054-214908b47745', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 31, 31, 'Then Bathsheba bowed with her face to the earth, and did obeisance to the king, and said, "Let my lord king David live forever!"'),
  ('75e5ef8f-ea51-5b33-a0f1-e5f596878c16', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 32, 32, 'King David said, "Call to me Zadok the priest, Nathan the prophet, and Benaiah the son of Jehoiada." They came before the king.'),
  ('df60e13b-f7b7-5d52-a044-4f20f3122c27', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 33, 33, 'The king said to them, "Take with you the servants of your lord, and cause Solomon my son to ride on my own mule, and bring him down to Gihon.'),
  ('e5ef055b-3b01-56fb-a7e8-79db94f88967', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 34, 34, 'Let Zadok the priest and Nathan the prophet anoint him there king over Israel. Blow the trumpet, and say, ''Long live king Solomon!'''),
  ('da252c22-c899-5251-a38d-5479fa259af2', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 35, 35, 'Then you shall come up after him, and he shall come and sit on my throne; for he shall be king in my place. I have appointed him to be prince over Israel and over Judah."'),
  ('380793e7-62ad-5237-acc0-149863bc7562', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 36, 36, 'Benaiah the son of Jehoiada answered the king, and said, "Amen. May Yahweh, the God of my lord the king, say so.'),
  ('b5e14929-2be5-5486-a410-cc0bbf8409f4', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 37, 37, 'As Yahweh has been with my lord the king, even so may he be with Solomon, and make his throne greater than the throne of my lord king David."'),
  ('eed46386-1e97-5bbb-a492-2350fd40498d', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 38, 38, 'So Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada, and the Cherethites and the Pelethites, went down, and caused Solomon to ride on king David''s mule, and brought him to Gihon.'),
  ('6b13f7ce-18f5-5668-ab18-5d03e200ecb4', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 39, 39, 'Zadok the priest took the horn of oil out of the Tent, and anointed Solomon. They blew the trumpet; and all the people said, "Long live king Solomon!"'),
  ('5b4dc451-bd18-54fd-ac75-24f612981b32', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 40, 40, 'All the people came up after him, and the people piped with pipes, and rejoiced with great joy, so that the earth shook with the sound of them.'),
  ('287d68d9-9192-5f0b-a77a-8cf1ff16ee45', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 41, 41, 'Adonijah and all the guests who were with him heard it as they had made an end of eating. When Joab heard the sound of the trumpet, he said, "Why is this noise of the city being in an uproar?"'),
  ('144236ae-933f-5c0c-aa2f-876efdbc946d', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 42, 42, 'While he yet spoke, behold, Jonathan the son of Abiathar the priest came: and Adonijah said, "Come in; for you are a worthy man, and bring good news."'),
  ('2da40848-3ace-5675-a471-bc5cac34e198', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 43, 43, 'Jonathan answered Adonijah, "Most certainly our lord king David has made Solomon king.'),
  ('bcb3c5ec-f2ba-54b9-a8d6-8f9f57f84999', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 44, 44, 'The king has sent with him Zadok the priest, Nathan the prophet, Benaiah the son of Jehoiada, and the Cherethites and the Pelethites; and they have caused him to ride on the king''s mule.'),
  ('8e7d72ba-1d5e-5a9d-a8ae-6c58653dcfd5', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 45, 45, 'Zadok the priest and Nathan the prophet have anointed him king in Gihon. They have come up from there rejoicing, so that the city rang again. This is the noise that you have heard.'),
  ('6588b554-0daf-5d26-a8fc-b35be04076d1', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 46, 46, 'Also, Solomon sits on the throne of the kingdom.'),
  ('0e0954ed-8abd-5416-ac07-9f69ede4f7bb', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 47, 47, 'Moreover the king''s servants came to bless our lord king David, saying, ''May your God make the name of Solomon better than your name, and make his throne greater than your throne;'' and the king bowed himself on the bed.'),
  ('5a0d3324-0d9d-55a1-a342-22ea8048a7d7', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 48, 48, 'Also thus said the king, ''Blessed be Yahweh, the God of Israel, who has given one to sit on my throne this day, my eyes even seeing it.''"'),
  ('19b83355-56b7-5721-ae69-8face2b6420b', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 49, 49, 'All the guests of Adonijah were afraid, and rose up, and each man went his way.'),
  ('588ce739-f077-536e-aaaa-0def93902e45', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 50, 50, 'Adonijah feared because of Solomon; and he arose, and went, and caught hold on the horns of the altar.'),
  ('c2450fdd-2d57-547b-abc1-92e70c2c8f9a', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 51, 51, 'It was told Solomon, saying, "Behold, Adonijah fears king Solomon; for, behold, he has laid hold on the horns of the altar, saying, ''Let king Solomon swear to me first that he will not kill his servant with the sword.''"'),
  ('f1e01a0c-f3cd-5ca1-adc1-d74cec7884c1', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 52, 52, 'Solomon said, "If he shows himself a worthy man, not a hair of him shall fall to the earth; but if wickedness be found in him, he shall die."'),
  ('bc85d45e-d7f7-514d-ad37-7b784e31438b', '477775d6-5439-5a8d-a745-3cdf2e316331', NULL, 53, 53, 'So king Solomon sent, and they brought him down from the altar. He came and did obeisance to king Solomon; and Solomon said to him, "Go to your house."'),
  ('a6a983ef-bb2f-575b-a95c-b5e87478a9c3', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 1, 1, 'Now the days of David drew near that he should die; and he commanded Solomon his son, saying,'),
  ('9fe71b01-b93a-5a5c-a222-d644e5504996', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 2, 2, '"I am going the way of all the earth. You be strong therefore, and show yourself a man;'),
  ('9333d787-976c-5702-acd4-d8b93b466e23', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 3, 3, 'and keep the instruction of Yahweh your God, to walk in his ways, to keep his statutes, his commandments, his ordinances, and his testimonies, according to that which is written in the law of Moses, that you may prosper in all that you do, and wherever you turn yourself.'),
  ('81cf321c-af18-5740-affc-50343c274ad2', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 4, 4, 'That Yahweh may establish his word which he spoke concerning me, saying, ''If your children take heed to their way, to walk before me in truth with all their heart and with all their soul, there shall not fail you,'' he said, ''a man on the throne of Israel.'''),
  ('dccd3bd8-c7e2-55f5-af0c-c6f3ace5168e', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 5, 5, '"Moreover you know also what Joab the son of Zeruiah did to me, even what he did to the two captains of the armies of Israel, to Abner the son of Ner, and to Amasa the son of Jether, whom he killed, and shed the blood of war in peace, and put the blood of war on his sash that was about his waist, and in his shoes that were on his feet.'),
  ('51a5d17d-fbf5-5b9c-a24c-2f3a6fc66876', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 6, 6, 'Do therefore according to your wisdom, and don''t let his gray head go down to Sheol in peace.'),
  ('84de0c28-14ba-5b30-a06b-75b62e6e4839', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 7, 7, 'But show kindness to the sons of Barzillai the Gileadite, and let them be of those who eat at your table; for so they came to me when I fled from Absalom your brother.'),
  ('c30ea5f4-5c46-521e-ae3f-0ecf456db1ca', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 8, 8, '"Behold, there is with you Shimei the son of Gera, the Benjamite, of Bahurim, who cursed me with a grievous curse in the day when I went to Mahanaim; but he came down to meet me at the Jordan, and I swore to him by Yahweh, saying, ''I will not put you to death with the sword.'''),
  ('e255218a-b76f-5aa2-a261-b5022527de8d', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 9, 9, 'Now therefore don''t hold him guiltless, for you are a wise man; and you will know what you ought to do to him, and you shall bring his gray head down to Sheol with blood."'),
  ('3ddc6df1-1a7e-5864-ac6e-6303e9496b28', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 10, 10, 'David slept with his fathers, and was buried in the city of David.'),
  ('e38336bb-432b-563e-a49e-1aa1968aa776', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 11, 11, 'The days that David reigned over Israel were forty years; seven years reigned he in Hebron, and thirty-three years reigned he in Jerusalem.'),
  ('dba50e9a-35e7-5757-a33f-b028ea864880', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 12, 12, 'Solomon sat on the throne of David his father; and his kingdom was firmly established.'),
  ('d3cc769a-98be-5344-a27c-f2dd6d392668', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 13, 13, 'Then Adonijah the son of Haggith came to Bathsheba the mother of Solomon. She said, "Do you come peaceably?" He said, "Peaceably.'),
  ('eb35ed2d-18f3-5eca-ab44-c8b42c5d7870', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 14, 14, 'He said moreover, I have something to tell you." She said, "Say on."'),
  ('1918d626-0779-52b9-a13d-c868f03f061b', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 15, 15, 'He said, "You know that the kingdom was mine, and that all Israel set their faces on me, that I should reign. However the kingdom is turned around, and has become my brother''s; for it was his from Yahweh.'),
  ('aa3c53ca-16f5-5333-a512-6708c06eec2f', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 16, 16, 'Now I ask one petition of you. Don''t deny me." She said to him, "Say on."'),
  ('b775abbe-a341-5e9f-a508-63b71a250432', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 17, 17, 'He said, "Please speak to Solomon the king (for he will not tell you ''no''), that he give me Abishag the Shunammite as wife."'),
  ('f7398620-2675-5cc4-aa14-7a4b4c87b365', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 18, 18, 'Bathsheba said, "Alright. I will speak for you to the king."'),
  ('0e2fabd8-cc04-5fbf-af95-ea440f598f4d', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 19, 19, 'Bathsheba therefore went to king Solomon, to speak to him for Adonijah. The king rose up to meet her, and bowed himself to her, and sat down on his throne, and caused a throne to be set for the king''s mother; and she sat on his right hand.'),
  ('436ab027-86ae-529d-afe6-83f1372a8bf5', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 20, 20, 'Then she said, "I ask one small petition of you; don''t deny me." The king said to her, "Ask on, my mother; for I will not deny you."'),
  ('cc65bc5d-5d80-5d4c-aed9-07ad13ee11cc', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 21, 21, 'She said, "Let Abishag the Shunammite be given to Adonijah your brother as wife."'),
  ('9dfd8e0f-122c-5470-adf8-bbc536831632', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 22, 22, 'King Solomon answered his mother, "Why do you ask Abishag the Shunammite for Adonijah? Ask for him the kingdom also; for he is my elder brother; even for him, and for Abiathar the priest, and for Joab the son of Zeruiah."'),
  ('e5bdce62-dbd0-5dec-ae42-062c0a4a737f', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 23, 23, 'Then king Solomon swore by Yahweh, saying, "God do so to me, and more also, if Adonijah has not spoken this word against his own life.'),
  ('acd365ef-a497-56fc-a9d3-4e257c0664cb', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 24, 24, 'Now therefore as Yahweh lives, who has established me, and set me on the throne of David my father, and who has made me a house, as he promised, surely Adonijah shall be put to death this day."'),
  ('06e316ad-ef71-5da3-afd3-d1748ee315c7', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 25, 25, 'King Solomon sent by Benaiah the son of Jehoiada; and he fell on him, so that he died.'),
  ('adc78e47-1fee-54a0-afdf-5a620af242d7', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 26, 26, 'To Abiathar the priest the king said, "Go to Anathoth, to your own fields; for you are worthy of death. But I will not at this time put you to death, because you bore the ark of the Lord Yahweh before David my father, and because you were afflicted in all in which my father was afflicted."'),
  ('91251907-00e7-586a-afee-9bb1d5066b78', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 27, 27, 'So Solomon thrust out Abiathar from being priest to Yahweh, that he might fulfill the word of Yahweh, which he spoke concerning the house of Eli in Shiloh.'),
  ('d1568082-1489-5293-a7e5-3bfebcadbf99', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 28, 28, 'The news came to Joab; for Joab had turned after Adonijah, though he didn''t turn after Absalom. Joab fled to the Tent of Yahweh, and caught hold on the horns of the altar.'),
  ('f947a637-0b0a-5b4b-a188-8244372de8ee', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 29, 29, 'It was told king Solomon, "Joab has fled to the Tent of Yahweh, and behold, he is by the altar." Then Solomon sent Benaiah the son of Jehoiada, saying, "Go, fall on him."'),
  ('220cdd95-7ae4-5b53-a784-403dac40b711', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 30, 30, 'Benaiah came to the Tent of Yahweh, and said to him, "Thus says the king, ''Come forth!''" He said, "No; but I will die here." Benaiah brought the king word again, saying, "Thus said Joab, and thus he answered me."'),
  ('a68f5b8a-65e9-5590-a2c7-c2463a37b999', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 31, 31, 'The king said to him, "Do as he has said, and fall on him, and bury him; that you may take away the blood, which Joab shed without cause, from me and from my father''s house.'),
  ('2a2f3766-0a9e-5049-ad9c-12face551452', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 32, 32, 'Yahweh will return his blood on his own head, because he fell on two men more righteous and better than he, and killed them with the sword, and my father David didn''t know it: Abner the son of Ner, captain of the army of Israel, and Amasa the son of Jether, captain of the army of Judah.'),
  ('e1c7e0cd-3bbb-5df5-ae2c-78203333700f', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 33, 33, 'So shall their blood return on the head of Joab, and on the head of his seed forever. But to David, and to his seed, and to his house, and to his throne, there shall be peace forever from Yahweh."'),
  ('c2620fba-b06c-5bf6-a563-da943a30d50d', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 34, 34, 'Then Benaiah the son of Jehoiada went up, and fell on him, and killed him; and he was buried in his own house in the wilderness.'),
  ('263b4d66-032e-5ff0-abb2-7223402713f7', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 35, 35, 'The king put Benaiah the son of Jehoiada in his place over the army; and Zadok the priest did the king put in the place of Abiathar.'),
  ('3747c663-248e-550d-ab0c-f9a587935d60', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 36, 36, 'The king sent and called for Shimei, and said to him, "Build yourself a house in Jerusalem, and dwell there, and don''t go out from there anywhere.'),
  ('ffdfcda9-7ba4-5e67-a97e-1f618dcddf29', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 37, 37, 'For on the day you go out, and pass over the brook Kidron, know for certain that you shall surely die: your blood shall be on your own head."'),
  ('4c42a5da-f93f-5f9b-aaa9-731341b00c01', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 38, 38, 'Shimei said to the king, "The saying is good. As my lord the king has said, so will your servant do." Shimei lived in Jerusalem many days.'),
  ('cbbff035-de95-57a0-ade4-7396a4ff60d6', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 39, 39, 'It happened at the end of three years, that two of the servants of Shimei ran away to Achish, son of Maacah, king of Gath. They told Shimei, saying, "Behold, your servants are in Gath."'),
  ('0cdfb0cb-0565-527b-a0df-d0c06a5a5d88', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 40, 40, 'Shimei arose, and saddled his donkey, and went to Gath to Achish, to seek his servants; and Shimei went, and brought his servants from Gath.'),
  ('ac9b50ea-599a-58bc-ab2f-4d6611e6ce35', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 41, 41, 'It was told Solomon that Shimei had gone from Jerusalem to Gath, and was come again.'),
  ('24856d2e-8ff1-56b3-aa7b-a55c9ebb5829', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 42, 42, 'The king sent and called for Shimei, and said to him, "Didn''t I adjure you by Yahweh, and warn you, saying, ''Know for certain, that on the day you go out, and walk abroad any where, you shall surely die?'' You said to me, ''The saying that I have heard is good.'''),
  ('62ae0859-143b-5860-a525-cc836419dfbb', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 43, 43, 'Why then have you not kept the oath of Yahweh, and the commandment that I have instructed you with?"'),
  ('e31246f6-54fa-514a-ae31-dce504c55160', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 44, 44, 'The king said moreover to Shimei, "You know all the wickedness which your heart is privy to, that you did to David my father. Therefore Yahweh shall return your wickedness on your own head.'),
  ('fccab688-426f-55b2-a921-e72514c04b59', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 45, 45, 'But king Solomon shall be blessed, and the throne of David shall be established before Yahweh forever."'),
  ('9cae1d75-ca5f-5c77-a6b3-d9d6891410e5', 'b745ae02-0002-5993-ad7d-0ac523a41d10', NULL, 46, 46, 'So the king commanded Benaiah the son of Jehoiada; and he went out, and fell on him, so that he died. The kingdom was established in the hand of Solomon.'),
  ('4687f955-5c9f-5e4b-a02f-a0d426e64621', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 1, 1, 'Solomon made affinity with Pharaoh king of Egypt, and took Pharaoh''s daughter, and brought her into the city of David, until he had made an end of building his own house, and the house of Yahweh, and the wall of Jerusalem all around.'),
  ('57778934-159b-5a16-a408-c4855eb4e60f', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 2, 2, 'Only the people sacrificed in the high places, because there was no house built for the name of Yahweh until those days.'),
  ('86cbd28b-92dd-5a2b-a4cd-f3e89a6a7a14', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 3, 3, 'Solomon loved Yahweh, walking in the statutes of David his father: only he sacrificed and burnt incense in the high places.'),
  ('9798c7b5-7b2b-578c-a5c2-6ba89bdac722', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 4, 4, 'The king went to Gibeon to sacrifice there; for that was the great high place: a thousand burnt offerings did Solomon offer on that altar.'),
  ('1e5f5e02-17b8-554c-ace5-02416ef4dc4e', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 5, 5, 'In Gibeon Yahweh appeared to Solomon in a dream by night; and God said, "Ask what I shall give you."'),
  ('674771dc-f29c-5b19-a09e-85ca8343d73a', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 6, 6, 'Solomon said, "You have shown to your servant David my father great loving kindness, according as he walked before you in truth, and in righteousness, and in uprightness of heart with you. You have kept for him this great loving kindness, that you have given him a son to sit on his throne, as it is this day.'),
  ('626fcc74-cff5-58a2-a5d0-64ad762dcda2', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 7, 7, 'Now, Yahweh my God, you have made your servant king instead of David my father. I am but a little child. I don''t know how to go out or come in.'),
  ('98afe16c-e214-569c-a9ab-0ded3ed6d571', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 8, 8, 'Your servant is in the midst of your people which you have chosen, a great people, that can''t be numbered nor counted for multitude.'),
  ('88bc4cfe-d757-5fb1-a177-30373d28f314', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 9, 9, 'Give your servant therefore an understanding heart to judge your people, that I may discern between good and evil; for who is able to judge this your great people?"'),
  ('af8445b1-ee65-5f03-a411-9aa9b67c75de', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 10, 10, 'The speech pleased the Lord, that Solomon had asked this thing.'),
  ('1b54d7da-c13e-57c0-a1d0-c3cc75a021db', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 11, 11, 'God said to him, "Because you have asked this thing, and have not asked for yourself long life, neither have asked riches for yourself, nor have asked the life of your enemies, but have asked for yourself understanding to discern justice;'),
  ('2a049b71-74ea-502f-ae80-202e4db517d6', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 12, 12, 'behold, I have done according to your word. Behold, I have given you a wise and an understanding heart; so that there has been none like you before you, neither after you shall any arise like you.'),
  ('4718fd02-de52-5cbe-a001-681caec35b39', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 13, 13, 'I have also given you that which you have not asked, both riches and honor, so that there shall not be any among the kings like you, all your days.'),
  ('988f2cfc-7b5a-5ada-ab0f-b91e983dae69', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 14, 14, 'If you will walk in my ways, to keep my statutes and my commandments, as your father David walked, then I will lengthen your days."'),
  ('21e73527-932e-5674-a0d5-62b61c5e68cb', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 15, 15, 'Solomon awoke; and behold, it was a dream. Then he came to Jerusalem, and stood before the ark of the covenant of Yahweh, and offered up burnt offerings, offered peace offerings, and made a feast to all his servants.'),
  ('0caf2195-2d89-56d7-af7f-1001f2cce099', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 16, 16, 'Then two women who were prostitutes came to the king, and stood before him.'),
  ('6111ee69-9aab-5bab-a1e2-a5ed13e959ce', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 17, 17, 'The one woman said, "Oh, my lord, I and this woman dwell in one house. I delivered a child with her in the house.'),
  ('bdb87e3c-73a6-5686-ad1d-961acdcf981a', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 18, 18, 'It happened the third day after I delivered, that this woman delivered also. We were together. There was no stranger with us in the house, just us two in the house.'),
  ('82e369ad-fafe-5863-a4bd-a03faeebba06', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 19, 19, 'This woman''s child died in the night, because she lay on it.'),
  ('530d8f97-5eea-534b-a189-5afa0f5e99a4', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 20, 20, 'She arose at midnight, and took my son from beside me, while your handmaid slept, and laid it in her bosom, and laid her dead child in my bosom.'),
  ('ea7f0271-6533-5286-ae9c-88bcad4f0f6e', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 21, 21, 'When I rose in the morning to nurse my child, behold, it was dead; but when I had looked at it in the morning, behold, it was not my son, whom I bore."'),
  ('d9e72662-92c2-5d66-a25c-f720c12f3472', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 22, 22, 'The other woman said, "No; but the living is my son, and the dead is your son." This said, "No; but the dead is your son, and the living is my son." Thus they spoke before the king.'),
  ('8a3c5a2d-339b-5d55-a4b1-c7a7baf88569', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 23, 23, 'Then the king said, "The one says, ''This is my son who lives, and your son is the dead;'' and the other says, ''No; but your son is the dead one, and my son is the living one.''"'),
  ('bda962c4-e0d0-5542-a9f4-2be7c462ab17', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 24, 24, 'The king said, "Get me a sword." They brought a sword before the king.'),
  ('72c5a2ab-6020-5e25-abec-9dfef52b1ebb', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 25, 25, 'The king said, "Divide the living child in two, and give half to the one, and half to the other."'),
  ('4f291518-c144-5b44-ab31-3b08e49513c8', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 26, 26, 'Then the woman whose the living child was spoke to the king, for her heart yearned over her son, and she said, "Oh, my lord, give her the living child, and in no way kill it!" But the other said, "It shall be neither mine nor yours. Divide it."'),
  ('41fe6450-e7c1-56e6-a706-2adb6145f3d6', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 27, 27, 'Then the king answered, "Give her the living child, and in no way kill it. She is its mother."'),
  ('2d282de0-97e0-5fdc-a116-fd24f9bfcc7c', '31eefdf5-ba63-5e7d-acc2-d6217b6ef254', NULL, 28, 28, 'All Israel heard of the judgment which the king had judged; and they feared the king: for they saw that the wisdom of God was in him, to do justice.'),
  ('3baba866-373d-5f4c-a346-98341b81134d', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 1, 1, 'King Solomon was king over all Israel.'),
  ('786817a1-e716-5112-a20f-c0cefdaaac07', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 2, 2, 'These were the princes whom he had: Azariah the son of Zadok, the priest;'),
  ('e7da7a58-55c4-5569-af53-45b052e07507', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 3, 3, 'Elihoreph and Ahijah, the sons of Shisha, scribes; Jehoshaphat the son of Ahilud, the recorder;'),
  ('396892ba-c709-54ac-a195-9dc7b82a6052', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 4, 4, 'and Benaiah the son of Jehoiada was over the army; and Zadok and Abiathar were priests;'),
  ('4a43470e-28d6-5d48-a0a4-457847571bf9', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 5, 5, 'and Azariah the son of Nathan was over the officers; and Zabud the son of Nathan was chief minister, [and] the king''s friend;'),
  ('c500701c-5a1e-519b-ab3e-2bd190c30d1a', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 6, 6, 'and Ahishar was over the household; and Adoniram the son of Abda was over the men subject to forced labor.'),
  ('ab28f176-4ead-5f79-a99f-dabfb69dadb8', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 7, 7, 'Solomon had twelve officers over all Israel, who provided food for the king and his household: each man had to make provision for a month in the year.'),
  ('d3a77c56-e8a7-5e0f-aaa6-eef734a4a805', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 8, 8, 'These are their names: Ben Hur, in the hill country of Ephraim;'),
  ('01403519-4737-5791-a7cf-a6ac4154ca9d', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 9, 9, 'Ben Deker, in Makaz, and in Shaalbim, and Beth Shemesh, and Elon Beth Hanan;'),
  ('ebb01f28-dd37-5661-a118-7b036aeda9f2', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 10, 10, 'Ben Hesed, in Arubboth (to him [pertained] Socoh, and all the land of Hepher);'),
  ('f0616684-a1d2-56f5-a66d-855bd2c00f2d', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 11, 11, 'Ben Abinadab, in all the height of Dor (he had Taphath the daughter of Solomon as wife);'),
  ('59e7325a-f781-58ea-a577-a0281aa9ea2c', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 12, 12, 'Baana the son of Ahilud, in Taanach and Megiddo, and all Beth Shean which is beside Zarethan, beneath Jezreel, from Beth Shean to Abel Meholah, as far as beyond Jokmeam;'),
  ('1dd98533-610d-53c2-a884-8ab2156859f1', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 13, 13, 'Ben Geber, in Ramoth Gilead (to him [pertained] the towns of Jair the son of Manasseh, which are in Gilead; [even] to him [pertained] the region of Argob, which is in Bashan, sixty great cities with walls and bronze bars);'),
  ('47e00b78-3497-5187-a061-4da419eb6fe4', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 14, 14, 'Ahinadab the son of Iddo, in Mahanaim;'),
  ('2d69d805-c0f4-507c-a676-8b5eb4190c26', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 15, 15, 'Ahimaaz, in Naphtali (he also took Basemath the daughter of Solomon as wife);'),
  ('9ac783be-c1e2-5b1d-a14b-568e6beb05c9', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 16, 16, 'Baana the son of Hushai, in Asher and Bealoth;')
